// ==================== MANUAL FEE STRUCTURE ASSIGNMENT ====================
// ==================== MANUAL FEE STRUCTURE ASSIGNMENT (FULLY FIXED) ====================
// Version: 2.0 - Year-aware, with proper error handling and feedback

async function assignFeeStructureManually(studentId) {
    console.log('📌 Manual fee assignment for student:', studentId);

    // Check if there's already a modal open
    if (document.getElementById('assignFeeModal')) {
        document.getElementById('assignFeeModal').remove();
    }

    try {
        // Show loading indicator
        const loadingHtml = `
            <div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50" id="assignFeeLoading">
                <div class="bg-white rounded-2xl p-8 flex flex-col items-center">
                    <div class="loading-spinner mb-4"></div>
                    <p class="text-gray-600">Loading fee structures...</p>
                </div>
            </div>
        `;
        document.body.insertAdjacentHTML('beforeend', loadingHtml);

        // Fetch all required data
        const [studentRes, feeStructuresRes, assignmentsRes, settingsRes, classesRes] = await Promise.all([
            fetch(`/api/students/${studentId}`).catch(e => { console.error('Student fetch error:', e); throw new Error('Failed to load student data: ' + e.message); }),
            fetch('/api/fee/structures').catch(e => { console.error('Fee structures fetch error:', e); throw new Error('Failed to load fee structures: ' + e.message); }),
            fetch('/api/student-fee-assignments').catch(e => { console.error('Fee assignments fetch error:', e); throw new Error('Failed to load fee assignments: ' + e.message); }),
            fetch('/api/academic/settings').catch(e => { console.error('Academic settings fetch error:', e); throw new Error('Failed to load academic settings: ' + e.message); }),
            fetch('/api/school/classes').catch(e => { console.error('Classes fetch error:', e); throw new Error('Failed to load classes: ' + e.message); })
        ]);

        // Check responses
        if (!studentRes.ok) throw new Error('Failed to load student (status: ' + studentRes.status + ')');
        if (!feeStructuresRes.ok) throw new Error('Failed to load fee structures (status: ' + feeStructuresRes.status + ')');
        if (!assignmentsRes.ok) throw new Error('Failed to load fee assignments (status: ' + assignmentsRes.status + ')');
        if (!settingsRes.ok) throw new Error('Failed to load academic settings (status: ' + settingsRes.status + ')');
        if (!classesRes.ok) throw new Error('Failed to load classes (status: ' + classesRes.status + ')');

        const student = await studentRes.json();
        const feeStructures = await feeStructuresRes.json();
        const feeAssignments = await assignmentsRes.json();
        const settings = await settingsRes.json();
        const classes = await classesRes.json();

        // Get current academic year
        const currentYear = settings.currentYear || settings.currentAcademicYear || new Date().getFullYear();
        const currentTerm = settings.currentTerm || 1;

        console.log('📅 Current academic year:', currentYear);
        console.log('👤 Student loaded:', student.firstName, student.lastName);

        // Find existing assignment for the current year
        const currentAssignment = feeAssignments.find(a =>
            a && a.studentId === studentId && a.academicYear === currentYear
        ) || {};

        console.log('📋 Current assignment:', currentAssignment);

        // Get current fee structure name for display
        const currentFeeStructure = feeStructures.find(f => f.id === currentAssignment.feeStructureId);
        const currentFeeStructureName = currentFeeStructure ? currentFeeStructure.name : 'Not Assigned';

        // Get student's current class
        const studentClass = classes.find(c => c.id === student.currentClassId);
        const className = studentClass ? studentClass.name : 'Unknown';

        // Remove loading indicator
        const loadingModal = document.getElementById('assignFeeLoading');
        if (loadingModal) loadingModal.remove();

        // Build fee structure options with grouping by level
        const levels = ['Nursery', 'LowerPrimary', 'UpperPrimary'];
        let feeStructureOptions = '';

        for (const level of levels) {
            const levelStructures = feeStructures.filter(f =>
                f && f.isActive !== false && f.level === level
            );

            if (levelStructures.length === 0) continue;

            const levelLabel = level === 'Nursery' ? 'Nursery' :
                              level === 'LowerPrimary' ? 'Lower Primary' : 'Upper Primary';

            feeStructureOptions += `<optgroup label="${levelLabel}">`;

            for (const fs of levelStructures) {
                const isSelected = currentAssignment.feeStructureId === fs.id;
                const tuition = fs.tuition || 0;
                const isBoarding = fs.name.toLowerCase().includes('boarding');
                const typeLabel = isBoarding ? '🏠 Boarding' : '☀️ Day';
                feeStructureOptions += `
                    <option value="${fs.id}" ${isSelected ? 'selected' : ''}>
                        ${fs.name} - UGX ${tuition.toLocaleString()}/term ${typeLabel}
                    </option>
                `;
            }

            feeStructureOptions += `</optgroup>`;
        }

        // Build bursary options
        let bursaryOptions = '';
        const bursariesRes2 = await fetch('/api/fee/bursaries').catch(() => ({ ok: false, json: async () => [] }));
        const feeBursaries = bursariesRes2.ok ? await bursariesRes2.json() : [];

        bursaryOptions = `
            <option value="">None</option>
            ${feeBursaries.filter(b => b && b.isActive !== false).map(b => `
                <option value="${b.id}" ${currentAssignment.bursaryId === b.id ? 'selected' : ''}>
                    ${b.name} (${b.type === 'percentage' ? b.value + '% off' : 'UGX ' + b.value.toLocaleString() + ' off'})
                </option>
            `).join('')}
            <option value="custom" ${student.customBursary && student.customBursary.amount > 0 ? 'selected' : ''}>
                ✏️ Custom Bursary (Enter Amount)
            </option>
        `;

        // Check if student has custom bursary
        const hasCustomBursary = student.customBursary && student.customBursary.amount > 0;
        const customBursaryAmount = hasCustomBursary ? student.customBursary.amount : '';

        // Build the modal HTML
        const modalHtml = `
            <div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 overflow-y-auto" id="assignFeeModal">
                <div class="bg-white rounded-2xl p-6 max-w-2xl w-full mx-4 my-8 max-h-[90vh] overflow-y-auto">
                    <div class="flex justify-between items-center mb-4 pb-3 border-b sticky top-0 bg-white z-10">
                        <h2 class="text-xl font-bold flex items-center gap-2">
                            <i class="fas fa-money-bill-wave text-green-600"></i>
                            Assign Fee Structure
                        </h2>
                        <button onclick="document.getElementById('assignFeeModal').remove()" 
                                class="text-gray-500 hover:text-gray-700 text-2xl" id="closeAssignModalBtn">
                            &times;
                        </button>
                    </div>

                    <div class="mb-4 bg-gray-50 rounded-lg p-4">
                        <div class="grid grid-cols-2 gap-3 text-sm">
                            <div>
                                <span class="text-gray-500">Student:</span>
                                <span class="font-semibold">${student.firstName || ''} ${student.lastName || ''}</span>
                            </div>
                            <div>
                                <span class="text-gray-500">Admission:</span>
                                <span class="font-semibold">${student.admissionNumber || 'N/A'}</span>
                            </div>
                            <div>
                                <span class="text-gray-500">Current Class:</span>
                                <span class="font-semibold">${className}</span>
                            </div>
                            <div>
                                <span class="text-gray-500">Academic Year:</span>
                                <span class="font-semibold text-blue-600">${currentYear}</span>
                            </div>
                            <div class="col-span-2">
                                <span class="text-gray-500">Current Fee Structure:</span>
                                <span class="font-semibold ${currentFeeStructureName !== 'Not Assigned' ? 'text-green-600' : 'text-red-500'}">
                                    ${currentFeeStructureName}
                                </span>
                            </div>
                        </div>
                    </div>

                    <form id="assignFeeForm" class="space-y-4">
                        <div>
                            <label class="block text-sm font-medium mb-1">
                                Fee Structure <span class="text-red-500">*</span>
                            </label>
                            <select id="assignFeeStructureId" class="w-full border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500" required>
                                <option value="">-- Select Fee Structure --</option>
                                ${feeStructureOptions}
                            </select>
                            <p class="text-xs text-gray-400 mt-1">Assignment applies only to ${currentYear}</p>
                        </div>

                        <div>
                            <label class="block text-sm font-medium mb-1">Bursary (Optional)</label>
                            <div class="flex gap-2">
                                <select id="assignBursaryId" class="flex-1 border rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500" onchange="toggleAssignCustomBursary()">
                                    ${bursaryOptions}
                                </select>
                                <div id="assignCustomBursaryContainer" class="${hasCustomBursary ? '' : 'hidden'}">
                                    <input type="number" id="assignCustomBursaryAmount"
                                           value="${customBursaryAmount}"
                                           placeholder="Amount (UGX)"
                                           class="w-40 border rounded-lg px-2 py-2 text-sm focus:ring-2 focus:ring-blue-500"
                                           min="0" step="1000">
                                </div>
                            </div>
                            ${hasCustomBursary ? `
                                <p class="text-xs text-green-600 mt-1">🎖️ Current custom bursary: UGX ${customBursaryAmount.toLocaleString()} off tuition</p>
                            ` : ''}
                        </div>

                        <div class="bg-yellow-50 border border-yellow-200 rounded-lg p-3">
                            <div class="flex items-start gap-2">
                                <i class="fas fa-info-circle text-yellow-600 mt-0.5"></i>
                                <div>
                                    <p class="text-sm text-yellow-800">
                                        <strong>⚠️ Important:</strong> This assignment will apply only to the <strong>${currentYear}</strong> academic year.
                                        Previous years' fee structures will remain unchanged.
                                    </p>
                                </div>
                            </div>
                        </div>

                        <div class="flex gap-3 pt-4 border-t">
                            <button type="submit" class="flex-1 bg-green-600 text-white py-2 rounded-lg font-semibold hover:bg-green-700 transition flex items-center justify-center gap-2">
                                <i class="fas fa-save"></i> Assign for ${currentYear}
                            </button>
                            <button type="button" onclick="document.getElementById('assignFeeModal').remove()" 
                                    class="flex-1 bg-gray-300 text-gray-700 py-2 rounded-lg font-semibold hover:bg-gray-400 transition">
                                Cancel
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        `;

        document.body.insertAdjacentHTML('beforeend', modalHtml);

        // ================================================================
        // TOGGLE CUSTOM BURSARY FIELD
        // ================================================================
        window.toggleAssignCustomBursary = function() {
            const bursarySelect = document.getElementById('assignBursaryId');
            const customContainer = document.getElementById('assignCustomBursaryContainer');
            if (bursarySelect && customContainer) {
                if (bursarySelect.value === 'custom') {
                    customContainer.classList.remove('hidden');
                    document.getElementById('assignCustomBursaryAmount').focus();
                } else {
                    customContainer.classList.add('hidden');
                }
            }
        };

        // Initialize custom bursary toggle
        toggleAssignCustomBursary();

        // ================================================================
        // FORM SUBMISSION HANDLER
        // ================================================================
        document.getElementById('assignFeeForm').addEventListener('submit', async (e) => {
            e.preventDefault();

            const feeStructureId = document.getElementById('assignFeeStructureId').value;
            const bursaryId = document.getElementById('assignBursaryId').value || null;
            const customBursaryAmount = document.getElementById('assignCustomBursaryAmount');
            let customAmount = null;
            let isCustomBursary = false;

            // Handle custom bursary
            if (bursaryId === 'custom') {
                const amount = parseInt(customBursaryAmount?.value) || 0;
                if (amount > 0) {
                    customAmount = amount;
                    isCustomBursary = true;
                } else {
                    alert('Please enter a valid custom bursary amount.');
                    customBursaryAmount?.focus();
                    return;
                }
            }

            if (!feeStructureId) {
                alert('Please select a fee structure.');
                document.getElementById('assignFeeStructureId').focus();
                return;
            }

            // Get the selected fee structure name for the confirmation message
            const feeSelect = document.getElementById('assignFeeStructureId');
            const selectedOption = feeSelect.options[feeSelect.selectedIndex];
            const feeStructureName = selectedOption ? selectedOption.text : 'Unknown';

            // Confirm the assignment
            let confirmMsg = `Assign "${feeStructureName}" to ${student.firstName} ${student.lastName} for ${currentYear}?`;
            if (isCustomBursary) {
                confirmMsg += `\n\n💰 Custom Bursary: UGX ${customAmount.toLocaleString()} off tuition`;
            } else if (bursaryId) {
                const bursary = feeBursaries.find(b => b.id === bursaryId);
                if (bursary) {
                    confirmMsg += `\n\n🎖️ Bursary: ${bursary.name}`;
                }
            }
            confirmMsg += `\n\n⚠️ This assignment will apply only to ${currentYear}. Previous years will not be affected.`;

            if (!confirm(confirmMsg)) return;

            // Show loading state
            const submitBtn = e.target.querySelector('button[type="submit"]');
            const originalText = submitBtn.innerHTML;
            submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Assigning...';
            submitBtn.disabled = true;

            try {
                const payload = {
                    studentId: studentId,
                    feeStructureId: feeStructureId,
                    bursaryId: isCustomBursary ? null : bursaryId,
                    academicYear: currentYear,
                    term: currentTerm
                };

                console.log('📤 Sending assignment payload:', payload);

                // Step 1: Save the fee assignment
                const assignmentResponse = await fetch('/api/student-fee-assignments', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Accept': 'application/json'
                    },
                    body: JSON.stringify(payload)
                });

                if (!assignmentResponse.ok) {
                    let errorText = await assignmentResponse.text();
                    console.error('Assignment error response:', errorText);
                    throw new Error(`Failed to assign fee structure (${assignmentResponse.status}): ${errorText}`);
                }

                const assignmentResult = await assignmentResponse.json();
                console.log('✅ Assignment saved:', assignmentResult);

                // Step 2: If custom bursary, save it to the student
                if (isCustomBursary) {
                    const studentUpdatePayload = {
                        customBursary: {
                            amount: customAmount,
                            appliedAt: new Date().toISOString(),
                            description: 'Custom bursary applied via manual assignment'
                        },
                        bursaryId: null,
                        updatedAt: new Date().toISOString()
                    };

                    const studentUpdateResponse = await fetch(`/api/students/${studentId}`, {
                        method: 'PUT',
                        headers: {
                            'Content-Type': 'application/json',
                            'Accept': 'application/json'
                        },
                        body: JSON.stringify(studentUpdatePayload)
                    });

                    if (!studentUpdateResponse.ok) {
                        console.warn('⚠️ Failed to save custom bursary:', await studentUpdateResponse.text());
                    } else {
                        console.log('✅ Custom bursary saved to student');
                    }
                }

                // Step 3: Also update the student's assignedFeeStructureId if not already updated
                // The assignment endpoint should do this, but we'll do it explicitly as a fallback
                const studentSyncResponse = await fetch(`/api/students/${studentId}`, {
                    method: 'PUT',
                    headers: {
                        'Content-Type': 'application/json',
                        'Accept': 'application/json'
                    },
                    body: JSON.stringify({
                        assignedFeeStructureId: feeStructureId,
                        feeStructureId: feeStructureId,
                        _feeAssignmentPeriod: {
                            year: currentYear,
                            term: currentTerm
                        },
                        updatedAt: new Date().toISOString()
                    })
                });

                if (!studentSyncResponse.ok) {
                    console.warn('⚠️ Failed to sync student fee structure ID:', await studentSyncResponse.text());
                } else {
                    console.log('✅ Student fee structure ID synced');
                }

                // Build success message
                let successMsg = `✅ Fee structure assigned successfully!\n\n`;
                successMsg += `📅 Academic Year: ${currentYear}\n`;
                successMsg += `📚 Fee Structure: ${feeStructureName}\n`;
                successMsg += `👤 Student: ${student.firstName} ${student.lastName}\n`;
                successMsg += `🏫 Class: ${className}\n`;

                if (isCustomBursary) {
                    successMsg += `💰 Custom Bursary: UGX ${customAmount.toLocaleString()} off tuition\n`;
                } else if (bursaryId) {
                    const bursary = feeBursaries.find(b => b.id === bursaryId);
                    if (bursary) {
                        successMsg += `🎖️ Bursary: ${bursary.name}\n`;
                    }
                }

                successMsg += `\n⚠️ This assignment applies only to ${currentYear}. Previous years remain unchanged.`;

                alert(successMsg);

                // Close modal
                document.getElementById('assignFeeModal').remove();

                // Refresh the page to show updated data
                const currentPageTitle = document.getElementById('pageTitle')?.innerText || '';
                if (currentPageTitle.includes('All Students') || currentPageTitle.includes('Students')) {
                    if (typeof showStudentList === 'function') {
                        showStudentList();
                    } else {
                        location.reload();
                    }
                } else if (currentPageTitle.includes('Fee Management')) {
                    if (typeof showFeeManagement === 'function') {
                        showFeeManagement();
                    } else {
                        location.reload();
                    }
                } else if (currentPageTitle.includes('Dashboard')) {
                    if (typeof showDashboard === 'function') {
                        showDashboard();
                    } else {
                        location.reload();
                    }
                } else {
                    location.reload();
                }

            } catch (error) {
                console.error('❌ Error assigning fee structure:', error);
                alert('❌ Error assigning fee structure: ' + error.message + '\n\nPlease check the console for more details.');
            } finally {
                submitBtn.innerHTML = originalText;
                submitBtn.disabled = false;
            }
        });

        // ================================================================
        // CLOSE MODAL ON ESCAPE KEY
        // ================================================================
        document.addEventListener('keydown', function escapeHandler(e) {
            if (e.key === 'Escape') {
                const modal = document.getElementById('assignFeeModal');
                if (modal) {
                    modal.remove();
                    document.removeEventListener('keydown', escapeHandler);
                }
            }
        });

        // ================================================================
        // CLOSE MODAL ON BACKDROP CLICK
        // ================================================================
        const modal = document.getElementById('assignFeeModal');
        if (modal) {
            modal.addEventListener('click', function(e) {
                if (e.target === this) {
                    this.remove();
                }
            });
        }

    } catch (error) {
        console.error('❌ Error loading assignment data:', error);
        const loadingModal = document.getElementById('assignFeeLoading');
        if (loadingModal) loadingModal.remove();

        // Show error message in a simple alert
        alert('Failed to load data: ' + error.message + '\n\nPlease check the console for more details.');
    }
}

