// ==================== STUDENT PROMOTION (v6.0 - WITH P.7 ARCHIVING) ====================
// FIXED: P.7 students are archived instead of promoted
// ADDED: Archive tab to view archived students
// ADDED: Archive student details view

async function showStudentPromotion() {
    console.log('🎓 === LOADING STUDENT PROMOTION (v7.0 - ALL ACTIVE STUDENTS) ===');

    const pageTitle = document.getElementById('pageTitle');
    if (pageTitle) pageTitle.innerHTML = '<i class="fas fa-arrow-up mr-2"></i>🎓 Promote Students';

    const mainContent = document.getElementById('mainContent');
    if (!mainContent) return;

    mainContent.innerHTML = `
        <div class="flex justify-center items-center h-64">
            <div class="loading-spinner"></div>
            <span class="ml-3 text-gray-500">Loading promotion data...</span>
        </div>
    `;

    try {
        // Fetch all required data
        const [classesRes, studentsRes, enrollmentsRes, feeStructuresRes, assignmentsRes, settingsRes] = await Promise.all([
            fetch('/api/school/classes'),
            fetch('/api/students'),
            fetch('/api/enrollments'),
            fetch('/api/fee/structures'),
            fetch('/api/student-fee-assignments'),
            fetch('/api/academic/settings')
        ]);

        if (!classesRes.ok) throw new Error('Failed to load classes');
        if (!studentsRes.ok) throw new Error('Failed to load students');
        if (!enrollmentsRes.ok) throw new Error('Failed to load enrollments');
        if (!feeStructuresRes.ok) console.warn('Failed to load fee structures');
        if (!assignmentsRes.ok) console.warn('Failed to load fee assignments');
        if (!settingsRes.ok) console.warn('Failed to load academic settings');

        const classes = await classesRes.json();
        const students = await studentsRes.json();
        const enrollments = await enrollmentsRes.json();
        const feeStructures = await feeStructuresRes.json();
        const feeAssignments = await assignmentsRes.json();
        const settings = await settingsRes.json();

        const currentYear = settings.currentYear || settings.currentAcademicYear || new Date().getFullYear();
        const nextYear = currentYear + 1;

        // Build class map
        const classMap = {};
        classes.forEach(c => { if (c && c.id) classMap[c.id] = c; });

        // Build fee structure map
        const feeStructureMap = {};
        feeStructures.forEach(f => { if (f && f.id) feeStructureMap[f.id] = f; });

        // ================================================================
        // ✅ FIX: Include ALL active students with a class, regardless of enrollment year
        // ================================================================
        // Get current enrollments (for reference, but not used for filtering)
        const currentEnrollments = enrollments.filter(e => e.academicYear === currentYear && e.isCurrent === true);

        // Enrich students with current class info and fee assignment for current year
        const studentsWithClass = students
            .filter(s => s.status === 'Active' && s.currentClassId)
            .map(s => {
                const enrollment = currentEnrollments.find(e => e.studentId === s.id);
                const classObj = classMap[s.currentClassId];
                const assignment = feeAssignments.find(a =>
                    a && a.studentId === s.id && a.academicYear === currentYear
                ) || feeAssignments.find(a => a && a.studentId === s.id) || {};

                // Determine student type from current fee structure
                const feeStructure = feeStructureMap[assignment.feeStructureId];
                const studentType = feeStructure?.name?.toLowerCase().includes('boarding') ? 'Boarding' : 'Day';

                // Check if student is in P.7
                const isP7 = classObj?.name?.toLowerCase().trim() === 'p.7' || 
                            classObj?.name?.toLowerCase().trim() === 'primary 7' ||
                            classObj?.name?.toLowerCase().trim() === 'p7';

                return {
                    ...s,
                    currentClassId: s.currentClassId,
                    currentClassName: classObj?.name || 'Not Assigned',
                    currentLevel: classObj?.level || null,
                    isEnrolled: true, // Always true for active students with a class
                    currentFeeStructureId: assignment.feeStructureId || null,
                    currentFeeStructureName: feeStructure?.name || 'Not Assigned',
                    studentType: studentType,
                    currentClassObj: classObj,
                    isP7: isP7,
                    enrollment: enrollment || null // Keep for reference
                };
            });

        // Store globally for use in tabs
        window.promotionData = {
            classes,
            students: studentsWithClass,
            allStudents: students,
            enrollments,
            feeStructures,
            feeAssignments,
            feeStructureMap,
            classMap,
            currentYear,
            nextYear
        };

        console.log(`📚 ${studentsWithClass.length} active students with class`);
        console.log(`📅 Current Year: ${currentYear}, Next Year: ${nextYear}`);
        console.log(`📦 Fee Structures: ${feeStructures.length}`);

        // Render the page
        const html = `
            <div class="space-y-6">
                <!-- Header -->
                <div class="bg-gradient-to-r from-green-500 to-teal-600 rounded-xl p-5 text-white shadow-lg">
                    <div class="flex justify-between items-center flex-wrap gap-4">
                        <div>
                            <h2 class="text-2xl font-bold">🎓 Student Promotion</h2>
                            <p class="text-sm opacity-90">Promote students to the next class for ${nextYear}</p>
                            <p class="text-xs opacity-70">Showing all active students with a class</p>
                        </div>
                        <div class="text-sm bg-white/20 px-4 py-2 rounded-lg">
                            📅 ${currentYear} → ${nextYear}
                        </div>
                    </div>
                </div>

                <!-- Tabs -->
                <div class="bg-white rounded-xl shadow-sm overflow-hidden">
                    <div class="border-b overflow-x-auto">
                        <div class="flex" id="promotionTabs">
                            <button class="promotion-tab px-6 py-3 font-medium text-sm active border-b-2 border-green-600 text-green-600" data-tab="individual">👤 Individual</button>
                            <button class="promotion-tab px-6 py-3 font-medium text-sm" data-tab="class">📚 By Class</button>
                            <button class="promotion-tab px-6 py-3 font-medium text-sm" data-tab="level">🏷️ By Level</button>
                            <button class="promotion-tab px-6 py-3 font-medium text-sm" data-tab="all">🏫 All School</button>
                            <button class="promotion-tab px-6 py-3 font-medium text-sm" data-tab="archive">📦 Archive</button>
                        </div>
                    </div>
                    <div id="promotionTabContent" class="p-6">
                        <div class="text-center py-8 text-gray-500">Loading...</div>
                    </div>
                </div>
            </div>
        `;

        mainContent.innerHTML = html;

        // Initialize tabs
        initializePromotionTabs();

        // Load the default tab (individual)
        setTimeout(() => loadPromotionTab('individual'), 100);

    } catch (error) {
        console.error('❌ Error loading promotion:', error);
        mainContent.innerHTML = `
            <div class="bg-red-50 border border-red-200 rounded-lg p-6 text-center max-w-2xl mx-auto mt-8">
                <i class="fas fa-exclamation-triangle text-red-600 text-4xl mb-3"></i>
                <p class="text-red-600 font-semibold text-lg">Error Loading Promotion</p>
                <p class="text-red-500 text-sm mt-2">${error.message}</p>
                <button onclick="showStudentPromotion()" class="mt-4 bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700 transition">
                    <i class="fas fa-sync-alt"></i> Retry
                </button>
            </div>
        `;
    }
}
// ==================== TAB INITIALIZATION ====================
function initializePromotionTabs() {
    const tabs = document.querySelectorAll('.promotion-tab');
    tabs.forEach(tab => {
        tab.addEventListener('click', function() {
            tabs.forEach(t => {
                t.classList.remove('active', 'border-green-600', 'text-green-600');
                t.classList.add('text-gray-500');
            });
            this.classList.add('active', 'border-green-600', 'text-green-600');
            this.classList.remove('text-gray-500');
            loadPromotionTab(this.dataset.tab);
        });
    });
}

// ==================== LOAD TAB CONTENT ====================
async function loadPromotionTab(tabName) {
    console.log(`📂 Loading tab: ${tabName}`);
    const container = document.getElementById('promotionTabContent');
    if (!container) return;

    const { classes, students, currentYear, nextYear, feeStructures, feeStructureMap } = window.promotionData || {};

    if (tabName === 'archive') {
        await renderArchiveTab(container);
        return;
    }

    if (!classes || classes.length === 0) {
        container.innerHTML = `<div class="text-center py-8 text-gray-500">No classes found</div>`;
        return;
    }

    let html = '';
    switch (tabName) {
        case 'individual':
            html = renderIndividualTab(students, classes, feeStructures, feeStructureMap);
            break;
        case 'class':
            html = renderClassTab(students, classes, currentYear, nextYear);
            break;
        case 'level':
            html = renderLevelTab(students, classes);
            break;
        case 'all':
            html = renderAllTab(students, classes, currentYear, nextYear);
            break;
        default:
            html = '<p class="text-gray-500">Select a promotion method</p>';
    }

    container.innerHTML = html;

    if (tabName === 'individual') {
        initIndividualTab(feeStructures, feeStructureMap);
    }
}

