// ==================== INITIALIZE UNIVERSAL SEARCH ====================
function initializeUniversalSearch(students, teachers, classes, organizePaymentsByYearTerm, currentYear, currentTerm, termName) {
    const searchInput = document.getElementById('universalSearch');
    const resultsContainer = document.getElementById('searchResults');
    
    const performSearch = () => {
        const searchTerm = searchInput.value.toLowerCase().trim();
        
        if (searchTerm === '') {
            resultsContainer.innerHTML = `
                <div class="bg-gray-50 rounded-xl p-12 text-center border-2 border-dashed">
                    <i class="fas fa-search text-gray-400 text-6xl mb-4"></i>
                    <p class="text-gray-500 text-lg">Enter a search term above to find students, parents, or teachers</p>
                    <p class="text-gray-400 text-sm mt-2">Search by name, admission number, phone number, or ID</p>
                </div>
            `;
            return;
        }
        
        // Search in students
        const matchedStudents = students.filter(student => {
            const fullName = `${student.firstName} ${student.lastName}`.toLowerCase();
            const admissionNumber = (student.admissionNumber || '').toLowerCase();
            const parentName = (student.parentInfo?.name || '').toLowerCase();
            const parentPhone = (student.parentInfo?.phone || '').toLowerCase();
            const parentAltPhone = (student.parentInfo?.altPhone || '').toLowerCase();
            
            return fullName.includes(searchTerm) || 
                   admissionNumber.includes(searchTerm) ||
                   parentName.includes(searchTerm) ||
                   parentPhone.includes(searchTerm) ||
                   parentAltPhone.includes(searchTerm);
        });
        
        // Search in teachers
        const matchedTeachers = teachers.filter(teacher => {
            const fullName = `${teacher.firstName} ${teacher.lastName}`.toLowerCase();
            const teacherId = (teacher.teacherId || '').toLowerCase();
            const phone = (teacher.phone || '').toLowerCase();
            const email = (teacher.email || '').toLowerCase();
            
            return fullName.includes(searchTerm) || 
                   teacherId.includes(searchTerm) ||
                   phone.includes(searchTerm) ||
                   email.includes(searchTerm);
        });
        
        // Build results HTML
        let resultsHtml = '';
        
        // Student Results
        if (matchedStudents.length > 0) {
            resultsHtml += `
                <div class="bg-white rounded-xl shadow-sm overflow-hidden">
                    <div class="bg-gradient-to-r from-blue-500 to-blue-600 p-4 text-white">
                        <h3 class="font-bold text-lg flex items-center">
                            <i class="fas fa-user-graduate mr-2"></i> Students Found (${matchedStudents.length})
                        </h3>
                    </div>
                    <div class="divide-y">
                        ${matchedStudents.map(student => renderStudentSearchResult(student, classes, organizePaymentsByYearTerm, currentYear, currentTerm, termName)).join('')}
                    </div>
                </div>
            `;
        }
        
        // Teacher Results
        if (matchedTeachers.length > 0) {
            resultsHtml += `
                <div class="bg-white rounded-xl shadow-sm overflow-hidden">
                    <div class="bg-gradient-to-r from-purple-500 to-purple-600 p-4 text-white">
                        <h3 class="font-bold text-lg flex items-center">
                            <i class="fas fa-chalkboard-user mr-2"></i> Teachers Found (${matchedTeachers.length})
                        </h3>
                    </div>
                    <div class="divide-y">
                        ${matchedTeachers.map(teacher => renderTeacherSearchResult(teacher)).join('')}
                    </div>
                </div>
            `;
        }
        
        // No results
        if (matchedStudents.length === 0 && matchedTeachers.length === 0) {
            resultsHtml = `
                <div class="bg-yellow-50 rounded-xl p-12 text-center border-2 border-yellow-200">
                    <i class="fas fa-exclamation-triangle text-yellow-500 text-6xl mb-4"></i>
                    <p class="text-yellow-700 text-lg">No results found for "${searchInput.value}"</p>
                    <p class="text-yellow-600 text-sm mt-2">Try searching by student name, admission number, parent name, parent phone, teacher name, or teacher ID</p>
                </div>
            `;
        }
        
        resultsContainer.innerHTML = resultsHtml;
        
        // Initialize collapsible sections
        document.querySelectorAll('.toggle-details').forEach(btn => {
            btn.addEventListener('click', function() {
                const targetId = this.dataset.target;
                const target = document.getElementById(targetId);
                if (target) {
                    target.classList.toggle('hidden');
                    const icon = this.querySelector('i');
                    if (icon) {
                        icon.classList.toggle('fa-chevron-down');
                        icon.classList.toggle('fa-chevron-up');
                    }
                }
            });
        });
    };
    
    searchInput.addEventListener('input', performSearch);
    searchInput.addEventListener('keyup', performSearch);
}

// ==================== RENDER STUDENT SEARCH RESULT ====================
function renderStudentSearchResult(student, classes, organizePaymentsByYearTerm, currentYear, currentTerm, termName) {
    const studentPayments = student.allPayments || [];
    const totalPaid = student.totalPaidAllTime || 0;
    const currentBalance = student.currentTermBalance || 0;
    const expectedTuition = student.expectedTuition || 0;
    
    // Get student's class level
    const classObj = classes.find(c => c.name === student.currentClass);
    const classLevel = classObj ? classObj.level : 'Not Specified';
    
    // Group payments by year and term
    const paymentsByYear = {};
    studentPayments.forEach(p => {
        const year = p.academicYear || new Date(p.date).getFullYear();
        const term = p.term;
        if (!paymentsByYear[year]) paymentsByYear[year] = {};
        if (!paymentsByYear[year][term]) paymentsByYear[year][term] = [];
        paymentsByYear[year][term].push(p);
    });
    
    const years = Object.keys(paymentsByYear).sort().reverse();
    
    // Calculate payment statistics
    const totalTransactions = studentPayments.length;
    const firstPaymentDate = studentPayments.length > 0 ? new Date(Math.min(...studentPayments.map(p => new Date(p.date)))).toLocaleDateString() : 'N/A';
    const lastPaymentDate = studentPayments.length > 0 ? new Date(Math.max(...studentPayments.map(p => new Date(p.date)))).toLocaleDateString() : 'N/A';
    
    // Payment methods summary
    const paymentMethods = {};
    studentPayments.forEach(p => {
        const method = p.method || 'cash';
        paymentMethods[method] = (paymentMethods[method] || 0) + (p.totalAmount || p.amount || 0);
    });
    
    const uniqueId = `student-${student.id}`;
    
    return `
        <div class="p-6 hover:bg-gray-50 transition">
            <!-- Student Header -->
            <div class="flex justify-between items-start mb-4">
                <div class="flex items-center space-x-3">
                    <div class="w-12 h-12 bg-gradient-to-r from-blue-500 to-purple-500 rounded-full flex items-center justify-center text-white font-bold text-xl">
                        ${student.firstName?.charAt(0)}${student.lastName?.charAt(0)}
                    </div>
                    <div>
                        <h4 class="font-bold text-xl">${student.firstName} ${student.lastName}</h4>
                        <p class="text-sm text-gray-500">Admission: ${student.admissionNumber} | Class: ${student.currentClass}</p>
                    </div>
                </div>
                <div class="text-right">
                    <div class="text-2xl font-bold ${currentBalance > 0 ? 'text-red-600' : 'text-green-600'}">
                        ${currentBalance > 0 ? `Due: UGX ${currentBalance.toLocaleString()}` : 'Fully Paid'}
                    </div>
                    <p class="text-xs text-gray-500">Status: ${student.status || 'Active'}</p>
                </div>
            </div>
            
            <!-- Expand/Collapse Button -->
            <button class="toggle-details w-full text-left text-blue-600 hover:text-blue-800 text-sm font-medium py-2 border-t flex items-center justify-between"
                    data-target="${uniqueId}">
                <span><i class="fas fa-info-circle mr-2"></i> View Complete Details</span>
                <i class="fas fa-chevron-down"></i>
            </button>
            
            <!-- Detailed Information (Collapsible) -->
            <div id="${uniqueId}" class="hidden mt-4 space-y-4 border-t pt-4">
                <!-- Personal Information -->
                <div class="bg-blue-50 rounded-lg p-4">
                    <h5 class="font-bold text-md mb-3 flex items-center">
                        <i class="fas fa-user-circle text-blue-600 mr-2"></i> Personal Information
                    </h5>
                    <div class="grid grid-cols-1 md:grid-cols-3 gap-3 text-sm">
                        <div><span class="font-medium">Full Name:</span> ${student.firstName} ${student.lastName}</div>
                        <div><span class="font-medium">Admission Number:</span> ${student.admissionNumber || 'N/A'}</div>
                        <div><span class="font-medium">Gender:</span> ${student.gender || 'N/A'}</div>
                        <div><span class="font-medium">Date of Birth:</span> ${student.dateOfBirth || 'N/A'}</div>
                        <div><span class="font-medium">Class:</span> ${student.currentClass || 'Not Assigned'}</div>
                        <div><span class="font-medium">Class Level:</span> ${classLevel}</div>
                        <div><span class="font-medium">Status:</span> <span class="px-2 py-0.5 rounded-full text-xs ${student.status === 'Active' ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'}">${student.status || 'Active'}</span></div>
                        <div><span class="font-medium">Enrolled On:</span> ${student.enrolledAt ? new Date(student.enrolledAt).toLocaleDateString() : 'N/A'}</div>
                        <div><span class="font-medium">Address:</span> ${student.address || 'N/A'}</div>
                    </div>
                </div>
                
                <!-- Parent/Guardian Information -->
                <div class="bg-green-50 rounded-lg p-4">
                    <h5 class="font-bold text-md mb-3 flex items-center">
                        <i class="fas fa-users text-green-600 mr-2"></i> Parent/Guardian Information
                    </h5>
                    <div class="grid grid-cols-1 md:grid-cols-2 gap-3 text-sm">
                        <div><span class="font-medium">Parent Name:</span> ${student.parentInfo?.name || 'N/A'}</div>
                        <div><span class="font-medium">Phone:</span> ${student.parentInfo?.phone || 'N/A'}</div>
                        <div><span class="font-medium">Alternative Phone:</span> ${student.parentInfo?.altPhone || 'N/A'}</div>
                        <div><span class="font-medium">Email:</span> ${student.parentInfo?.email || 'N/A'}</div>
                        <div><span class="font-medium">Occupation:</span> ${student.parentInfo?.occupation || 'N/A'}</div>
                        <div><span class="font-medium">Relationship:</span> ${student.parentInfo?.relationship || 'Parent'}</div>
                    </div>
                </div>
                
                <!-- Fee Structure & Bursary -->
                <div class="bg-purple-50 rounded-lg p-4">
                    <h5 class="font-bold text-md mb-3 flex items-center">
                        <i class="fas fa-money-bill-wave text-purple-600 mr-2"></i> Fee Information
                    </h5>
                    <div class="grid grid-cols-1 md:grid-cols-3 gap-3 text-sm">
                        <div><span class="font-medium">Fee Structure:</span> ${student.feeStructure?.name || 'Not Assigned'}</div>
                        <div><span class="font-medium">Expected Tuition (Current Term):</span> UGX ${expectedTuition.toLocaleString()}</div>
                        <div><span class="font-medium">Paid This Term:</span> UGX ${student.currentTermPaid?.toLocaleString() || 0}</div>
                        <div><span class="font-medium">Current Term Balance:</span> <span class="font-bold ${currentBalance > 0 ? 'text-red-600' : 'text-green-600'}">UGX ${Math.abs(currentBalance).toLocaleString()}</span></div>
                        ${student.appliedBursary ? `
                            <div><span class="font-medium">Bursary Applied:</span> ${student.appliedBursary.name}</div>
                            <div><span class="font-medium">Discount:</span> ${student.appliedBursary.type === 'percentage' ? `${student.appliedBursary.value}%` : `UGX ${student.appliedBursary.value.toLocaleString()}`}</div>
                            <div><span class="font-medium">Discount Amount:</span> UGX ${student.discountAmount?.toLocaleString() || 0}</div>
                        ` : '<div colspan="2"><span class="font-medium">Bursary:</span> None</div>'}
                    </div>
                </div>
                
                <!-- Payment History Summary -->
                <div class="bg-orange-50 rounded-lg p-4">
                    <h5 class="font-bold text-md mb-3 flex items-center">
                        <i class="fas fa-chart-line text-orange-600 mr-2"></i> Payment Summary
                    </h5>
                    <div class="grid grid-cols-1 md:grid-cols-4 gap-3 text-sm mb-4">
                        <div><span class="font-medium">Total Paid (All Time):</span> <span class="font-bold text-green-600">UGX ${totalPaid.toLocaleString()}</span></div>
                        <div><span class="font-medium">Total Transactions:</span> ${totalTransactions}</div>
                        <div><span class="font-medium">First Payment:</span> ${firstPaymentDate}</div>
                        <div><span class="font-medium">Last Payment:</span> ${lastPaymentDate}</div>
                    </div>
                    
                    <!-- Payment Methods Summary -->
                    <div class="mt-3">
                        <p class="font-medium text-sm mb-2">Payment Methods Breakdown:</p>
                        <div class="flex flex-wrap gap-2">
                            ${Object.entries(paymentMethods).map(([method, amount]) => `
                                <span class="px-3 py-1 bg-white rounded-full text-sm">
                                    ${method.toUpperCase()}: UGX ${amount.toLocaleString()}
                                </span>
                            `).join('')}
                        </div>
                    </div>
                </div>
                
                <!-- Detailed Payment History by Year and Term -->
                <div class="bg-gray-50 rounded-lg p-4">
                    <h5 class="font-bold text-md mb-3 flex items-center">
                        <i class="fas fa-history text-gray-600 mr-2"></i> Complete Payment History
                    </h5>
                    ${years.length > 0 ? years.map(year => `
                        <div class="mb-4">
                            <h6 class="font-bold text-sm bg-gray-200 p-2 rounded mb-2">📅 ${year} Academic Year</h6>
                            <div class="grid grid-cols-1 md:grid-cols-3 gap-3">
                                ${[1, 2, 3].map(term => {
                                    const termPayments = paymentsByYear[year]?.[term] || [];
                                    const termTotal = termPayments.reduce((s, p) => s + (p.totalAmount || p.amount || 0), 0);
                                    if (termPayments.length === 0 && termTotal === 0) return null;
                                    return `
                                        <div class="bg-white rounded-lg p-3 shadow-sm">
                                            <div class="flex justify-between items-center mb-2">
                                                <span class="font-semibold">Term ${term}</span>
                                                <span class="text-sm font-bold text-green-600">UGX ${termTotal.toLocaleString()}</span>
                                            </div>
                                            <div class="space-y-2 max-h-40 overflow-y-auto">
                                                ${termPayments.map(p => `
                                                    <div class="text-xs border-b pb-1">
                                                        <div class="flex justify-between">
                                                            <span>${new Date(p.date).toLocaleDateString()}</span>
                                                            <span class="font-medium">UGX ${(p.totalAmount || p.amount || 0).toLocaleString()}</span>
                                                        </div>
                                                        <div class="flex justify-between text-gray-500">
                                                            <span>Receipt: ${p.receiptNumber}</span>
                                                            <span>${p.method}</span>
                                                        </div>
                                                        ${p.notes ? `<div class="text-gray-400 mt-1">${p.notes}</div>` : ''}
                                                    </div>
                                                `).join('')}
                                            </div>
                                        </div>
                                    `;
                                }).filter(Boolean).join('')}
                            </div>
                        </div>
                    `).join('') : '<p class="text-gray-500 text-center">No payment records found</p>'}
                </div>
                
                <!-- Recommendations -->
                <div class="bg-yellow-50 rounded-lg p-4 border-l-4 border-yellow-500">
                    <h5 class="font-bold text-md mb-2 flex items-center">
                        <i class="fas fa-lightbulb text-yellow-600 mr-2"></i> Recommendations
                    </h5>
                    <div class="space-y-2 text-sm">
                        ${currentBalance > 0 ? `
                            <div class="flex items-start">
                                <i class="fas fa-exclamation-circle text-red-500 mr-2 mt-0.5"></i>
                                <span><strong>Outstanding Balance:</strong> This student has an outstanding balance of <strong>UGX ${currentBalance.toLocaleString()}</strong> for ${termName} ${currentYear}. Please follow up for payment.</span>
                            </div>
                        ` : `
                            <div class="flex items-start">
                                <i class="fas fa-check-circle text-green-500 mr-2 mt-0.5"></i>
                                <span><strong>Good Standing:</strong> This student has no outstanding balance for ${termName} ${currentYear}.</span>
                            </div>
                        `}
                        
                        ${student.status === 'Inactive' ? `
                            <div class="flex items-start">
                                <i class="fas fa-user-slash text-gray-500 mr-2 mt-0.5"></i>
                                <span><strong>Inactive Status:</strong> This student is marked as inactive. Please review if they should be re-activated.</span>
                            </div>
                        ` : ''}
                        
                        ${totalTransactions === 0 ? `
                            <div class="flex items-start">
                                <i class="fas fa-info-circle text-blue-500 mr-2 mt-0.5"></i>
                                <span><strong>No Payment History:</strong> This student has not made any payments yet. Consider sending a payment reminder.</span>
                            </div>
                        ` : ''}
                        
                        ${student.parentInfo?.phone ? `
                            <div class="flex items-start">
                                <i class="fas fa-phone text-green-500 mr-2 mt-0.5"></i>
                                <span><strong>Contact Parent:</strong> Parent phone: ${student.parentInfo.phone}</span>
                            </div>
                        ` : ''}
                    </div>
                </div>
            </div>
        </div>
    `;
}

// ==================== RENDER TEACHER SEARCH RESULT ====================
