async function exportFullSystemBackup() {
    try {
        const response = await fetch('/api/reports/export-all');
        const data = await response.json();
        
        const backupData = {
            ...data,
            exportDate: new Date().toISOString(),
            version: '2.0'
        };
        
        const jsonStr = JSON.stringify(backupData, null, 2);
        const blob = new Blob([jsonStr], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `school_full_backup_${new Date().toISOString().split('T')[0]}.json`;
        a.click();
        URL.revokeObjectURL(url);
        
        localStorage.setItem('lastBackupDate', new Date().toLocaleString());
        alert('✅ Full backup created successfully!');
    } catch (error) {
        console.error('Error creating backup:', error);
        alert('❌ Error creating backup: ' + error.message);
    }
}

async function restoreFromBackupFile() {
    const fileInput = document.getElementById('restoreFileInput');
    if (!fileInput.files || fileInput.files.length === 0) {
        alert('Please select a backup file to restore');
        return;
    }
    
    const file = fileInput.files[0];
    if (!file.name.endsWith('.json')) {
        alert('Please select a valid JSON backup file');
        return;
    }
    
    const reader = new FileReader();
    reader.onload = async function(e) {
        try {
            const backupData = JSON.parse(e.target.result);
            
            const confirmation = prompt('⚠️ WARNING: Restoring will overwrite ALL current data!\n\nType "RESTORE" to confirm:');
            if (confirmation !== 'RESTORE') {
                alert('Restore cancelled');
                return;
            }
            
            // Restore each data type
            if (backupData.students) {
                await fetch('/api/students/bulk', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(backupData.students)
                }).catch(() => {});
            }
            
            if (backupData.teachers) {
                await fetch('/api/teachers/bulk', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(backupData.teachers)
                }).catch(() => {});
            }
            
            alert('✅ Data restored successfully! The page will now refresh.');
            setTimeout(() => window.location.reload(), 1500);
            
        } catch (error) {
            console.error('Error restoring data:', error);
            alert('❌ Invalid backup file or error during restore');
        }
    };
    reader.readAsText(file);
}

