async function saveSystemPreferences() {
    const emailNotifications = document.getElementById('emailNotifications').checked;
    const smsNotifications = document.getElementById('smsNotifications').checked;
    const autoBackup = document.getElementById('autoBackup').checked;
    
    let settings = await fetch('/api/school').then(r => r.json());
    settings = settings.settings || {};
    
    settings.emailNotifications = emailNotifications;
    settings.smsNotifications = smsNotifications;
    settings.autoBackup = autoBackup;
    
    try {
        const response = await fetch('/api/school/settings', {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(settings)
        });
        
        if (response.ok) {
            alert('✅ System preferences saved!');
        } else {
            alert('❌ Error saving preferences');
        }
    } catch (error) {
        console.error('Error:', error);
        alert('Network error: ' + error.message);
    }
}

function confirmSystemReset() {
    const confirmation = prompt('⚠️ WARNING: This will delete ALL data!\n\nType "RESET ALL DATA" to confirm:');
    if (confirmation === 'RESET ALL DATA') {
        resetSystem();
    } else {
        alert('Reset cancelled');
    }
}

async function resetSystem() {
    try {
        const response = await fetch('/api/system/reset', { method: 'DELETE' });
        if (response.ok) {
            localStorage.clear();
            alert('✅ System reset successfully! Page will reload.');
            setTimeout(() => window.location.reload(), 1500);
        } else {
            alert('❌ Error resetting system');
        }
    } catch (error) {
        console.error('Error:', error);
        alert('Network error: ' + error.message);
    }
}

