// ========== SET FULL TUITION FOR PERIOD ==========
function setFullTuitionForPeriod(periodKey, tuitionBalance) {
    const tuitionInput = document.getElementById(`tuitionAmount_${periodKey}`);
    if (tuitionInput) {
        tuitionInput.value = tuitionBalance;
        tuitionInput.dispatchEvent(new Event('input'));
        updatePeriodTotal(periodKey);
    }
}

// ========== UPDATE PERIOD TOTAL ==========
// ========== UPDATE PERIOD TOTAL (COMPLETE REBUILD) ==========
// Version: 3.0 - Cash and Items tracked SEPARATELY
// - Cash total: Sum of all cash amounts
// - Items total: Sum of all item quantities
// - Grand total: Cash + (Items * UnitPrice) for display only

function updatePeriodTotal(periodKey) {
    let totalCash = 0;
    let totalItems = 0;
    let totalValue = 0;
    
    // ========== SUM CASH PAYMENTS ==========
    document.querySelectorAll(`#periodItems_${periodKey} .cash-amount-input`).forEach(input => {
        const val = parseFloat(input.value) || 0;
        totalCash += val;
        totalValue += val;
    });
    
    // ========== SUM ITEM QUANTITIES ==========
    document.querySelectorAll(`#periodItems_${periodKey} .item-quantity-input`).forEach(input => {
        const val = parseFloat(input.value) || 0;
        totalItems += val;
        const unitPrice = parseFloat(input.dataset.unitPrice) || 0;
        totalValue += val * unitPrice;
    });
    
    // ========== GET TUITION PAYMENT ==========
    const tuitionInput = document.getElementById(`tuitionAmount_${periodKey}`);
    const tuitionAmount = parseFloat(tuitionInput?.value) || 0;
    totalValue += tuitionAmount;
    
    // ========== UPDATE SUMMARY DISPLAYS ==========
    const summaryTuition = document.getElementById(`summaryTuition_${periodKey}`);
    const summaryCash = document.getElementById(`summaryCash_${periodKey}`);
    const summaryItems = document.getElementById(`summaryItems_${periodKey}`);
    const summaryTotal = document.getElementById(`summaryTotal_${periodKey}`);
    const outstandingAfter = document.getElementById(`outstandingAfter_${periodKey}`);
    const itemsAfter = document.getElementById(`itemsAfter_${periodKey}`);
    
    if (summaryTuition) summaryTuition.innerHTML = `UGX ${formatMoney(tuitionAmount)}`;
    if (summaryCash) summaryCash.innerHTML = `UGX ${formatMoney(totalCash)}`;
    if (summaryItems) summaryItems.innerHTML = `${totalItems} item(s)`;
    if (summaryTotal) summaryTotal.innerHTML = `UGX ${formatMoney(totalValue)}`;
    
    // ========== CALCULATE REMAINING ==========
    const totalBalanceEl = document.querySelector(`#periodForm_${periodKey} .font-bold.text-sm`);
    const totalBalance = parseFloat(totalBalanceEl?.innerText?.replace(/[^0-9]/g, '') || 0);
    const remainingAfter = Math.max(0, totalBalance - totalValue);
    if (outstandingAfter) {
        outstandingAfter.innerHTML = `UGX ${formatMoney(remainingAfter)}`;
        outstandingAfter.className = `font-bold text-lg ${remainingAfter > 0 ? 'text-red-600' : 'text-green-600'}`;
    }
    
    // ========== CALCULATE ITEMS REMAINING ==========
    const totalItemsRemainingEl = document.querySelector(`#periodForm_${periodKey} .bg-orange-50 .font-bold`);
    const totalItemsRemaining = parseFloat(totalItemsRemainingEl?.innerText?.replace(/[^0-9]/g, '') || 0);
    const itemsRemainingAfter = Math.max(0, totalItemsRemaining - totalItems);
    if (itemsAfter) {
        itemsAfter.innerHTML = itemsRemainingAfter > 0 ? `📦 ${itemsRemainingAfter} items remaining` : '✓ All items delivered';
        itemsAfter.className = `text-xs text-gray-400 ${itemsRemainingAfter > 0 ? 'text-orange-600' : 'text-green-600'}`;
    }
    
    // ========== UPDATE PERIOD FOOTER ==========
    const totalSpan = document.getElementById(`periodTotal_${periodKey}`);
    if (totalSpan) {
        totalSpan.innerHTML = `Total: UGX ${formatMoney(totalValue)} (💵 ${formatMoney(totalCash)} cash + 📦 ${totalItems} items)`;
    }
    
    const countSpan = document.getElementById(`periodItemsCount_${periodKey}`);
    if (countSpan) {
        const totalInputs = document.querySelectorAll(`#periodItems_${periodKey} .cash-amount-input, #periodItems_${periodKey} .item-quantity-input, #tuitionAmount_${periodKey}`);
        const filledInputs = Array.from(totalInputs).filter(i => parseFloat(i.value) > 0);
        countSpan.innerHTML = `Items: ${filledInputs.length} with payment`;
    }
}

// ========== SUBMIT PERIOD PAYMENT ==========
