// ==================== MODIFIED SUBMIT PERIOD PAYMENT WITH MODAL ====================

// Update the submitPeriodPayment function to use the modal instead of alert

async function submitPeriodPayment(periodKey) {
    console.log('=== SUBMIT PERIOD PAYMENT v12.0 - WITH CONFIRMATION MODAL ===');
    console.log('Period Key:', periodKey);
    
    const periodData = window.multiPeriodData;
    if (!periodData) { 
        showToast('Period data not loaded', 'error');
        return; 
    }
    
    // ========== FIND THE PERIOD ==========
    let period = null;
    let isCurrent = false;
    let year, term;
    
    if (periodData.currentPeriod && periodData.currentPeriod.periodKey === periodKey) {
        period = periodData.currentPeriod;
        isCurrent = true;
        year = periodData.currentPeriod.year;
        term = periodData.currentPeriod.term;
    } else if (periodData.previousPeriods) {
        period = periodData.previousPeriods.find(p => p.periodKey === periodKey);
        if (period) { 
            year = period.year; 
            term = period.term; 
        }
    }
    
    if (!period) { 
        showToast('Period not found', 'error');
        return; 
    }
    
    console.log(`📅 Processing period: ${year} Term ${term}${isCurrent ? ' (Current)' : ' (Previous)'}`);
    
    // ========== GET PAYMENT DETAILS ==========
    const method = document.getElementById(`paymentMethod_${periodKey}`)?.value || 'cash';
    let receiptNumber = document.getElementById(`receiptNumber_${periodKey}`)?.value || null;
    const reference = document.getElementById(`reference_${periodKey}`)?.value || '';
    const notes = document.getElementById(`notes_${periodKey}`)?.value || '';
    
    const paymentDate = document.getElementById(`paymentDate_${periodKey}`)?.value || new Date().toISOString().split('T')[0];
    const paymentTime = document.getElementById(`paymentTime_${periodKey}`)?.value || new Date().toTimeString().slice(0, 5);
    const fullDateTime = `${paymentDate}T${paymentTime}`;
    
    // ========== GET TUITION PAYMENT ==========
    const tuitionBalance = period.tuition?.balance || 0;
    const tuitionInput = document.getElementById(`tuitionAmount_${periodKey}`);
    
    let tuitionPaid = 0;
    if (tuitionInput) {
        const rawValue = tuitionInput.value;
        if (rawValue && rawValue.trim() !== '') {
            tuitionPaid = parseFloat(rawValue);
            if (isNaN(tuitionPaid)) tuitionPaid = 0;
            tuitionPaid = Math.round(tuitionPaid);
        }
        
        if (tuitionPaid > tuitionBalance && tuitionBalance > 0) {
            console.warn(`⚠️ Tuition ${tuitionPaid} exceeds balance ${tuitionBalance}, capping...`);
            tuitionPaid = tuitionBalance;
            tuitionInput.value = tuitionPaid;
            showToast(`⚠️ Tuition capped at UGX ${formatMoney(tuitionBalance)}`, 'warning');
        }
    }
    
    console.log(`💰 Tuition payment: UGX ${formatMoney(tuitionPaid)}`);
    
    // ========== COLLECT ACTIVITY ITEM PAYMENTS ==========
    const activityItemPayments = [];
    const processedItemKeys = new Set();
    let totalActivityAmount = 0;
    
    // ========== PROCESS CASH PAYMENTS ==========
    console.log('📊 Processing cash payments...');
    const cashInputs = document.querySelectorAll(`#periodItems_${periodKey} .cash-amount-input`);
    console.log(`Found ${cashInputs.length} cash inputs`);
    
    for (const input of cashInputs) {
        const rawValue = input.value;
        let enteredAmount = 0;
        
        if (rawValue && rawValue.trim() !== '') {
            enteredAmount = parseFloat(rawValue);
            if (isNaN(enteredAmount)) enteredAmount = 0;
        }
        
        if (enteredAmount <= 0) {
            console.log(`⏭️ Skipping ${input.dataset.itemName || 'unknown'} - amount: ${enteredAmount}`);
            continue;
        }
        
        enteredAmount = Math.round(enteredAmount);
        
        const itemName = input.dataset.itemName || '';
        const componentName = input.dataset.component || '';
        const periodType = input.dataset.periodType || 'termly';
        const unitPrice = parseFloat(input.dataset.unitPrice) || 0;
        const maxCash = parseFloat(input.dataset.maxCash) || 0;
        const isSpecial = input.dataset.special === 'true';
        const paymentMode = input.dataset.paymentMode || 'none';
        const isLocked = input.dataset.isLocked === 'true';
        
        if (!itemName || !componentName) {
            console.warn('⚠️ Missing itemName or componentName, skipping');
            continue;
        }
        
        // ========== CRITICAL FIX: VALIDATE CASH IS MULTIPLE OF UNIT PRICE ==========
        let finalAmount = enteredAmount;
        
        if (!isSpecial && unitPrice > 0) {
            const remainder = finalAmount % unitPrice;
            if (remainder !== 0) {
                finalAmount = Math.floor(finalAmount / unitPrice) * unitPrice;
                console.warn(`⚠️ Amount ${enteredAmount} rounded down to ${finalAmount} (must be multiple of UGX ${formatMoney(unitPrice)})`);
                if (finalAmount === 0) {
                    showToast(`⚠️ Cash amount must be at least UGX ${formatMoney(unitPrice)} for ${itemName}`, 'warning');
                    continue;
                }
                showToast(`⚠️ Amount for ${itemName} adjusted to UGX ${formatMoney(finalAmount)} (multiple of UGX ${formatMoney(unitPrice)})`, 'warning');
            }
        }
        
        if (finalAmount > maxCash && maxCash > 0) {
            console.warn(`⚠️ Amount ${finalAmount} exceeds max ${maxCash}, capping...`);
            finalAmount = maxCash;
            if (unitPrice > 0) {
                finalAmount = Math.floor(finalAmount / unitPrice) * unitPrice;
            }
            input.value = finalAmount;
            showToast(`⚠️ Amount capped at UGX ${formatMoney(finalAmount)} for ${itemName}`, 'warning');
        }
        
        // ========== CHECK IF ITEM IS LOCKED TO CASH OR ITEMS ==========
        if (isLocked && paymentMode === 'items') {
            console.log(`⏭️ Skipping cash payment for ${itemName} - item is locked to ITEMS only`);
            showToast(`⚠️ ${itemName} is locked to ITEM payments. Bring items instead.`, 'warning');
            continue;
        }
        
        // ========== DETERMINE IF THIS PAYMENT SHOULD BE CASH OR ITEM ==========
        const existingHistories = getItemPaymentHistories(periodKey, componentName, itemName, periodType);
        let hasCashHistory = existingHistories.some(h => h.type === 'cash' || h.type === 'paid_cash');
        let hasItemHistory = existingHistories.some(h => h.type === 'item' || h.type === 'brought_item');
        
        if (hasItemHistory && !hasCashHistory) {
            console.log(`⏭️ Skipping cash for ${itemName} - item is locked to ITEMS (from history)`);
            showToast(`⚠️ ${itemName} is locked to ITEM payments. Bring items instead.`, 'warning');
            continue;
        }
        
        const strictKey = `cash_${periodType}_${componentName}_${itemName}`;
        if (processedItemKeys.has(strictKey)) {
            console.log(`⏭️ Duplicate cash item: ${strictKey}`);
            continue;
        }
        processedItemKeys.add(strictKey);
        
        console.log(`💰 Cash payment: ${itemName} - UGX ${finalAmount} (entered: ${enteredAmount})`);
        
        let quantityRequired = 1;
        if (unitPrice > 0) {
            quantityRequired = Math.floor(finalAmount / unitPrice);
        }
        
        const paymentEntry = {
            periodType: periodType,
            componentName: componentName,
            itemName: itemName,
            unitPrice: unitPrice,
            quantityRequired: quantityRequired,
            paymentType: 'paid_cash',
            amountPaid: finalAmount,
            itemsBrought: null,
            cashEquivalent: finalAmount,
            isPreviousBalancePayment: !isCurrent,
            targetPeriodYear: year,
            targetPeriodTerm: term,
            date: fullDateTime,
            isCashPayment: true,
            isItemPayment: false,
            paymentMode: 'cash',
            coversItems: quantityRequired
        };
        
        activityItemPayments.push(paymentEntry);
        totalActivityAmount += finalAmount;
        
        console.log(`   ✅ Added: ${itemName} - UGX ${formatMoney(finalAmount)} (covers ${quantityRequired} items)`);
    }
    
    // ========== PROCESS ITEM BRING PAYMENTS ==========
    console.log('📦 Processing item bring payments...');
    const itemInputs = document.querySelectorAll(`#periodItems_${periodKey} .item-quantity-input`);
    console.log(`Found ${itemInputs.length} item inputs`);
    
    for (const input of itemInputs) {
        const rawValue = input.value;
        let enteredQuantity = 0;
        
        if (rawValue && rawValue.trim() !== '') {
            enteredQuantity = parseInt(rawValue);
            if (isNaN(enteredQuantity)) enteredQuantity = 0;
        }
        
        if (enteredQuantity <= 0) {
            console.log(`⏭️ Skipping ${input.dataset.itemName || 'unknown'} - quantity: ${enteredQuantity}`);
            continue;
        }
        
        const itemName = input.dataset.itemName || '';
        const componentName = input.dataset.component || '';
        const periodType = input.dataset.periodType || 'termly';
        const unitPrice = parseFloat(input.dataset.unitPrice) || 0;
        const maxItems = parseFloat(input.dataset.maxItems) || 0;
        
        if (!itemName || !componentName) {
            console.warn('⚠️ Missing itemName or componentName, skipping');
            continue;
        }
        
        // ========== CHECK IF ITEM IS LOCKED TO CASH ==========
        const existingHistories = getItemPaymentHistories(periodKey, componentName, itemName, periodType);
        let hasCashHistory = existingHistories.some(h => h.type === 'cash' || h.type === 'paid_cash');
        let hasItemHistory = existingHistories.some(h => h.type === 'item' || h.type === 'brought_item');
        
        if (hasCashHistory && !hasItemHistory) {
            console.log(`⏭️ Skipping item bring for ${itemName} - item is locked to CASH (from history)`);
            showToast(`⚠️ ${itemName} is locked to CASH payments. Use cash instead.`, 'warning');
            continue;
        }
        
        let finalQuantity = enteredQuantity;
        if (finalQuantity > maxItems && maxItems > 0) {
            console.warn(`⚠️ Quantity ${finalQuantity} exceeds max ${maxItems}, capping...`);
            finalQuantity = maxItems;
            input.value = finalQuantity;
            showToast(`⚠️ Quantity capped at ${maxItems} for ${itemName}`, 'warning');
        }
        
        const strictKey = `item_${periodType}_${componentName}_${itemName}`;
        if (processedItemKeys.has(strictKey)) {
            console.log(`⏭️ Duplicate item: ${strictKey}`);
            continue;
        }
        processedItemKeys.add(strictKey);
        
        const cashEquivalent = Math.round(finalQuantity * unitPrice);
        
        console.log(`📦 Item bring: ${itemName} - ${finalQuantity} items (entered: ${enteredQuantity})`);
        
        const paymentEntry = {
            periodType: periodType,
            componentName: componentName,
            itemName: itemName,
            unitPrice: unitPrice,
            quantityRequired: maxItems || finalQuantity,
            paymentType: 'brought_item',
            amountPaid: null,
            itemsBrought: finalQuantity,
            cashEquivalent: cashEquivalent,
            isPreviousBalancePayment: !isCurrent,
            targetPeriodYear: year,
            targetPeriodTerm: term,
            date: fullDateTime
        };
        
        activityItemPayments.push(paymentEntry);
        totalActivityAmount += cashEquivalent;
        
        console.log(`   ✅ Added: ${itemName} - ${finalQuantity} items (UGX ${formatMoney(cashEquivalent)})`);
    }
    
    // ========== CALCULATE TOTAL ==========
    const totalAmount = tuitionPaid + totalActivityAmount;
    
    console.log('📊 === PAYMENT SUMMARY ===');
    console.log(`💰 Tuition: UGX ${formatMoney(tuitionPaid)}`);
    console.log(`📦 Activity Total: UGX ${formatMoney(totalActivityAmount)}`);
    console.log(`💰 TOTAL AMOUNT: UGX ${formatMoney(totalAmount)}`);
    console.log(`📦 Activity Items Count: ${activityItemPayments.length}`);
    
    if (activityItemPayments.length > 0) {
        console.log('📋 Activity Items:');
        for (const p of activityItemPayments) {
            const amount = p.paymentType === 'paid_cash' ? p.amountPaid : p.cashEquivalent;
            const label = p.paymentType === 'paid_cash' ? '💵 Cash' : '📦 Items';
            console.log(`   • ${p.itemName}: ${label} UGX ${formatMoney(amount)}`);
        }
    }
    
    // ========== VALIDATE ==========
    if (totalAmount <= 0 && activityItemPayments.length === 0) {
        showToast('Please enter an amount to pay or select items to bring', 'warning');
        return;
    }
    
    if (totalAmount > 0 && activityItemPayments.length === 0 && tuitionPaid === 0) {
        showToast('Please enter a valid payment amount', 'warning');
        return;
    }
    
    // ========== PREVIOUS BALANCE CONFIRMATION ==========
    if (!isCurrent && totalAmount > 0) {
        const confirmMsg = `⚠️ You are about to pay for ${year} Term ${term} (Previous Balance).\n\n` +
                          `💰 Amount: UGX ${formatMoney(totalAmount)}\n` +
                          `📦 Items: ${activityItemPayments.length}\n\n` +
                          `This will be recorded as a previous balance payment.`;
        if (!confirm(confirmMsg)) {
            showToast('Payment cancelled', 'info');
            return;
        }
    }
    
    // ========== RECEIPT NUMBER ==========
    if (!receiptNumber || receiptNumber.trim() === '') {
        receiptNumber = await generateReceiptNumberWithPrefix(periodKey);
        const receiptInput = document.getElementById(`receiptNumber_${periodKey}`);
        if (receiptInput) receiptInput.value = receiptNumber;
    } else {
        receiptNumber = receiptNumber.trim();
    }
    
    console.log(`📋 Receipt: ${receiptNumber}`);
    
    // ========== BUILD PAYLOAD ==========
    const student = window.currentStudent;
    const payload = {
        studentId: student.id,
        studentName: `${student.firstName} ${student.lastName}`,
        admissionNumber: student.admissionNumber,
        term: term,
        academicYear: year.toString(),
        feeStructureId: periodData.feeStructure?.id || null,
        feeStructureName: periodData.feeStructure?.name || 'General Fee',
        bursaryId: student.appliedBursary?.id || null,
        bursaryName: student.appliedBursary?.name || null,
        tuitionPaid: tuitionPaid,
        activityItemPayments: activityItemPayments,
        totalAmount: totalAmount,
        method: method,
        receiptNumber: receiptNumber,
        reference: reference,
        notes: notes || (isCurrent ? '' : `Previous balance payment for ${year} Term ${term}`),
        date: fullDateTime,
        isPreviousBalancePayment: !isCurrent,
        targetPeriodYear: isCurrent ? null : year.toString(),
        targetPeriodTerm: isCurrent ? null : term,
        originalPeriod: isCurrent ? null : {
            year: currentAcademicSettings.currentYear,
            term: currentAcademicSettings.currentTerm
        }
    };
    
    console.log('📤 Sending payment payload...');
    console.log(`   Total: UGX ${formatMoney(totalAmount)}`);
    console.log(`   Items: ${activityItemPayments.length}`);
    
    // ========== DISABLE BUTTON ==========
    const submitBtn = document.querySelector(`#periodForm_${periodKey} .bg-green-600`);
    const originalText = submitBtn?.innerHTML || 'Submit';
    if (submitBtn) {
        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';
        submitBtn.disabled = true;
    }
    
    try {
        const response = await fetch('/api/fee/payments/enhanced', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        
        const result = await response.json();
        console.log('📥 Server response:', result);
        
        if (response.ok) {
            const periodLabel = isCurrent ? 'Current Period' : `${year} Term ${term}`;
            const remaining = period.total.balance - totalAmount;
            
            // ========== SHOW BEAUTIFUL CONFIRMATION MODAL ==========
            showPaymentConfirmationModal(
                result,                          // paymentResult
                periodLabel,                     // periodLabel
                !isCurrent,                      // isPreviousBalance
                totalAmount,                     // totalAmount
                tuitionPaid,                     // tuitionPaid
                activityItemPayments,            // activityItemPayments
                remaining                        // remainingBalance
            );
            
            // ========== REFRESH DATA IN BACKGROUND ==========
            setTimeout(async () => {
                await loadMultiPeriodCollectionForm(student.id);
            }, 500);
            
        } else {
            showToast('❌ Error: ' + (result.error || 'Unknown error'), 'error');
        }
    } catch (error) {
        console.error('Payment error:', error);
        showToast('Network error: ' + error.message, 'error');
    } finally {
        if (submitBtn) {
            submitBtn.innerHTML = originalText;
            submitBtn.disabled = false;
        }
    }
}

