// ==================== FIXED SUBMIT COLLECTION PAYMENT ====================
// This function is called by the form submission button
// It uses the same deduplication logic to ensure no double-counting

// ==================== FIXED SUBMIT COLLECTION PAYMENT ====================
// ==================== FIXED SUBMIT COLLECTION PAYMENT - ACCEPTS PARTIAL PAYMENTS ====================
// ==================== COMPLETE REBUILT SUBMIT COLLECTION PAYMENT ====================
// Version: 5.0 - With Previous Academic Period Balance Tracking

// ==================== COMPLETE REBUILT SUBMIT COLLECTION PAYMENT ====================
// Version: 8.0 - Full previous balance support with item-level payment

// ========== FIXED SUBMIT COLLECTION PAYMENT - INDIVIDUAL PAYMENTS ==========
// Version: 9.0 - Records INDIVIDUAL payment amounts, NOT cumulative totals

async function submitCollectionPaymentFixed() {
    console.log('=== SUBMIT COLLECTION PAYMENT v9.0 - INDIVIDUAL PAYMENTS ===');

    const student = window.currentCollectingStudent;
    if (!student) {
        alert('No student selected');
        return;
    }

    console.log('Student:', student.firstName, student.lastName);
    console.log('Previous Balances:', student.previousBalances?.length || 0);

    // ========== GET TUITION AMOUNT ==========
    const tuitionInput = document.getElementById('tuitionAmount');
    const tuitionPaid = Math.round(parseInt(tuitionInput?.value) || 0);
    const method = document.getElementById('paymentMethodSelect')?.value || 'cash';
    let receiptNumber = document.getElementById('receiptNumber')?.value || null;
    const reference = document.getElementById('paymentReference')?.value || '';
    const notes = document.getElementById('paymentNotes')?.value || '';

    const tuitionBalance = student.tuitionBalance || 0;
    
    // ========== CHECK FOR PREVIOUS BALANCE PAYMENT ==========
    let isPreviousBalancePayment = false;
    let targetYear = currentAcademicSettings.currentYear;
    let targetTerm = currentAcademicSettings.currentTerm;
    let originalPeriod = null;
    let isBulkPayment = false;
    let bulkPaymentId = null;

    if (window.previousBalancePaymentTarget) {
        isPreviousBalancePayment = true;
        targetYear = window.previousBalancePaymentTarget.year;
        targetTerm = window.previousBalancePaymentTarget.term;
        originalPeriod = {
            year: currentAcademicSettings.currentYear,
            term: currentAcademicSettings.currentTerm
        };
        isBulkPayment = window.isBulkPayment || false;
        bulkPaymentId = window.bulkPaymentId || null;
        
        console.log(`📅 PREVIOUS BALANCE PAYMENT: ${targetYear} Term ${targetTerm}`);
        window.previousBalancePaymentTarget = null;
    }

    // ========== VALIDATE TUITION PAYMENT ==========
    if (tuitionPaid > tuitionBalance && tuitionBalance > 0) {
        alert(`⚠️ Tuition payment cannot exceed the balance of UGX ${tuitionBalance.toLocaleString()}`);
        return;
    }

    // ========== GET STATUS GROUP DATA ==========
    const statusGroupData = student.statusGroupData || {};
    console.log('Status Group Data keys:', Object.keys(statusGroupData));

    // ========== HELPER: GET ITEM DETAILS FROM STATUS GROUP DATA ==========
    function getItemDetailsFromStatusGroup(componentName, itemName, periodType) {
        for (const [sgId, sgData] of Object.entries(statusGroupData)) {
            for (const component of (sgData.components || [])) {
                const compMatch = component.name && 
                    component.name.toLowerCase() === componentName.toLowerCase();
                if (!compMatch) continue;

                if (periodType && component.periodType && component.periodType !== periodType) {
                    continue;
                }

                for (const item of (component.items || [])) {
                    const itemMatch = item.name && 
                        item.name.toLowerCase() === itemName.toLowerCase();
                    if (itemMatch) {
                        return {
                            unitPrice: item.unitPrice || (item.totalAmount / (item.quantity || 1)) || 1,
                            quantityRequired: item.quantity || 1,
                            totalAmount: item.totalAmount || 0,
                            alreadyPaidCash: item.alreadyPaidCash || 0,
                            alreadyBroughtItems: item.alreadyBroughtItems || 0,
                            paymentOption: item.paymentOption || 'either',
                            isCustomized: item.isCustomized || false,
                            customReason: item.customReason || null,
                            customAmount: item.customAmount || null,
                            customQuantity: item.customQuantity || null,
                            defaultAmount: item.defaultAmount || item.totalAmount || 0,
                            defaultQuantity: item.defaultQuantity || item.quantity || 1,
                            remainingAmount: item.remainingAmount || 0,
                            remainingQuantity: item.remainingQuantity || 0,
                            periodType: component.periodType || 'termly',
                            isSpecialItem: item.isSpecialItem || false,
                            isCustomizedCashOnly: item.isCustomizedCashOnly || false,
                            isRemoved: item.isRemoved || false,
                            componentName: component.name,
                            itemId: item.id,
                            // ========== TRACK INDIVIDUAL PAYMENTS ==========
                            individualPayments: item.individualPayments || []
                        };
                    }
                }
            }
        }
        return null;
    }

    // ========== COLLECT ALL ACTIVITY ITEM PAYMENTS ==========
    const activityItemPayments = [];
    const processedKeys = new Set();

    // ========== PROCESS CASH PAYMENTS - INDIVIDUAL PAYMENTS ==========
    console.log('📊 === PROCESSING CASH PAYMENTS (INDIVIDUAL) ===');
    const cashInputs = document.querySelectorAll('.cash-amount-input');
    console.log(`Found ${cashInputs.length} cash inputs`);

    for (const input of cashInputs) {
        const rawAmount = parseFloat(input.value) || 0;
        const amount = Math.round(rawAmount);
        
        if (amount <= 0) continue;

        const itemName = input.dataset.itemName;
        const componentName = input.dataset.component;
        const periodType = input.dataset.period || 'termly';
        const isSpecial = input.dataset.special === 'true';
        const isCustomizedCashOnly = input.dataset.customizedCashOnly === 'true';

        if (!itemName || !componentName) continue;

        const paymentKey = `${componentName}|${itemName}|${periodType}|cash`;
        if (processedKeys.has(paymentKey)) continue;
        processedKeys.add(paymentKey);

        console.log(`💰 Individual cash payment: ${itemName} (${componentName}) - UGX ${amount}`);

        const itemDetails = getItemDetailsFromStatusGroup(componentName, itemName, periodType);
        
        // ========== CHECK IF THIS IS A SPECIAL ITEM ==========
        const isSpecialItem = itemDetails?.isSpecialItem || 
                              (componentName && (componentName.toLowerCase().includes('transport') || 
                                                 componentName.toLowerCase().includes('uniform'))) ||
                              (itemName && (itemName.toLowerCase().includes('transport') || 
                                            itemName.toLowerCase().includes('uniform') ||
                                            itemName.toLowerCase().includes('van')));

        // ========== CRITICAL: Calculate the remaining amount correctly ==========
        let remainingAmountForItem = 0;
        if (itemDetails) {
            const totalAmount = itemDetails.totalAmount || 0;
            const alreadyPaid = itemDetails.alreadyPaidCash || 0;
            const alreadyBrought = itemDetails.alreadyBroughtItems || 0;
            const unitPrice = itemDetails.unitPrice || 1;
            const quantityRequired = itemDetails.quantityRequired || 1;
            
            // Calculate remaining based on payment option
            if (itemDetails.paymentOption === 'cash_only') {
                remainingAmountForItem = Math.max(0, totalAmount - alreadyPaid);
            } else if (itemDetails.paymentOption === 'item_only') {
                remainingAmountForItem = Math.max(0, quantityRequired - alreadyBrought) * unitPrice;
            } else {
                // Either: items reduce cash needed
                const itemsValue = alreadyBrought * unitPrice;
                const totalPaidValue = alreadyPaid + itemsValue;
                const totalRequired = quantityRequired * unitPrice;
                remainingAmountForItem = Math.max(0, totalRequired - totalPaidValue);
            }
        } else {
            remainingAmountForItem = 1000000; // Fallback
        }

        if (isSpecialItem) {
            // ========== SPECIAL ITEM: ACCEPT ANY AMOUNT (INDIVIDUAL PAYMENT) ==========
            console.log(`🎯 SPECIAL ITEM detected: ${itemName}. Accepting any amount: UGX ${amount}`);
            
            const paymentEntry = {
                periodType: periodType || 'termly',
                componentName: componentName,
                itemName: itemName,
                paymentType: 'paid_cash',
                amountPaid: amount,  // <-- INDIVIDUAL PAYMENT AMOUNT
                itemsBrought: null,
                cashEquivalent: amount,
                quantityRequired: 1,
                unitPrice: 1,
                totalAmount: itemDetails?.totalAmount || amount,
                status: amount >= (itemDetails?.totalAmount || 0) ? 'fully_paid' : 'partial',
                isCustomized: itemDetails?.isCustomized || false,
                customReason: itemDetails?.customReason || null,
                customAmount: itemDetails?.customAmount || null,
                customQuantity: itemDetails?.customQuantity || null,
                defaultAmount: itemDetails?.defaultAmount || amount,
                defaultQuantity: itemDetails?.defaultQuantity || 1,
                isPreviousBalancePayment: isPreviousBalancePayment,
                targetPeriodYear: targetYear,
                targetPeriodTerm: targetTerm,
                receiptNumber: receiptNumber || null,
                isIndividualPayment: true,
                individualAmount: amount  // <-- Explicitly mark as individual amount
            };
            
            activityItemPayments.push(paymentEntry);
            console.log(`💵 SPECIAL individual payment added: ${itemName} - UGX ${amount}`);
            continue;
        }

        // ========== NORMAL ITEM PROCESSING ==========
        if (!itemDetails) {
            // Fallback: create a default entry
            const unitPrice = parseFloat(input.dataset.unitPrice) || 1;
            const quantityRequired = Math.ceil(amount / unitPrice);
            const paymentEntry = {
                periodType: periodType || 'termly',
                componentName: componentName,
                itemName: itemName,
                paymentType: 'paid_cash',
                amountPaid: amount,  // <-- INDIVIDUAL PAYMENT AMOUNT
                itemsBrought: null,
                cashEquivalent: amount,
                quantityRequired: quantityRequired || 1,
                unitPrice: unitPrice || 1,
                totalAmount: quantityRequired * unitPrice || amount,
                status: amount >= (quantityRequired * unitPrice) ? 'fully_paid' : 'partial',
                isCustomized: false,
                customReason: null,
                customAmount: null,
                customQuantity: null,
                defaultAmount: quantityRequired * unitPrice || amount,
                defaultQuantity: quantityRequired || 1,
                isPreviousBalancePayment: isPreviousBalancePayment,
                targetPeriodYear: targetYear,
                targetPeriodTerm: targetTerm,
                receiptNumber: receiptNumber || null,
                isIndividualPayment: true,
                individualAmount: amount
            };
            activityItemPayments.push(paymentEntry);
            console.log(`💵 Cash individual payment added (default): ${itemName} - UGX ${amount}`);
            continue;
        }

        const { 
            unitPrice, 
            quantityRequired, 
            totalAmount, 
            alreadyPaidCash, 
            isCustomized, 
            customReason, 
            customAmount, 
            customQuantity, 
            defaultAmount, 
            defaultQuantity 
        } = itemDetails;

        const effectiveTotalAmount = totalAmount || (quantityRequired * unitPrice);
        const remainingAmountEffective = Math.max(0, effectiveTotalAmount - alreadyPaidCash);
        
        // ========== CRITICAL: The payment is the INDIVIDUAL amount, not cumulative ==========
        const actualPayment = Math.min(amount, remainingAmountEffective);
        const itemsCovered = unitPrice > 0 ? Math.floor(actualPayment / unitPrice) : 0;
        const cashEquivalent = itemsCovered * unitPrice;

        if (cashEquivalent <= 0) continue;

        const newTotalPaid = alreadyPaidCash + cashEquivalent;
        const isFullyPaid = newTotalPaid >= effectiveTotalAmount;

        const paymentEntry = {
            periodType: periodType || 'termly',
            componentName: componentName,
            itemName: itemName,
            paymentType: 'paid_cash',
            amountPaid: cashEquivalent,  // <-- INDIVIDUAL PAYMENT AMOUNT
            itemsBrought: null,
            cashEquivalent: cashEquivalent,
            quantityRequired: quantityRequired || 1,
            unitPrice: unitPrice || 1,
            totalAmount: effectiveTotalAmount,
            status: isFullyPaid ? 'fully_paid' : 'partial',
            isCustomized: isCustomized || false,
            customReason: customReason || null,
            customAmount: customAmount || null,
            customQuantity: customQuantity || null,
            defaultAmount: defaultAmount || effectiveTotalAmount,
            defaultQuantity: defaultQuantity || quantityRequired,
            isPreviousBalancePayment: isPreviousBalancePayment,
            targetPeriodYear: targetYear,
            targetPeriodTerm: targetTerm,
            receiptNumber: receiptNumber || null,
            isIndividualPayment: true,
            individualAmount: cashEquivalent  // <-- Explicitly mark as individual amount
        };

        activityItemPayments.push(paymentEntry);
        console.log(`💵 Cash individual payment added: ${itemName} - UGX ${cashEquivalent} (${isFullyPaid ? 'Fully Paid' : 'Partial'})${isCustomized ? ' [Custom]' : ''}`);
    }

    // ========== PROCESS ITEM BRING PAYMENTS - INDIVIDUAL ==========
    console.log('📦 === PROCESSING ITEM BRING PAYMENTS (INDIVIDUAL) ===');
    const itemInputs = document.querySelectorAll('.item-quantity-input');
    console.log(`Found ${itemInputs.length} item inputs`);

    for (const input of itemInputs) {
        const quantity = Math.round(parseInt(input.value) || 0);
        if (quantity <= 0) continue;

        const itemName = input.dataset.itemName;
        const componentName = input.dataset.component;
        const periodType = input.dataset.period || 'termly';

        if (!itemName || !componentName) continue;

        const paymentKey = `${componentName}|${itemName}|${periodType}|item`;
        if (processedKeys.has(paymentKey)) continue;
        processedKeys.add(paymentKey);

        console.log(`📦 Individual item bring: ${itemName} (${componentName}) - ${quantity} items`);

        const itemDetails = getItemDetailsFromStatusGroup(componentName, itemName, periodType);
        if (!itemDetails) {
            const unitPrice = parseFloat(input.dataset.unitPrice) || 1;
            const quantityRequired = parseInt(input.dataset.maxItems) || quantity;

            const paymentEntry = {
                periodType: periodType || 'termly',
                componentName: componentName,
                itemName: itemName,
                paymentType: 'brought_item',
                amountPaid: null,
                itemsBrought: quantity,  // <-- INDIVIDUAL QUANTITY
                cashEquivalent: quantity * unitPrice,
                quantityRequired: quantityRequired || quantity,
                unitPrice: unitPrice,
                totalAmount: quantityRequired * unitPrice,
                status: quantity >= quantityRequired ? 'fully_paid' : 'partial',
                isCustomized: false,
                customReason: null,
                customAmount: null,
                customQuantity: null,
                defaultAmount: quantityRequired * unitPrice,
                defaultQuantity: quantityRequired || quantity,
                isPreviousBalancePayment: isPreviousBalancePayment,
                targetPeriodYear: targetYear,
                targetPeriodTerm: targetTerm,
                receiptNumber: receiptNumber || null,
                isIndividualPayment: true,
                individualQuantity: quantity
            };
            activityItemPayments.push(paymentEntry);
            console.log(`📦 Item bring individual payment added (default): ${itemName} - ${quantity} items`);
            continue;
        }

        const { 
            unitPrice, 
            quantityRequired, 
            totalAmount, 
            alreadyBroughtItems, 
            isCustomized, 
            customReason, 
            customAmount, 
            customQuantity, 
            defaultAmount, 
            defaultQuantity 
        } = itemDetails;

        const effectiveQuantityRequired = quantityRequired || 1;
        const remainingQuantity = Math.max(0, effectiveQuantityRequired - alreadyBroughtItems);
        const actualItemsBrought = Math.min(quantity, remainingQuantity);

        if (actualItemsBrought <= 0) continue;

        const cashEquivalent = Math.round(actualItemsBrought * (unitPrice || 1));
        const newTotalBrought = alreadyBroughtItems + actualItemsBrought;
        const isFullyPaid = newTotalBrought >= effectiveQuantityRequired;

        const paymentEntry = {
            periodType: periodType || 'termly',
            componentName: componentName,
            itemName: itemName,
            paymentType: 'brought_item',
            amountPaid: null,
            itemsBrought: actualItemsBrought,  // <-- INDIVIDUAL QUANTITY
            cashEquivalent: cashEquivalent,
            quantityRequired: effectiveQuantityRequired,
            unitPrice: unitPrice || 1,
            totalAmount: totalAmount || (effectiveQuantityRequired * unitPrice),
            status: isFullyPaid ? 'fully_paid' : 'partial',
            isCustomized: isCustomized || false,
            customReason: customReason || null,
            customAmount: customAmount || null,
            customQuantity: customQuantity || null,
            defaultAmount: defaultAmount || totalAmount,
            defaultQuantity: defaultQuantity || effectiveQuantityRequired,
            isPreviousBalancePayment: isPreviousBalancePayment,
            targetPeriodYear: targetYear,
            targetPeriodTerm: targetTerm,
            receiptNumber: receiptNumber || null,
            isIndividualPayment: true,
            individualQuantity: actualItemsBrought
        };

        activityItemPayments.push(paymentEntry);
        console.log(`📦 Item bring individual payment added: ${itemName} - ${actualItemsBrought} items (value: UGX ${cashEquivalent})${isCustomized ? ' [Custom]' : ''}`);
    }

    // ========== CALCULATE TOTALS ==========
    const activityTotal = activityItemPayments.reduce((sum, p) =>
        sum + (p.paymentType === 'paid_cash' ? (p.amountPaid || 0) : (p.cashEquivalent || 0)), 0);
    const totalAmount = tuitionPaid + activityTotal;

    console.log('📊 === INDIVIDUAL PAYMENT SUMMARY ===');
    console.log(`💰 Tuition: UGX ${tuitionPaid}`);
    console.log(`📦 Activity Total: UGX ${activityTotal}`);
    console.log(`💰 Total Amount: UGX ${totalAmount}`);
    console.log(`📦 Activity Items Count: ${activityItemPayments.length}`);
    
    // Log each individual payment
    console.log('💰 INDIVIDUAL PAYMENTS DETAIL:');
    for (const p of activityItemPayments) {
        if (p.paymentType === 'paid_cash') {
            console.log(`   💵 ${p.itemName}: UGX ${p.individualAmount || p.amountPaid}`);
        } else {
            console.log(`   📦 ${p.itemName}: ${p.individualQuantity || p.itemsBrought} items`);
        }
    }
    
    if (isPreviousBalancePayment) {
        console.log(`📅 Applied to: ${targetYear} Term ${targetTerm} (Previous Balance)`);
    }

    if (totalAmount <= 0 && activityItemPayments.length === 0) {
        alert('Please enter an amount to pay or select items to bring');
        return;
    }

    // ========== RECEIPT NUMBER HANDLING ==========
    if (!receiptNumber || receiptNumber.trim() === '') {
        const schoolRes = await fetch('/api/school');
        const schoolData = await schoolRes.json();
        const school = schoolData.school || {};
        const prefix = (school.schoolName || 'SCH').replace(/[^a-zA-Z0-9]/g, '').substring(0, 4).toUpperCase() || 'SCH';
        const timestamp = Date.now().toString().slice(-6);
        const random = Math.floor(Math.random() * 900 + 100).toString();
        receiptNumber = isPreviousBalancePayment ? 
            `PB${timestamp}${random}` : 
            `${prefix}${timestamp}${random}`;
        console.log('Auto-generated receipt number:', receiptNumber);
    } else {
        receiptNumber = receiptNumber.trim();
        console.log('📝 Using manually entered receipt number:', receiptNumber);
    }

    // ========== SUBMIT PAYMENT ==========
    const submitBtn = document.querySelector('#collectionForm button[type="button"]');
    const originalText = submitBtn.innerHTML;
    submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';
    submitBtn.disabled = true;

    try {
        // ========== BUILD PAYLOAD ==========
        const payload = {
            studentId: student.id,
            studentName: `${student.firstName} ${student.lastName}`,
            admissionNumber: student.admissionNumber,
            term: isPreviousBalancePayment ? targetTerm : currentAcademicSettings.currentTerm,
            academicYear: isPreviousBalancePayment ? targetYear.toString() : currentAcademicSettings.currentYear.toString(),
            feeStructureId: student.feeStructure?.id || null,
            feeStructureName: student.feeStructure?.name || 'General Fee',
            bursaryId: student.appliedBursary?.id || null,
            bursaryName: student.appliedBursary?.name || null,
            tuitionPaid: tuitionPaid,
            activityItemPayments: activityItemPayments,
            totalAmount: totalAmount,
            method: method,
            receiptNumber: receiptNumber,
            reference: reference,
            notes: notes || (isPreviousBalancePayment ? `Payment for ${targetYear} Term ${targetTerm} previous balance` : ''),
            hasCustomizations: activityItemPayments.some(p => p.isCustomized),
            customItemsCount: activityItemPayments.filter(p => p.isCustomized).length,
            studentCustomOverrides: student.customItemOverrides || {},
            hasPartialPayments: activityItemPayments.some(p => p.isPartialPayment),
            partialPaymentsCount: activityItemPayments.filter(p => p.isPartialPayment).length,
            isPreviousBalancePayment: isPreviousBalancePayment,
            targetPeriodYear: isPreviousBalancePayment ? targetYear.toString() : null,
            targetPeriodTerm: isPreviousBalancePayment ? targetTerm : null,
            originalPeriod: isPreviousBalancePayment ? {
                year: currentAcademicSettings.currentYear,
                term: currentAcademicSettings.currentTerm
            } : null,
            isBulkPayment: window.isBulkPayment || false,
            bulkPaymentId: window.bulkPaymentId || null,
            // ========== CRITICAL FIX: Mark as individual payments ==========
            isIndividualPayment: true,
            paymentMode: 'incremental'
        };

        console.log('📤 Sending INDIVIDUAL payment payload:', {
            totalAmount,
            activityItems: activityItemPayments.length,
            customItems: payload.customItemsCount,
            receiptNumber: receiptNumber,
            isPreviousBalancePayment: isPreviousBalancePayment,
            targetPeriod: isPreviousBalancePayment ? `${targetYear} T${targetTerm}` : 'Current',
            isIndividualPayment: true
        });

        const response = await fetch('/api/fee/payments/enhanced', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });

        const result = await response.json();

        if (response.ok) {
            // ========== BUILD SUCCESS MESSAGE ==========
            let message = `✅ INDIVIDUAL payment recorded!\n📋 Receipt: ${result.receiptNumber}\n💰 Amount: UGX ${totalAmount.toLocaleString()}\n`;

            if (isPreviousBalancePayment) {
                message += `📅 Applied to: ${targetYear} Term ${targetTerm} (Previous Balance)\n`;
                message += `   Original period: ${currentAcademicSettings.currentYear} Term ${currentAcademicSettings.currentTerm}\n\n`;
            } else {
                message += `📅 Applied to: ${currentAcademicSettings.currentYear} Term ${currentAcademicSettings.currentTerm}\n\n`;
            }

            if (tuitionPaid > 0) {
                message += `💰 Tuition: UGX ${tuitionPaid.toLocaleString()}\n`;
            }

            const cashPayments = activityItemPayments.filter(p => p.paymentType === 'paid_cash');
            const itemPayments = activityItemPayments.filter(p => p.paymentType === 'brought_item');

            if (cashPayments.length > 0) {
                message += `\n💵 Cash Payments (Individual):\n`;
                for (const p of cashPayments) {
                    const individualAmount = p.individualAmount || p.amountPaid || 0;
                    const customIndicator = p.isCustomized ? ' ⚡' : '';
                    const prevIndicator = p.isPreviousBalancePayment ? ' 📋Prev' : '';
                    message += `   • ${p.itemName}: UGX ${individualAmount.toLocaleString()}${customIndicator}${prevIndicator}\n`;
                }
            }

            if (itemPayments.length > 0) {
                message += `\n📦 Items Brought (Individual):\n`;
                for (const p of itemPayments) {
                    const individualQty = p.individualQuantity || p.itemsBrought || 0;
                    const remainingNeeded = p.quantityRequired - (p.itemsBrought || 0);
                    const statusText = remainingNeeded <= 0 ? '✓ Complete' : `⚠️ ${remainingNeeded} more needed`;
                    const customIndicator = p.isCustomized ? ' ⚡' : '';
                    const prevIndicator = p.isPreviousBalancePayment ? ' 📋Prev' : '';
                    message += `   • ${p.itemName}: ${individualQty} of ${p.quantityRequired} items (${statusText})${customIndicator}${prevIndicator}\n`;
                }
            }

            // Show remaining total balance
            const newTotalPaid = (student.totalPaid || 0) + totalAmount;
            const newBalance = (student.totalExpected || 0) - newTotalPaid;
            
            if (newBalance < 0) {
                message += `\n⚠️ Credit created: UGX ${Math.abs(newBalance).toLocaleString()}`;
            } else if (newBalance === 0 && !isPreviousBalancePayment) {
                message += `\n🎉 Student is now FULLY PAID for this term!`;
            } else if (!isPreviousBalancePayment) {
                message += `\nRemaining balance for this term: UGX ${newBalance.toLocaleString()}`;
            }

            alert(message);

            // ========== CLEAR CACHES ==========
            window.allStudentsData = null;
            window.enhancedStudentsData = null;
            window.dashboardStudents = null;
            window.previousBalancesData = [];
            window.previousBalancesTotal = 0;
            window.previousBalancePaymentTarget = null;
            window.isBulkPayment = false;
            window.bulkPaymentId = null;

            // ========== REFRESH ==========
            if (isPreviousBalancePayment) {
                const { currentYear: cy, currentTerm: ct } = currentAcademicSettings;
                const termName = getTermName(ct);
                await loadCollectionForm(student, cy, ct, termName);
            } else {
                showFeeManagement();
            }
        } else {
            alert('❌ Error: ' + (result.error || 'Unknown error'));
        }
    } catch (error) {
        console.error('Payment error:', error);
        alert('Network error: ' + error.message);
    } finally {
        submitBtn.innerHTML = originalText;
        submitBtn.disabled = false;
    }
}

// ========== HELPER FUNCTIONS FOR PREVIOUS BALANCE PAYMENTS ==========

// ========== PAY FULL PREVIOUS BALANCE ==========
// ==================== PAY FULL PREVIOUS BALANCE ====================
async function payFullPreviousBalance(studentId, year, term, balance) {
    console.log('=== PAY FULL PREVIOUS BALANCE ===');
    console.log('Student:', studentId, 'Year:', year, 'Term:', term, 'Balance:', balance);
    
    if (!balance || balance <= 0) {
        alert('No balance to pay for this period');
        return;
    }
    
    const student = window.currentCollectingStudent;
    if (!student) {
        alert('Student data not loaded');
        return;
    }
    
    // Confirm with user
    const confirmed = confirm(
        `⚠️ Pay full previous balance?\n\n` +
        `📅 Period: ${year} Term ${term}\n` +
        `💰 Amount: UGX ${formatMoney(balance)}\n` +
        `📦 Items: ${student.totalUnpaidItems || 0} item(s) remain\n\n` +
        `This payment will be recorded for ${year} Term ${term}.`
    );
    
    if (!confirmed) return;
    
    // Set the global target and trigger submission
    window.previousBalancePaymentTarget = {
        year: parseInt(year),
        term: parseInt(term)
    };
    window.isBulkPayment = false;
    window.bulkPaymentId = null;
    
    // Set the tuition amount to the balance
    const tuitionInput = document.getElementById('tuitionAmount');
    if (tuitionInput) {
        tuitionInput.value = balance;
        tuitionInput.dispatchEvent(new Event('input'));
    }
    
    // Submit the payment
    await submitCollectionPaymentFixed();
}

