// ==================== EXTRACT ITEMS FROM ACTIVITIES ====================

function extractItemsFromActivities(activities) {
    const items = [];
    activities.forEach(activity => {
        (activity.items || []).forEach(item => {
            items.push({
                componentId: activity.id,
                componentName: activity.name,
                periodType: activity.periodType,
                itemId: item.id,
                itemName: item.name,
                quantity: item.quantity || 1,
                totalAmount: item.totalAmount || 0,
                unitPrice: item.unitPrice || (item.totalAmount / (item.quantity || 1)),
                isTangible: item.isTangible !== false
            });
        });
    });
    return items;
}

// ==================== RENDER FULL ACTIVITY SECTION ====================

function renderFullActivitySection(items, periodType, title, color, icon, note) {
    if (!items || items.length === 0) return '';
    
    const bgColor = color === 'purple' ? 'bg-purple-50' : color === 'green' ? 'bg-green-50' : 'bg-orange-50';
    const borderColor = color === 'purple' ? 'border-purple-300' : color === 'green' ? 'border-green-300' : 'border-orange-300';
    const textColor = color === 'purple' ? 'text-purple-600' : color === 'green' ? 'text-green-600' : 'text-orange-600';
    
    return `
        <div class="border-2 ${borderColor} rounded-lg p-4 ${bgColor}">
            <div class="flex justify-between items-center mb-3 flex-wrap gap-2">
                <div class="flex items-center gap-2">
                    <div class="bg-${color}-600 text-white rounded-full w-8 h-8 flex items-center justify-center text-sm">${icon}</div>
                    <h3 class="font-bold text-lg">${title}</h3>
                </div>
                <span class="text-xs text-gray-500 italic">${note}</span>
            </div>
            <div id="${periodType}ItemsContainer" class="space-y-4 max-h-[500px] overflow-y-auto pr-2">
                ${items.map(item => renderFullItemRow(item, periodType, color)).join('')}
            </div>
            <div class="mt-4 pt-3 border-t ${borderColor} flex justify-between items-center font-bold">
                <span>Total ${title}:</span>
                <span id="${periodType}TotalAmountFinal" class="${textColor} text-xl">UGX 0</span>
            </div>
        </div>
    `;
}

