function renderPaymentHistoryRows(payments) {
    if (!payments || payments.length === 0) {
        return '<tr><td colspan="10" class="text-center p-8 text-gray-500">No payment records found</td></tr>';
    }
    
    return payments.slice().reverse().map(p => {
        const oneTimePaid = (p.paymentsByPeriodType?.one_time || []).reduce((s, i) => s + (i.amountPaid || i.cashEquivalent || 0), 0);
        const termlyPaid = (p.paymentsByPeriodType?.termly || []).reduce((s, i) => s + (i.amountPaid || i.cashEquivalent || 0), 0);
        const yearlyPaid = (p.paymentsByPeriodType?.yearly || []).reduce((s, i) => s + (i.amountPaid || i.cashEquivalent || 0), 0);
        
        return `
            <tr class="border-b hover:bg-gray-50">
                <td class="p-3">${new Date(p.date).toLocaleDateString()}</td>
                <td class="p-3 font-mono text-sm font-semibold text-blue-600">${p.receiptNumber}</td>
                <td class="p-3">${p.studentName || 'N/A'}</td>
                <td class="p-3 text-right">UGX ${(p.tuitionPaid || 0).toLocaleString()}</td>
                <td class="p-3 text-right">UGX ${oneTimePaid.toLocaleString()}</td>
                <td class="p-3 text-right">UGX ${termlyPaid.toLocaleString()}</td>
                <td class="p-3 text-right">UGX ${yearlyPaid.toLocaleString()}</td>
                <td class="p-3 text-right font-bold">UGX ${(p.totalAmount || 0).toLocaleString()}</td>
                <td class="p-3 capitalize">${p.method}</td>
                <td class="p-3"><button onclick="viewPaymentReceipt('${p.id}')" class="text-blue-600 hover:text-blue-800"><i class="fas fa-print"></i></button></td>
            </tr>
        `;
    }).join('');
}

function renderBalancesTableRows(students) {
    if (!students || students.length === 0) {
        return '<tr><td colspan="11" class="text-center p-8 text-gray-500">No students found</td></tr>';
    }
    
    return students.map(s => `
        <tr data-class="${s.currentClass || ''}" data-status="${s.status}">
            <td class="p-3 font-mono text-sm">${s.admissionNumber}</td>
            <td class="p-3 font-medium">${s.firstName} ${s.lastName}</td>
            <td class="p-3">${s.currentClass || 'N/A'}</td>
            <td class="p-3 text-right">
                UGX ${s.tuitionPaid.toLocaleString()}<br>
                <span class="text-xs text-gray-400">/ ${s.expectedTuition.toLocaleString()}</span>
            </td>
            <td class="p-3 text-right">
                UGX ${s.oneTimePaid.toLocaleString()}<br>
                <span class="text-xs text-gray-400">/ ${s.oneTimeTotal.toLocaleString()}</span>
            </td>
            <td class="p-3 text-right">
                UGX ${s.termlyPaid.toLocaleString()}<br>
                <span class="text-xs text-gray-400">/ ${s.termlyTotal.toLocaleString()}</span>
            </td>
            <td class="p-3 text-right">
                UGX ${s.yearlyPaid.toLocaleString()}<br>
                <span class="text-xs text-gray-400">/ ${s.yearlyTotal.toLocaleString()}</span>
            </td>
            <td class="p-3 text-right font-semibold text-green-600">UGX ${s.totalPaidThisTerm.toLocaleString()}</td>
            <td class="p-3 text-right font-bold ${s.balance > 0 ? 'text-red-600' : 'text-green-600'}">
                UGX ${Math.abs(s.balance).toLocaleString()}
            </td>
            <td class="p-3"><span class="px-2 py-1 rounded-full text-xs ${s.statusColor}">${s.status}</span></td>
            <td class="p-3 text-center">
                <button onclick="viewStudentFullFeeDetails('${s.id}')" class="text-blue-600 hover:text-blue-800" title="View Details">
                    <i class="fas fa-eye"></i>
                </button>
                <button onclick="loadStudentForCollection('${s.id}')" class="text-green-600 hover:text-green-800 ml-2" title="Make Payment">
                    <i class="fas fa-receipt"></i>
                </button>
            </td>
        </tr>
    `).join('');
}

function renderBursariesGrid(bursaries) {
    if (!bursaries || bursaries.length === 0) {
        return '<div class="col-span-3 text-center py-8 text-gray-500">No bursaries added</div>';
    }
    
    return bursaries.map(b => `
        <div class="border rounded-lg p-4 bg-gradient-to-r from-gray-50 to-white">
            <div class="flex justify-between items-start">
                <h4 class="font-bold text-lg">${b.name}</h4>
                <span class="px-2 py-1 rounded-full text-xs ${b.type === 'percentage' ? 'bg-blue-100 text-blue-800' : 'bg-green-100 text-green-800'}">
                    ${b.type === 'percentage' ? `${b.value}% OFF` : `UGX ${b.value.toLocaleString()} OFF`}
                </span>
            </div>
            <p class="text-sm text-gray-600 mt-1">${b.description || 'No description'}</p>
            <p class="text-xs text-gray-400 mt-2">Category: ${b.category || 'General'}</p>
            <div class="flex gap-2 mt-3 pt-2 border-t">
                <button onclick="editBursaryItem('${b.id}')" class="text-blue-600 text-sm hover:text-blue-800">
                    <i class="fas fa-edit"></i> Edit
                </button>
                <button onclick="deleteBursaryItem('${b.id}')" class="text-red-600 text-sm hover:text-red-800">
                    <i class="fas fa-trash"></i> Delete
                </button>
            </div>
        </div>
    `).join('');
}

// ==================== INITIALIZATION FUNCTIONS ====================

function initializeFeeTabs() {
    const tabs = document.querySelectorAll('.fee-tab');
    tabs.forEach(tab => {
        tab.addEventListener('click', () => {
            const tabId = tab.dataset.tab;
            tabs.forEach(t => {
                t.classList.remove('active', 'border-b-2', 'border-blue-600', 'text-blue-600');
                t.classList.add('text-gray-600');
            });
            tab.classList.add('active', 'border-b-2', 'border-blue-600', 'text-blue-600');
            tab.classList.remove('text-gray-600');
            
            document.querySelectorAll('.fee-tab-content').forEach(c => c.classList.add('hidden'));
            const activeTab = document.getElementById(tabId);
            if (activeTab) activeTab.classList.remove('hidden');
        });
    });
}

function initializeFeeSearchAndFilters(students) {
    const searchInput = document.getElementById('feeStudentSearch');
    const classFilter = document.getElementById('feeClassFilter');
    const statusFilter = document.getElementById('feeStatusFilter');
    const studentSelect = document.getElementById('collectStudentSelect');
    
    function filterStudents() {
        const searchTerm = searchInput?.value.toLowerCase().trim() || '';
        const classValue = classFilter?.value || '';
        const statusValue = statusFilter?.value || '';
        
        if (!studentSelect) return;
        
        let visibleCount = 0;
        let firstVisibleValue = null;
        
        for (let i = 1; i < studentSelect.options.length; i++) {
            const option = studentSelect.options[i];
            const optionText = option.text.toLowerCase();
            const optionAdmission = (option.getAttribute('data-admission') || '').toLowerCase();
            const optionClass = option.getAttribute('data-class') || '';
            const optionStatus = option.getAttribute('data-status') || '';
            
            let matchesSearch = true;
            if (searchTerm) {
                matchesSearch = optionText.includes(searchTerm) || optionAdmission.includes(searchTerm);
            }
            
            let matchesClass = true;
            if (classValue) {
                matchesClass = optionClass === classValue;
            }
            
            let matchesStatus = true;
            if (statusValue) {
                matchesStatus = optionStatus === statusValue;
            }
            
            const isVisible = matchesSearch && matchesClass && matchesStatus;
            option.style.display = isVisible ? '' : 'none';
            
            if (isVisible) {
                visibleCount++;
                if (!firstVisibleValue) {
                    firstVisibleValue = option.value;
                }
            }
        }
        
        const currentValue = studentSelect.value;
        if (visibleCount > 0 && (!currentValue || studentSelect.options[studentSelect.selectedIndex]?.style.display === 'none')) {
            if (firstVisibleValue) {
                studentSelect.value = firstVisibleValue;
                studentSelect.dispatchEvent(new Event('change'));
            }
        } else if (visibleCount === 0 && studentSelect.value) {
            studentSelect.value = '';
            document.getElementById('collectionFormContainer').innerHTML = '';
        }
    }
    
    if (searchInput) {
        searchInput.addEventListener('input', filterStudents);
        searchInput.addEventListener('keyup', filterStudents);
    }
    if (classFilter) classFilter.addEventListener('change', filterStudents);
    if (statusFilter) statusFilter.addEventListener('change', filterStudents);
    
    filterStudents();
}

function initializeBalanceFilters() {
    const balanceSearch = document.getElementById('balanceSearch');
    const balanceClassFilter = document.getElementById('balanceClassFilter');
    
    if (!balanceSearch || !balanceClassFilter) return;
    
    function filterBalances() {
        const searchTerm = balanceSearch.value.toLowerCase().trim();
        const classValue = balanceClassFilter.value;
        
        const rows = document.querySelectorAll('#balancesTableBody tr');
        let visibleCount = 0;
        
        rows.forEach(row => {
            const name = row.cells[1]?.innerText.toLowerCase() || '';
            const admission = row.cells[0]?.innerText.toLowerCase() || '';
            const rowClass = row.getAttribute('data-class') || '';
            
            let matchesSearch = true;
            if (searchTerm) {
                matchesSearch = name.includes(searchTerm) || admission.includes(searchTerm);
            }
            
            let matchesClass = true;
            if (classValue) {
                matchesClass = rowClass === classValue;
            }
            
            const isVisible = matchesSearch && matchesClass;
            row.style.display = isVisible ? '' : 'none';
            if (isVisible) visibleCount++;
        });
    }
    
    balanceSearch.addEventListener('input', filterBalances);
    balanceSearch.addEventListener('keyup', filterBalances);
    balanceClassFilter.addEventListener('change', filterBalances);
    
    filterBalances();
}

function loadStudentForCollection(studentId) {
    const studentSelect = document.getElementById('collectStudentSelect');
    if (studentSelect) {
        studentSelect.value = studentId;
        studentSelect.dispatchEvent(new Event('change'));
    }
    document.querySelector('.fee-tab[data-tab="collect"]')?.click();
}

async function refreshFeeStructures() {
    await showFeeManagement();
}

