// ==================== TOGGLE FEE STRUCTURE DETAILS ====================

function toggleFeeStructureDetails(structureId) {
    const detailsDiv = document.getElementById(`details_${structureId}`);
    const toggleIcon = document.getElementById(`toggleIcon_${structureId}`);
    
    if (detailsDiv) {
        if (detailsDiv.classList.contains('hidden')) {
            detailsDiv.classList.remove('hidden');
            if (toggleIcon) {
                toggleIcon.classList.remove('fa-chevron-down');
                toggleIcon.classList.add('fa-chevron-up');
            }
        } else {
            detailsDiv.classList.add('hidden');
            if (toggleIcon) {
                toggleIcon.classList.remove('fa-chevron-up');
                toggleIcon.classList.add('fa-chevron-down');
            }
        }
    }
}

// ==================== HELPER FUNCTION ====================

function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

// ==================== RENDER LEVEL COLUMN ====================

function renderLevelColumn(structures, levelKey, icon, title, subtitle) {
    if (!structures || structures.length === 0) {
        return `
            <div class="border rounded-xl overflow-hidden shadow-sm bg-white">
                <div class="bg-gradient-to-r from-gray-600 to-gray-700 text-white p-4 text-center">
                    <div class="flex items-center justify-between">
                        <div>
                            <h4 class="font-bold text-lg">${icon} ${title}</h4>
                            <p class="text-xs opacity-80 mt-0.5">${subtitle}</p>
                        </div>
                        <i class="fas ${levelKey === 'Nursery' ? 'fa-baby-carriage' : levelKey === 'LowerPrimary' ? 'fa-book-open' : 'fa-graduation-cap'} text-2xl opacity-50"></i>
                    </div>
                </div>
                <div class="p-6 text-center">
                    <div class="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-3">
                        <i class="fas fa-plus text-gray-400 text-2xl"></i>
                    </div>
                    <p class="text-gray-500 text-sm">No fee structures</p>
                    <button onclick="showAddFeeStructureModal()" class="mt-3 text-blue-600 text-sm hover:text-blue-800">
                        Add Fee Structure
                    </button>
                </div>
            </div>
        `;
    }
    
    return `
        <div class="border rounded-xl overflow-hidden shadow-sm bg-white">
            <div class="bg-gradient-to-r from-blue-600 to-purple-600 text-white p-4 text-center">
                <div class="flex items-center justify-between">
                    <div>
                        <h4 class="font-bold text-lg">${icon} ${title}</h4>
                        <p class="text-xs opacity-80 mt-0.5">${subtitle}</p>
                    </div>
                    <div class="text-right">
                        <p class="text-2xl font-bold">${structures.length}</p>
                        <p class="text-xs opacity-80">Structure(s)</p>
                    </div>
                </div>
            </div>
            <div class="p-3 max-h-[600px] overflow-y-auto space-y-4">
                ${structures.map(structure => renderFeeStructureCardItem(structure)).join('')}
            </div>
        </div>
    `;
}

// ==================== RENDER FEE STRUCTURE CARD ITEM ====================

// ==================== FIXED RENDER FEE STRUCTURE CARD ITEM ====================
// Version: 7.0 - Shows customization indicators

function renderFeeStructureCardItem(structure, studentOverrideMap) {
    const tuition = structure.tuition || 0;
    
    // Extract activities by period type
    const oneTimeActivities = (structure.activityComponents || []).filter(c => c.periodType === 'one_time');
    const termlyActivities = (structure.activityComponents || []).filter(c => c.periodType === 'termly');
    const yearlyActivities = (structure.activityComponents || []).filter(c => c.periodType === 'yearly');
    
    const oneTimeTotal = oneTimeActivities.reduce((sum, c) => sum + (c.totalAmount || 0), 0);
    const termlyTotal = termlyActivities.reduce((sum, c) => sum + (c.totalAmount || 0), 0);
    const yearlyTotal = yearlyActivities.reduce((sum, c) => sum + (c.totalAmount || 0), 0);
    const totalPerTerm = tuition + termlyTotal;
    
    // Group by status group
    const statusGroups = {};
    for (const component of structure.activityComponents || []) {
        const groupName = component.statusGroupName || 'Ungrouped';
        if (!statusGroups[groupName]) {
            statusGroups[groupName] = {
                name: groupName,
                periodTypes: new Set(),
                totalAmount: 0,
                count: 0,
                items: []
            };
        }
        statusGroups[groupName].periodTypes.add(component.periodType);
        statusGroups[groupName].totalAmount += component.totalAmount || 0;
        statusGroups[groupName].count++;
        
        // Check if any items in this group have custom overrides
        for (const item of (component.items || [])) {
            const itemId = item.id || item.name;
            const isCustomized = studentOverrideMap && studentOverrideMap[itemId] && studentOverrideMap[itemId].isActive !== false;
            statusGroups[groupName].items.push({
                ...item,
                componentName: component.name,
                periodType: component.periodType,
                isCustomized: isCustomized
            });
        }
    }
    
    // Helper function to get payment badge
    function getPaymentBadge(paymentOption) {
        if (paymentOption === 'cash_only') {
            return '<span class="bg-blue-100 text-blue-800 text-xs px-1.5 py-0.5 rounded-full">💵 Cash</span>';
        } else if (paymentOption === 'item_only') {
            return '<span class="bg-green-100 text-green-800 text-xs px-1.5 py-0.5 rounded-full">📦 Item</span>';
        } else {
            return '<span class="bg-purple-100 text-purple-800 text-xs px-1.5 py-0.5 rounded-full">🔄 Both</span>';
        }
    }
    
    // Helper function to render item details with customization indicator
    function renderItemDetails(item, isCustomized) {
        let details = '';
        if (item.paymentOption === 'cash_only') {
            details = `UGX ${(item.cashAmount || item.totalAmount || 0).toLocaleString()}`;
        } else if (item.paymentOption === 'item_only') {
            details = `${item.quantity} item(s)`;
        } else {
            const parts = [];
            if (item.cashAmount > 0) parts.push(`UGX ${item.cashAmount.toLocaleString()}`);
            if (item.quantity > 0) parts.push(`${item.quantity} item(s)`);
            details = parts.join(' + ');
        }
        
        if (isCustomized) {
            details += ' <span class="text-orange-500 text-xs font-bold">⚡ Custom</span>';
        }
        return details;
    }
    
    // Helper function to render collapsible activity group
    function renderActivityGroupCollapsible(components, title, color) {
        if (!components || components.length === 0) return '';
        
        const colorMap = {
            purple: { bg: 'bg-purple-50', border: 'border-purple-200', text: 'text-purple-700', icon: '⭐' },
            green: { bg: 'bg-green-50', border: 'border-green-200', text: 'text-green-700', icon: '📅' },
            orange: { bg: 'bg-orange-50', border: 'border-orange-200', text: 'text-orange-700', icon: '📆' }
        };
        const colors = colorMap[color];
        
        const total = components.reduce((sum, c) => sum + (c.totalAmount || 0), 0);
        
        return `
            <div class="${colors.bg} rounded-lg p-3 border ${colors.border} w-full">
                <div class="flex justify-between items-center mb-2">
                    <div class="flex items-center gap-2">
                        <span class="text-sm">${colors.icon}</span>
                        <span class="text-sm font-semibold ${colors.text}">${title}</span>
                    </div>
                    <span class="text-sm font-bold ${colors.text}">UGX ${total.toLocaleString()}</span>
                </div>
                <div class="space-y-2">
                    ${components.map(comp => `
                        <div class="bg-white rounded-lg p-2 text-sm">
                            <div class="flex justify-between items-center">
                                <span class="font-medium">📌 ${escapeHtml(comp.name)}</span>
                                <span class="font-semibold text-green-600">UGX ${(comp.totalAmount || 0).toLocaleString()}</span>
                            </div>
                            ${comp.statusGroupName ? `<p class="text-xs text-purple-600 mt-1">🏷️ ${escapeHtml(comp.statusGroupName)}</p>` : ''}
                            <div class="mt-2 pl-3 space-y-1">
                                ${(comp.items || []).map(item => {
                                    const itemId = item.id || item.name;
                                    const isCustomized = studentOverrideMap && studentOverrideMap[itemId] && studentOverrideMap[itemId].isActive !== false;
                                    const customClass = isCustomized ? 'border-l-2 border-l-orange-400 pl-2' : '';
                                    
                                    return `
                                        <div class="flex justify-between items-center text-xs border-b border-gray-100 pb-1 last:border-0 ${customClass}">
                                            <div class="flex items-center gap-2 flex-wrap">
                                                <span class="text-gray-600">📦 ${escapeHtml(item.name)}</span>
                                                ${getPaymentBadge(item.paymentOption)}
                                                ${isCustomized ? '<span class="text-orange-500 text-xs font-bold">⚡ Custom</span>' : ''}
                                            </div>
                                            <span class="font-medium text-green-600">${renderItemDetails(item, isCustomized)}</span>
                                        </div>
                                    `;
                                }).join('')}
                            </div>
                        </div>
                    `).join('')}
                </div>
            </div>
        `;
    }
    
    // Main card HTML
    return `
        <div class="border rounded-lg p-4 bg-white shadow-sm hover:shadow-md transition-all duration-200 w-full">
            <!-- Header with Name and Actions -->
            <div class="flex justify-between items-start mb-3 pb-2 border-b">
                <div class="flex-1">
                    <h5 class="font-bold text-md text-gray-800 break-words">${escapeHtml(structure.name)}</h5>
                    <div class="flex flex-wrap gap-1 mt-1">
                        ${oneTimeTotal > 0 ? '<span class="bg-purple-100 text-purple-700 text-xs px-2 py-0.5 rounded-full">⭐ One-Time</span>' : ''}
                        ${termlyTotal > 0 ? '<span class="bg-green-100 text-green-700 text-xs px-2 py-0.5 rounded-full">📅 Termly</span>' : ''}
                        ${yearlyTotal > 0 ? '<span class="bg-orange-100 text-orange-700 text-xs px-2 py-0.5 rounded-full">📆 Yearly</span>' : ''}
                    </div>
                </div>
                <div class="flex gap-1 flex-shrink-0">
                    <button onclick="editFeeStructureItem('${structure.id}')" class="text-blue-600 hover:text-blue-800 p-1 rounded hover:bg-blue-50 transition" title="Edit">
                        <i class="fas fa-edit text-sm"></i>
                    </button>
                    <button onclick="deleteFeeStructureItem('${structure.id}')" class="text-red-600 hover:text-red-800 p-1 rounded hover:bg-red-50 transition" title="Delete">
                        <i class="fas fa-trash text-sm"></i>
                    </button>
                </div>
            </div>
            
            <!-- Tuition - Full Width -->
            <div class="bg-blue-50 rounded-lg p-3 mb-3 w-full">
                <div class="flex justify-between items-center">
                    <div class="flex items-center gap-2">
                        <div class="w-7 h-7 bg-blue-500 rounded-full flex items-center justify-center">
                            <i class="fas fa-money-bill-wave text-white text-xs"></i>
                        </div>
                        <span class="text-sm font-semibold text-blue-700">Tuition Fee</span>
                    </div>
                    <div class="text-right">
                        <span class="font-bold text-blue-700 text-lg">UGX ${tuition.toLocaleString()}</span>
                        <p class="text-xs text-gray-500">per term</p>
                    </div>
                </div>
            </div>
            
            <!-- Status Groups Quick Summary with Customization Count -->
            ${Object.keys(statusGroups).length > 0 ? `
                <div class="mb-3 w-full">
                    <div class="flex items-center gap-1 mb-2">
                        <i class="fas fa-tags text-purple-500 text-xs"></i>
                        <span class="text-xs font-semibold text-gray-600 uppercase">Status Groups</span>
                    </div>
                    <div class="flex flex-wrap gap-2">
                        ${Object.values(statusGroups).map(sg => {
                            const customCount = sg.items.filter(i => i.isCustomized).length;
                            const customBadge = customCount > 0 ? 
                                `<span class="text-xs text-orange-500 ml-1">(⚡${customCount} customized)</span>` : '';
                            
                            return `
                                <div class="bg-gray-100 rounded-full px-3 py-1 inline-flex items-center gap-2">
                                    <span class="text-xs">🏷️ ${escapeHtml(sg.name)}</span>
                                    <span class="text-xs font-bold text-green-600">UGX ${sg.totalAmount.toLocaleString()}</span>
                                    ${customBadge}
                                </div>
                            `;
                        }).join('')}
                    </div>
                </div>
            ` : ''}
            
            <!-- Activity Items (Collapsible) -->
            ${(oneTimeActivities.length > 0 || termlyActivities.length > 0 || yearlyActivities.length > 0) ? `
                <div class="mt-2 w-full">
                    <button onclick="toggleFeeStructureDetails('${structure.id}')" class="w-full text-left text-sm text-blue-600 hover:text-blue-800 flex items-center justify-between py-2 px-2 bg-gray-50 rounded-lg">
                        <span><i class="fas fa-boxes mr-2"></i> View Items (${(oneTimeActivities.length + termlyActivities.length + yearlyActivities.length)} groups)</span>
                        <i class="fas fa-chevron-down transition-transform" id="toggleIcon_${structure.id}"></i>
                    </button>
                    <div id="details_${structure.id}" class="hidden mt-3 space-y-3">
                        ${renderActivityGroupCollapsible(oneTimeActivities, 'One-Time', 'purple')}
                        ${renderActivityGroupCollapsible(termlyActivities, 'Termly', 'green')}
                        ${renderActivityGroupCollapsible(yearlyActivities, 'Yearly', 'orange')}
                    </div>
                </div>
            ` : ''}
            
            <!-- Total Summary - Full Width -->
            <div class="mt-3 pt-3 border-t w-full">
                <div class="flex justify-between items-center">
                    <div>
                        <span class="text-sm font-semibold text-gray-700">Total Per Term:</span>
                        <p class="text-xs text-gray-500">Tuition + Termly fees</p>
                    </div>
                    <span class="text-xl font-bold text-purple-700">UGX ${totalPerTerm.toLocaleString()}</span>
                </div>
                ${oneTimeTotal > 0 ? `
                    <div class="flex justify-between items-center mt-2 pt-1">
                        <span class="text-sm text-gray-600">+ One-Time (once):</span>
                        <span class="text-sm font-semibold text-purple-600">UGX ${oneTimeTotal.toLocaleString()}</span>
                    </div>
                ` : ''}
                ${yearlyTotal > 0 ? `
                    <div class="flex justify-between items-center mt-1">
                        <span class="text-sm text-gray-600">+ Yearly (once):</span>
                        <span class="text-sm font-semibold text-orange-600">UGX ${yearlyTotal.toLocaleString()}</span>
                    </div>
                ` : ''}
            </div>
        </div>
    `;
}

// ==================== TOGGLE FEE STRUCTURE DETAILS ====================

function toggleFeeStructureDetails(structureId) {
    const detailsDiv = document.getElementById(`details_${structureId}`);
    const toggleIcon = document.getElementById(`toggleIcon_${structureId}`);
    
    if (detailsDiv) {
        if (detailsDiv.classList.contains('hidden')) {
            detailsDiv.classList.remove('hidden');
            if (toggleIcon) {
                toggleIcon.classList.remove('fa-chevron-down');
                toggleIcon.classList.add('fa-chevron-up');
            }
        } else {
            detailsDiv.classList.add('hidden');
            if (toggleIcon) {
                toggleIcon.classList.remove('fa-chevron-up');
                toggleIcon.classList.add('fa-chevron-down');
            }
        }
    }
}

// ==================== HELPER FUNCTION ====================

function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function renderStructureGroup(structures, levelName, icon) {
    if (structures.length === 0) {
        return `<div class="border rounded-xl p-4 text-center bg-gray-50">
                    <div class="text-3xl mb-2">${icon}</div>
                    <h3 class="font-semibold">${levelName}</h3>
                    <p class="text-sm text-gray-500">No fee structures</p>
                </div>`;
    }
    
    return `
        <div class="border rounded-xl overflow-hidden shadow-sm">
            <div class="bg-gradient-to-r from-blue-500 to-blue-600 text-white p-3 text-center font-semibold">${icon} ${levelName}</div>
            <div class="p-3 max-h-96 overflow-y-auto">
                ${structures.map(s => {
                    // Calculate totals from components
                    const tuitionAmount = s.tuition || 0;
                    const activityTotal = s.activityTotal || (s.activityComponents || []).reduce((sum, c) => sum + (c.amount || 0), 0);
                    const developmentTotal = s.developmentTotal || (s.developmentComponents || []).reduce((sum, c) => sum + (c.amount || 0), 0);
                    
                    return `
                        <div class="border-b pb-3 mb-3 last:border-0">
                            <div class="flex justify-between items-start">
                                <h4 class="font-bold">${s.name}</h4>
                                <div class="flex gap-1">
                                    <button onclick="editFeeStructureItem('${s.id}')" class="text-blue-600 text-sm" title="Edit"><i class="fas fa-edit"></i></button>
                                    <button onclick="deleteFeeStructureItem('${s.id}')" class="text-red-600 text-sm" title="Delete"><i class="fas fa-trash"></i></button>
                                </div>
                            </div>
                            <div class="mt-2 space-y-1 text-sm">
                                <div><span class="font-semibold text-blue-600">💰 Tuition:</span> UGX ${tuitionAmount.toLocaleString()}</div>
                                ${s.activityComponents && s.activityComponents.length > 0 ? `
                                    <div><span class="font-semibold text-green-600">🎯 Activity:</span> ${s.activityComponents.length} item(s) - UGX ${activityTotal.toLocaleString()}</div>
                                ` : ''}
                                ${s.developmentComponents && s.developmentComponents.length > 0 ? `
                                    <div><span class="font-semibold text-orange-600">🏗️ Development:</span> ${s.developmentComponents.length} item(s) - UGX ${developmentTotal.toLocaleString()}</div>
                                ` : ''}
                                ${s.tangibleRequirements && s.tangibleRequirements.length > 0 ? `
                                    <div><span class="font-semibold text-yellow-600">📦 Tangible:</span> ${s.tangibleRequirements.length} item(s)</div>
                                ` : ''}
                            </div>
                        </div>
                    `;
                }).join('')}
            </div>
        </div>
    `;
}

