// ==================== ENHANCED COLLECTION FORM INITIALIZATION ====================

function initEnhancedCollectionForm(isFirstPaymentPeriod) {
    const studentSelect = document.getElementById('feeStudent');
    if (!studentSelect) return;
    
    studentSelect.addEventListener('change', async function() {
        const studentId = this.value;
        if (!studentId) return;
        
        const selectedOption = this.options[this.selectedIndex];
        const studentName = selectedOption.dataset.name;
        const admissionNumber = selectedOption.dataset.admission;
        
        // Get student's fee structure and assignment
        const assignment = window.feeAssignmentsData?.find(a => a.studentId === studentId) || {};
        const feeStructure = window.feeStructuresData?.find(f => f.id === assignment.feeStructureId);
        
        if (feeStructure) {
            // Display fee structure info
            const infoDiv = document.getElementById('selectedFeeStructureInfo');
            if (infoDiv) {
                document.getElementById('selectedFsName').innerText = feeStructure.name;
                document.getElementById('displayTuition').innerHTML = `UGX ${(feeStructure.tuition || 0).toLocaleString()}`;
                document.getElementById('displayActivityTotal').innerHTML = `UGX ${(feeStructure.activityTotal || 0).toLocaleString()}`;
                document.getElementById('displayDevelopmentTotal').innerHTML = `UGX ${(feeStructure.developmentTotal || 0).toLocaleString()}`;
                infoDiv.classList.remove('hidden');
            }
            
            // Load activity components checklist
            if (isFirstPaymentPeriod) {
                loadActivityComponentsChecklist(feeStructure, studentId);
                loadDevelopmentComponentsChecklist(feeStructure, studentId);
                loadTangibleRequirementsChecklist(feeStructure, studentId);
            }
            
            // Get existing payments for this student to show already paid components
            await loadStudentExistingPayments(studentId);
        }
        
        // Set max tuition amount
        const tuitionInput = document.getElementById('tuitionPaid');
        if (tuitionInput && feeStructure) {
            tuitionInput.max = feeStructure.tuition || 0;
            tuitionInput.placeholder = `Max: UGX ${(feeStructure.tuition || 0).toLocaleString()}`;
        }
    });
}

function loadActivityComponentsChecklist(feeStructure, studentId) {
    const container = document.getElementById('activityComponentsChecklist');
    if (!container || !feeStructure.activityComponents) return;
    
    container.innerHTML = feeStructure.activityComponents.map(comp => `
        <label class="flex items-center justify-between p-2 bg-white rounded-lg border cursor-pointer hover:bg-blue-50">
            <div class="flex items-center">
                <input type="checkbox" class="activity-component-checkbox mr-3" data-id="${comp.id}" data-name="${comp.name}" data-amount="${comp.amount}" onchange="updateSelectedActivityTotal()">
                <span>${comp.name}</span>
            </div>
            <span class="font-semibold">UGX ${comp.amount.toLocaleString()}</span>
        </label>
    `).join('');
}

function loadDevelopmentComponentsChecklist(feeStructure, studentId) {
    const container = document.getElementById('developmentComponentsChecklist');
    if (!container || !feeStructure.developmentComponents) return;
    
    container.innerHTML = feeStructure.developmentComponents.map(comp => `
        <label class="flex items-center justify-between p-2 bg-white rounded-lg border cursor-pointer hover:bg-green-50">
            <div class="flex items-center">
                <input type="checkbox" class="development-component-checkbox mr-3" data-id="${comp.id}" data-name="${comp.name}" data-amount="${comp.amount}" onchange="updateSelectedDevelopmentTotal()">
                <span>${comp.name}</span>
            </div>
            <span class="font-semibold">UGX ${comp.amount.toLocaleString()}</span>
        </label>
    `).join('');
}

function loadTangibleRequirementsChecklist(feeStructure, studentId) {
    const container = document.getElementById('tangibleRequirementsChecklist');
    if (!container || !feeStructure.tangibleRequirements) return;
    
    container.innerHTML = feeStructure.tangibleRequirements.map(req => `
        <label class="flex items-center p-2 bg-white rounded-lg border cursor-pointer hover:bg-yellow-50">
            <input type="checkbox" class="tangible-requirement-checkbox mr-3" data-id="${req.id}" data-name="${req.name}" onchange="updateTangibleRequirementsList()">
            <span>${req.name}</span>
            <input type="number" placeholder="Qty" class="ml-auto w-20 border rounded px-2 py-1 text-sm quantity-input" data-id="${req.id}" disabled>
        </label>
    `).join('');
    
    // Enable quantity inputs when checkbox is checked
    document.querySelectorAll('.tangible-requirement-checkbox').forEach(cb => {
        cb.addEventListener('change', function() {
            const quantityInput = this.closest('label').querySelector('.quantity-input');
            if (quantityInput) quantityInput.disabled = !this.checked;
        });
    });
}

async function loadStudentExistingPayments(studentId) {
    try {
        const { currentYear, currentTerm } = currentAcademicSettings;
        const response = await fetch(`/api/fee/payments?year=${currentYear}&term=${currentTerm}&studentId=${studentId}`);
        const payments = await response.json();
        
        // Mark already paid components as checked and disabled
        payments.forEach(payment => {
            if (payment.activityComponentsPaid) {
                payment.activityComponentsPaid.forEach(paidComp => {
                    const checkbox = document.querySelector(`.activity-component-checkbox[data-id="${paidComp.id}"]`);
                    if (checkbox && !checkbox.checked) {
                        checkbox.checked = true;
                        checkbox.disabled = true;
                        // Add a badge to show it was already paid
                        const label = checkbox.closest('label');
                        if (label) {
                            label.classList.add('bg-green-100', 'opacity-75');
                            const paidBadge = document.createElement('span');
                            paidBadge.className = 'ml-2 text-xs text-green-600';
                            paidBadge.innerHTML = '(✓ Already Paid)';
                            label.querySelector('.flex.items-center').appendChild(paidBadge);
                        }
                    }
                });
            }
        });
        
        updateSelectedActivityTotal();
        updateSelectedDevelopmentTotal();
        
    } catch (error) {
        console.error('Error loading existing payments:', error);
    }
}

function updateSelectedActivityTotal() {
    let total = 0;
    document.querySelectorAll('.activity-component-checkbox:checked').forEach(cb => {
        total += parseInt(cb.dataset.amount) || 0;
    });
    const totalSpan = document.getElementById('selectedActivityTotal');
    if (totalSpan) totalSpan.innerHTML = `UGX ${total.toLocaleString()}`;
    calculateTotalPayment();
}

function updateSelectedDevelopmentTotal() {
    let total = 0;
    document.querySelectorAll('.development-component-checkbox:checked').forEach(cb => {
        total += parseInt(cb.dataset.amount) || 0;
    });
    const totalSpan = document.getElementById('selectedDevelopmentTotal');
    if (totalSpan) totalSpan.innerHTML = `UGX ${total.toLocaleString()}`;
    calculateTotalPayment();
}

function calculateTotalPayment() {
    const tuition = parseInt(document.getElementById('tuitionPaid')?.value) || 0;
    
    let activityTotal = 0;
    document.querySelectorAll('.activity-component-checkbox:checked').forEach(cb => {
        activityTotal += parseInt(cb.dataset.amount) || 0;
    });
    
    let developmentTotal = 0;
    document.querySelectorAll('.development-component-checkbox:checked').forEach(cb => {
        developmentTotal += parseInt(cb.dataset.amount) || 0;
    });
    
    const totalPayment = tuition + activityTotal + developmentTotal;
    
    document.getElementById('summaryTuitionPaid').innerHTML = `UGX ${tuition.toLocaleString()}`;
    document.getElementById('summaryActivityPaid').innerHTML = `UGX ${activityTotal.toLocaleString()}`;
    document.getElementById('summaryDevelopmentPaid').innerHTML = `UGX ${developmentTotal.toLocaleString()}`;
    document.getElementById('totalPaymentAmount').innerHTML = `UGX ${totalPayment.toLocaleString()}`;
    
    // Calculate outstanding after payment
    const expectedPerTerm = parseInt(document.getElementById('displayTuition')?.innerHTML?.replace(/[^0-9]/g, '') || 0) +
                           parseInt(document.getElementById('displayActivityTotal')?.innerHTML?.replace(/[^0-9]/g, '') || 0) +
                           parseInt(document.getElementById('displayDevelopmentTotal')?.innerHTML?.replace(/[^0-9]/g, '') || 0);
    const outstandingAfter = expectedPerTerm - totalPayment;
    const outstandingSpan = document.getElementById('outstandingAfterPayment');
    if (outstandingSpan) {
        outstandingSpan.innerHTML = `UGX ${Math.max(0, outstandingAfter).toLocaleString()}`;
        if (outstandingAfter <= 0) {
            outstandingSpan.classList.add('text-green-600');
            outstandingSpan.classList.remove('text-red-600');
        } else {
            outstandingSpan.classList.add('text-red-600');
            outstandingSpan.classList.remove('text-green-600');
        }
    }
}

function setFullTuition() {
    const checkbox = document.getElementById('fullTuitionCheckbox');
    const tuitionInput = document.getElementById('tuitionPaid');
    if (checkbox.checked && tuitionInput) {
        tuitionInput.value = tuitionInput.max;
        calculateTotalPayment();
    } else if (tuitionInput) {
        tuitionInput.value = 0;
        calculateTotalPayment();
    }
}

function filterActivityComponents() {
    const searchInput = document.getElementById('activitySearchInput');
    const searchTerm = searchInput.value.toLowerCase();
    const labels = document.querySelectorAll('#activityComponentsChecklist label');
    
    labels.forEach(label => {
        const text = label.innerText.toLowerCase();
        if (text.includes(searchTerm)) {
            label.style.display = '';
        } else {
            label.style.display = 'none';
        }
    });
}

function toggleActivitySearch() {
    const searchInput = document.getElementById('activitySearchInput');
    if (searchInput) {
        searchInput.classList.toggle('hidden');
        if (!searchInput.classList.contains('hidden')) {
            searchInput.focus();
        } else {
            searchInput.value = '';
            filterActivityComponents();
        }
    }
}

function resetCollectionForm() {
    document.getElementById('feeStudent').value = '';
    document.getElementById('paymentMethod').value = 'cash';
    document.getElementById('tuitionPaid').value = '0';
    document.getElementById('fullTuitionCheckbox').checked = false;
    document.getElementById('paymentReference').value = '';
    document.getElementById('paymentNotes').value = '';
    
    // Uncheck all checkboxes
    document.querySelectorAll('.activity-component-checkbox, .development-component-checkbox, .tangible-requirement-checkbox').forEach(cb => {
        cb.checked = false;
        cb.disabled = false;
    });
    
    // Reset quantity inputs
    document.querySelectorAll('.quantity-input').forEach(input => {
        input.value = '';
        input.disabled = true;
    });
    
    // Hide fee structure info
    const infoDiv = document.getElementById('selectedFeeStructureInfo');
    if (infoDiv) infoDiv.classList.add('hidden');
    
    calculateTotalPayment();
}

function loadStudentForPayment(studentId) {
    const studentSelect = document.getElementById('feeStudent');
    if (studentSelect) {
        studentSelect.value = studentId;
        studentSelect.dispatchEvent(new Event('change'));
    }
    
    // Switch to collect fees tab
    const collectTab = document.querySelector('.fee-tab[data-tab="collect-fees"]');
    if (collectTab) collectTab.click();
}

function exportBalancesReport() {
    const students = window.enhancedStudentsData || [];
    const exportData = students.map(s => ({
        'Admission Number': s.admissionNumber,
        'Student Name': `${s.firstName} ${s.lastName}`,
        'Class': s.currentClass || 'N/A',
        'Fee Structure': s.feeStructure?.name || 'Not Assigned',
        'Bursary': s.appliedBursary?.name || 'None',
        'Expected Per Term': s.expectedPerTerm,
        'Paid This Term': s.currentTermPaid,
        'Balance': s.currentTermBalance,
        'Status': s.status
    }));
    
    const csv = convertToCSV(exportData);
    downloadCSV(csv, `fee_balances_${new Date().toISOString().split('T')[0]}.csv`);
    alert('✅ Balances exported successfully');
}

function initializeBalanceFilters() {
    const searchInput = document.getElementById('balanceSearch');
    const classFilter = document.getElementById('classFilter');
    const statusFilter = document.getElementById('statusFilter');
    
    const filterFunction = () => {
        const searchTerm = searchInput?.value.toLowerCase() || '';
        const classValue = classFilter?.value || '';
        const statusValue = statusFilter?.value || '';
        
        const rows = document.querySelectorAll('#balancesTableBody tr');
        rows.forEach(row => {
            const name = row.cells[1]?.innerText.toLowerCase() || '';
            const admission = row.cells[0]?.innerText.toLowerCase() || '';
            const studentClass = row.cells[2]?.innerText || '';
            const statusSpan = row.cells[7]?.querySelector('span')?.innerText || '';
            
            let statusMatch = true;
            if (statusValue === 'paid') statusMatch = statusSpan === 'Good Standing';
            else if (statusValue === 'partial') statusMatch = statusSpan === 'Partial Payment';
            else if (statusValue === 'overdue') statusMatch = statusSpan === 'Critical Overdue';
            
            const matchesSearch = searchTerm === '' || name.includes(searchTerm) || admission.includes(searchTerm);
            const matchesClass = classValue === '' || studentClass === classValue;
            
            row.style.display = matchesSearch && matchesClass && statusMatch ? '' : 'none';
        });
    };
    
    if (searchInput) searchInput.addEventListener('input', filterFunction);
    if (classFilter) classFilter.addEventListener('change', filterFunction);
    if (statusFilter) statusFilter.addEventListener('change', filterFunction);
}

// Update the fee collection form submission handler
document.addEventListener('submit', async function(e) {
    if (e.target && e.target.id === 'feeCollectionForm') {
        e.preventDefault();
        
        const studentId = document.getElementById('feeStudent')?.value;
        const studentSelect = document.getElementById('feeStudent');
        const studentName = studentSelect?.options[studentSelect.selectedIndex]?.dataset.name || '';
        const admissionNumber = studentSelect?.options[studentSelect.selectedIndex]?.dataset.admission || '';
        const tuitionPaid = parseInt(document.getElementById('tuitionPaid')?.value) || 0;
        const method = document.getElementById('paymentMethod')?.value || 'cash';
        const reference = document.getElementById('paymentReference')?.value || '';
        const notes = document.getElementById('paymentNotes')?.value || '';
        
        if (!studentId) {
            alert('Please select a student');
            return;
        }
        
        // Collect selected activity components
        const selectedActivityComponents = [];
        document.querySelectorAll('.activity-component-checkbox:checked').forEach(cb => {
            selectedActivityComponents.push({
                id: cb.dataset.id,
                name: cb.dataset.name,
                amount: parseInt(cb.dataset.amount) || 0
            });
        });
        
        // Collect selected development components
        const selectedDevelopmentComponents = [];
        document.querySelectorAll('.development-component-checkbox:checked').forEach(cb => {
            selectedDevelopmentComponents.push({
                id: cb.dataset.id,
                name: cb.dataset.name,
                amount: parseInt(cb.dataset.amount) || 0
            });
        });
        
        // Collect tangible requirements being brought
        const selectedTangibleRequirements = [];
        document.querySelectorAll('.tangible-requirement-checkbox:checked').forEach(cb => {
            const label = cb.closest('label');
            const quantityInput = label?.querySelector('.quantity-input');
            selectedTangibleRequirements.push({
                id: cb.dataset.id,
                name: cb.dataset.name,
                quantity: parseInt(quantityInput?.value) || 1
            });
        });
        
        const totalAmount = tuitionPaid + 
                           selectedActivityComponents.reduce((s, c) => s + c.amount, 0) + 
                           selectedDevelopmentComponents.reduce((s, c) => s + c.amount, 0);
        
        if (totalAmount <= 0) {
            alert('Please enter an amount to pay');
            return;
        }
        
        const feeStructureId = window.feeStructuresData?.find(f => f.id === window.currentFeeStructureId)?.id || null;
        
        const submitBtn = e.target.querySelector('button[type="submit"]');
        const originalText = submitBtn.innerText;
        submitBtn.innerText = 'Processing...';
        submitBtn.disabled = true;
        
        try {
            const response = await fetch('/api/fee/payments/enhanced', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    studentId,
                    studentName,
                    admissionNumber,
                    term: currentAcademicSettings.currentTerm,
                    academicYear: currentAcademicSettings.currentYear.toString(),
                    feeStructureId,
                    tuitionPaid,
                    selectedActivityComponents,
                    selectedDevelopmentComponents,
                    selectedTangibleRequirements,
                    totalAmount,
                    method,
                    reference,
                    notes,
                    isFirstPaymentOfTerm: window.isWithinFirstMonth
                })
            });
            
            if (response.ok) {
                const result = await response.json();
                alert(`✅ Payment recorded successfully!\nReceipt Number: ${result.receiptNumber}\nTotal Amount: UGX ${totalAmount.toLocaleString()}`);
                resetCollectionForm();
                showFeeManagement();
            } else {
                const error = await response.json();
                alert('❌ Error recording payment: ' + (error.error || 'Unknown error'));
            }
        } catch (error) {
            console.error('Payment error:', error);
            alert('Network error: ' + error.message);
        } finally {
            submitBtn.innerText = originalText;
            submitBtn.disabled = false;
        }
    }
});

// ==================== HELPER RENDER FUNCTIONS ====================
// ==================== COMPLETE RENDER FEE STRUCTURES BY LEVEL ====================
// Version: 5.0 - With Status Groups and Payment Options

function renderFeeStructuresByLevel(structures, level, icon, levelName) {
    // Filter structures by level
    const levelStructures = structures.filter(s => s.level === level);
    
    if (!levelStructures || levelStructures.length === 0) {
        return `
            <div class="border rounded-xl p-6 text-center bg-gray-50">
                <div class="text-4xl mb-2">${icon}</div>
                <h3 class="font-semibold text-gray-700">${levelName}</h3>
                <p class="text-sm text-gray-500 mt-1">No fee structures added yet</p>
                <button onclick="showAddFeeStructureModal()" class="mt-3 text-blue-600 text-sm hover:text-blue-800">
                    <i class="fas fa-plus"></i> Add Fee Structure
                </button>
            </div>
        `;
    }
    
    return `
        <div class="border rounded-xl overflow-hidden shadow-sm bg-white">
            <div class="bg-gradient-to-r from-blue-600 to-purple-600 text-white p-3 text-center font-semibold">
                ${icon} ${levelName}
            </div>
            <div class="p-3  max-h-[600px] overflow-y-auto space-y-4">
                ${levelStructures.map(structure => renderFeeStructureCard(structure)).join('')}
            </div>
        </div>
    `;
}

// ==================== RENDER INDIVIDUAL FEE STRUCTURE CARD ====================

function renderFeeStructureCard(structure) {
    // Calculate totals
    const tuition = structure.tuition || 0;
    
    // Extract activities by period type
    const oneTimeActivities = (structure.activityComponents || []).filter(c => c.periodType === 'one_time');
    const termlyActivities = (structure.activityComponents || []).filter(c => c.periodType === 'termly');
    const yearlyActivities = (structure.activityComponents || []).filter(c => c.periodType === 'yearly');
    
    const oneTimeTotal = oneTimeActivities.reduce((sum, c) => sum + (c.totalAmount || 0), 0);
    const termlyTotal = termlyActivities.reduce((sum, c) => sum + (c.totalAmount || 0), 0);
    const yearlyTotal = yearlyActivities.reduce((sum, c) => sum + (c.totalAmount || 0), 0);
    const totalPerTerm = tuition + termlyTotal;
    
    // Group items by status group for summary
    const statusGroupMap = {};
    
    for (const component of structure.activityComponents || []) {
        const statusName = component.statusGroupName || 'Ungrouped';
        if (!statusGroupMap[statusName]) {
            statusGroupMap[statusName] = {
                name: statusName,
                periodTypes: new Set(),
                totalAmount: 0,
                components: []
            };
        }
        statusGroupMap[statusName].periodTypes.add(component.periodType);
        statusGroupMap[statusName].totalAmount += component.totalAmount || 0;
        statusGroupMap[statusName].components.push(component);
    }
    
    // Helper function to render payment badge
    function getPaymentBadge(paymentOption) {
        if (paymentOption === 'cash_only') {
            return '<span class="bg-blue-100 text-blue-800 text-xs px-2 py-0.5 rounded-full">💵 Cash Only</span>';
        } else if (paymentOption === 'item_only') {
            return '<span class="bg-green-100 text-green-800 text-xs px-2 py-0.5 rounded-full">📦 Item Only</span>';
        } else {
            return '<span class="bg-purple-100 text-purple-800 text-xs px-2 py-0.5 rounded-full">🔄 Cash/Item</span>';
        }
    }
    
    // Helper function to render item details
    function renderItemDetails(item) {
        let details = '';
        if (item.paymentOption === 'cash_only') {
            details = `UGX ${(item.cashAmount || item.totalAmount || 0).toLocaleString()}`;
        } else if (item.paymentOption === 'item_only') {
            details = `${item.quantity} item(s)`;
        } else {
            const parts = [];
            if (item.cashAmount > 0) parts.push(`UGX ${item.cashAmount.toLocaleString()}`);
            if (item.quantity > 0) parts.push(`${item.quantity} item(s)`);
            details = parts.join(' + ');
        }
        return details;
    }
    
    return `
        <div class="border rounded-lg p-4 mb-4 last:mb-0 bg-white shadow-sm hover:shadow-md transition-all">
            <!-- Header -->
            <div class="flex justify-between items-start mb-3 pb-2 border-b">
                <div>
                    <h4 class="font-bold text-lg text-gray-800">${escapeHtml(structure.name)}</h4>
                    <p class="text-xs text-gray-500 mt-0.5">
                        ${structure.level === 'Nursery' ? '🎨 Nursery' : structure.level === 'LowerPrimary' ? '📚 Lower Primary' : '🎓 Upper Primary'}
                    </p>
                </div>
                <div class="flex gap-2">
                    <button onclick="editFeeStructureItem('${structure.id}')" class="text-blue-600 hover:text-blue-800 p-1.5 rounded-lg hover:bg-blue-50 transition" title="Edit">
                        <i class="fas fa-edit"></i>
                    </button>
                    <button onclick="deleteFeeStructureItem('${structure.id}')" class="text-red-600 hover:text-red-800 p-1.5 rounded-lg hover:bg-red-50 transition" title="Delete">
                        <i class="fas fa-trash"></i>
                    </button>
                </div>
            </div>
            
            <!-- Tuition Card -->
            <div class="bg-gradient-to-r from-blue-50 to-blue-100 rounded-lg p-3 mb-3 border border-blue-200">
                <div class="flex justify-between items-center">
                    <div class="flex items-center gap-2">
                        <div class="w-8 h-8 bg-blue-500 rounded-full flex items-center justify-center">
                            <i class="fas fa-money-bill-wave text-white text-sm"></i>
                        </div>
                        <span class="font-semibold text-blue-800">Tuition Fee</span>
                    </div>
                    <div class="text-right">
                        <p class="text-xl font-bold text-blue-700">UGX ${tuition.toLocaleString()}</p>
                        <p class="text-xs text-gray-500">per term</p>
                    </div>
                </div>
                <p class="text-xs text-gray-500 mt-2 ml-10">💰 Bursaries can be applied to this amount only</p>
            </div>
            
            <!-- Status Groups Summary Section -->
            ${Object.keys(statusGroupMap).length > 0 ? `
                <div class="mb-3">
                    <div class="flex items-center gap-2 mb-2">
                        <i class="fas fa-tags text-purple-500 text-sm"></i>
                        <span class="text-xs font-semibold text-gray-600 uppercase tracking-wide">Status Groups Summary</span>
                    </div>
                    <div class="grid grid-cols-1 md:grid-cols-2 gap-2">
                        ${Object.values(statusGroupMap).map(sg => {
                            const periodBadges = Array.from(sg.periodTypes).map(p => {
                                if (p === 'one_time') return '<span class="bg-purple-100 text-purple-700 text-xs px-1.5 py-0.5 rounded">⭐ One-Time</span>';
                                if (p === 'termly') return '<span class="bg-green-100 text-green-700 text-xs px-1.5 py-0.5 rounded">📅 Termly</span>';
                                return '<span class="bg-orange-100 text-orange-700 text-xs px-1.5 py-0.5 rounded">📆 Yearly</span>';
                            }).join(' ');
                            return `
                                <div class="bg-gray-50 rounded-lg p-2 border border-gray-200">
                                    <div class="flex justify-between items-center">
                                        <div>
                                            <p class="font-medium text-sm">🏷️ ${escapeHtml(sg.name)}</p>
                                            <div class="flex gap-1 mt-1">${periodBadges}</div>
                                        </div>
                                        <p class="text-lg font-bold text-green-600">UGX ${sg.totalAmount.toLocaleString()}</p>
                                    </div>
                                </div>
                            `;
                        }).join('')}
                    </div>
                </div>
            ` : ''}
            
            <!-- Activity Components by Period Type -->
            <div class="space-y-3 mt-3">
                ${renderActivityGroup(oneTimeActivities, 'One-Time Activities', '⭐', 'purple', 'Paid once per year (first term only)')}
                ${renderActivityGroup(termlyActivities, 'Termly Activities', '📅', 'green', 'Paid every term')}
                ${renderActivityGroup(yearlyActivities, 'Yearly Activities', '📆', 'orange', 'Paid once per year (first term only)')}
            </div>
            
            <!-- Total Summary -->
            <div class="mt-4 pt-3 border-t-2 border-gray-200">
                <div class="flex justify-between items-center">
                    <div>
                        <span class="font-bold text-gray-700">Total Per Term:</span>
                        <p class="text-xs text-gray-500">Tuition + Termly fees</p>
                    </div>
                    <span class="text-2xl font-bold text-purple-700">UGX ${totalPerTerm.toLocaleString()}</span>
                </div>
                ${oneTimeTotal > 0 ? `
                    <div class="flex justify-between items-center mt-1 text-sm">
                        <span class="text-gray-500">+ One-Time (once):</span>
                        <span class="font-semibold text-purple-600">UGX ${oneTimeTotal.toLocaleString()}</span>
                    </div>
                ` : ''}
                ${yearlyTotal > 0 ? `
                    <div class="flex justify-between items-center mt-1 text-sm">
                        <span class="text-gray-500">+ Yearly (once):</span>
                        <span class="font-semibold text-orange-600">UGX ${yearlyTotal.toLocaleString()}</span>
                    </div>
                ` : ''}
            </div>
        </div>
    `;
    
    // Helper function to render activity group
    function renderActivityGroup(components, title, icon, color, note) {
        if (!components || components.length === 0) return '';
        
        const colorMap = {
            purple: { bg: 'bg-purple-50', border: 'border-purple-200', text: 'text-purple-700', iconBg: 'bg-purple-500' },
            green: { bg: 'bg-green-50', border: 'border-green-200', text: 'text-green-700', iconBg: 'bg-green-500' },
            orange: { bg: 'bg-orange-50', border: 'border-orange-200', text: 'text-orange-700', iconBg: 'bg-orange-500' }
        };
        const colors = colorMap[color];
        
        const total = components.reduce((sum, c) => sum + (c.totalAmount || 0), 0);
        
        return `
            <div class="${colors.bg} rounded-lg p-3 border ${colors.border}">
                <div class="flex justify-between items-center mb-2">
                    <div class="flex items-center gap-2">
                        <div class="w-6 h-6 ${colors.iconBg} rounded-full flex items-center justify-center">
                            <span class="text-white text-xs">${icon}</span>
                        </div>
                        <span class="font-semibold ${colors.text} text-sm">${title}</span>
                    </div>
                    <span class="font-bold ${colors.text}">UGX ${total.toLocaleString()}</span>
                </div>
                <p class="text-xs text-gray-500 mb-2 italic">${note}</p>
                
                <div class="space-y-2 mt-2">
                    ${components.map(comp => `
                        <div class="bg-white rounded-lg p-2 shadow-sm">
                            <div class="flex justify-between items-start">
                                <div class="flex-1">
                                    <p class="font-medium text-sm">📌 ${escapeHtml(comp.name)}</p>
                                    ${comp.statusGroupName ? `<p class="text-xs text-purple-600 mt-0.5">🏷️ Status: ${escapeHtml(comp.statusGroupName)}</p>` : ''}
                                </div>
                                <span class="font-semibold text-green-600 text-sm">UGX ${(comp.totalAmount || 0).toLocaleString()}</span>
                            </div>
                            <div class="mt-2 pl-3 space-y-1">
                                ${(comp.items || []).map(item => `
                                    <div class="flex justify-between items-center text-xs border-b border-gray-100 pb-1 last:border-0">
                                        <div class="flex items-center gap-2">
                                            <span class="text-gray-600">📦 ${escapeHtml(item.name)}</span>
                                            ${getPaymentBadge(item.paymentOption)}
                                        </div>
                                        <div class="text-right">
                                            <span class="font-medium text-green-600">${renderItemDetails(item)}</span>
                                            ${item.quantity > 0 && item.paymentOption !== 'cash_only' ? `<span class="text-xs text-gray-400 ml-1">(Qty: ${item.quantity})</span>` : ''}
                                        </div>
                                    </div>
                                `).join('')}
                            </div>
                            <div class="mt-2 pt-1 border-t ${colors.border} flex justify-between text-xs">
                                <span class="text-gray-500">Component Total:</span>
                                <span class="font-semibold ${colors.text}">UGX ${(comp.totalAmount || 0).toLocaleString()}</span>
                            </div>
                        </div>
                    `).join('')}
                </div>
            </div>
        `;
    }
    
    function getPaymentBadge(paymentOption) {
        if (paymentOption === 'cash_only') {
            return '<span class="bg-blue-100 text-blue-800 text-xs px-1.5 py-0.5 rounded">💵 Cash</span>';
        } else if (paymentOption === 'item_only') {
            return '<span class="bg-green-100 text-green-800 text-xs px-1.5 py-0.5 rounded">📦 Item</span>';
        } else {
            return '<span class="bg-purple-100 text-purple-800 text-xs px-1.5 py-0.5 rounded">🔄 Cash/Item</span>';
        }
    }
    
    function renderItemDetails(item) {
        if (item.paymentOption === 'cash_only') {
            return `UGX ${(item.cashAmount || item.totalAmount || 0).toLocaleString()}`;
        } else if (item.paymentOption === 'item_only') {
            return `${item.quantity} item(s)`;
        } else {
            const parts = [];
            if (item.cashAmount > 0) parts.push(`UGX ${item.cashAmount.toLocaleString()}`);
            if (item.quantity > 0) parts.push(`${item.quantity} item(s)`);
            return parts.join(' + ');
        }
    }
}

// ==================== RENDER ALL FEE STRUCTURES BY LEVEL ====================

