// ==================== HELPER FUNCTION ====================

function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function renderBursariesListFixed(bursaries) {
    if (!bursaries || bursaries.length === 0) {
        return '<div class="col-span-3 text-center py-8 text-gray-500">No bursaries added</div>';
    }
    return bursaries.map(b => `
        <div class="border rounded-lg p-3">
            <div class="font-bold">${b.name}</div>
            <p class="text-sm text-gray-600">${b.description || ''}</p>
            <div class="mt-2 text-sm">
                <span class="px-2 py-1 rounded-full bg-blue-100">
                    ${b.type === 'percentage' ? `${b.value}% OFF` : `UGX ${b.value.toLocaleString()} OFF`}
                </span>
                <span class="ml-2 text-xs text-gray-500">${b.category || 'General'}</span>
            </div>
            <div class="flex gap-2 mt-3">
                <button onclick="editBursary('${b.id}')" class="text-blue-600 text-sm">Edit</button>
                <button onclick="deleteBursary('${b.id}')" class="text-red-600 text-sm">Delete</button>
            </div>
        </div>
    `).join('');
}

// ==================== TAB INITIALIZATION ====================
function initializeFeeTabsFixed() {
    const tabs = document.querySelectorAll('.fee-tab');
    tabs.forEach(tab => {
        tab.addEventListener('click', () => {
            const tabId = tab.dataset.tab;
            tabs.forEach(t => {
                t.classList.remove('active', 'border-b-2', 'border-blue-600', 'text-blue-600');
                t.classList.add('text-gray-600');
            });
            tab.classList.add('active', 'border-b-2', 'border-blue-600', 'text-blue-600');
            tab.classList.remove('text-gray-600');
            
            document.querySelectorAll('.fee-tab-content').forEach(c => c.classList.add('hidden'));
            const activeTab = document.getElementById(tabId);
            if (activeTab) activeTab.classList.remove('hidden');
        });
    });
}

// ==================== FEE COLLECTION FORM SETUP WITH AUTO-LOAD ====================
function setupFeeCollectionForm() {
    const form = document.getElementById('feeCollectionForm');
    if (!form) return;
    
    // Get DOM elements
    const studentSelect = document.getElementById('feeStudent');
    const feeSelect = document.getElementById('feeStructureSelect');
    const bursarySelect = document.getElementById('bursarySelect');
    const amountInput = document.getElementById('amountPaid');
    const summaryDiv = document.getElementById('feeSummary');
    const alreadyPaidSpan = document.getElementById('alreadyPaid');
    const amountDueSpan = document.getElementById('amountDue');
    const originalFeeSpan = document.getElementById('originalFee');
    const discountSpan = document.getElementById('discountAmount');
    const outstandingSpan = document.getElementById('outstandingBalance');
    const maxHint = document.getElementById('maxAmountHint');
    
    // Store fee structures and bursaries globally for this function
    let feeStructuresList = [];
    let feeBursariesList = [];
    let studentAssignmentsMap = {};
    
    // Load all required data
    async function loadFeeData() {
        try {
            const [feeStructuresRes, feeBursariesRes, assignmentsRes] = await Promise.all([
                fetch('/api/fee/structures'),
                fetch('/api/fee/bursaries'),
                fetch('/api/student-fee-assignments')
            ]);
            
            feeStructuresList = await feeStructuresRes.json();
            feeBursariesList = await feeBursariesRes.json();
            const assignments = await assignmentsRes.json();
            
            // Create assignments map
            assignments.forEach(a => {
                studentAssignmentsMap[a.studentId] = a;
            });
        } catch (error) {
            console.error('Error loading fee data:', error);
        }
    }
    
    // Load data on page load
    loadFeeData();
    
    // Helper function to load student's assigned fee structure and bursary
    async function loadStudentAssignment(studentId) {
        if (!studentId) return;
        
        // Check if we have assignment in memory
        const assignment = studentAssignmentsMap[studentId];
        
        if (assignment && assignment.feeStructureId) {
            // Set fee structure if select exists
            if (feeSelect) {
                // Wait for the feeSelect options to be populated
                setTimeout(() => {
                    // Check if the option exists
                    let optionExists = false;
                    for (let i = 0; i < feeSelect.options.length; i++) {
                        if (feeSelect.options[i].value === assignment.feeStructureId) {
                            optionExists = true;
                            break;
                        }
                    }
                    
                    if (optionExists) {
                        feeSelect.value = assignment.feeStructureId;
                        // Trigger change event to update calculations
                        const changeEvent = new Event('change');
                        feeSelect.dispatchEvent(changeEvent);
                    } else {
                        console.log('Fee structure option not available yet');
                    }
                }, 100);
            }
        }
        
        // Set bursary if assigned
        if (bursarySelect && assignment && assignment.bursaryId) {
            setTimeout(() => {
                let optionExists = false;
                for (let i = 0; i < bursarySelect.options.length; i++) {
                    if (bursarySelect.options[i].value === assignment.bursaryId) {
                        optionExists = true;
                        break;
                    }
                }
                
                if (optionExists) {
                    bursarySelect.value = assignment.bursaryId;
                    // Trigger change event
                    const changeEvent = new Event('change');
                    bursarySelect.dispatchEvent(changeEvent);
                }
            }, 100);
        }
    }
    
    // Helper function to load existing payments for the term
    async function loadTermPayments(studentId, term) {
        if (!studentId || !term) return 0;
        
        try {
            const { currentYear } = currentAcademicSettings;
            const response = await fetch(`/api/fee/payments?year=${currentYear}&term=${term}`);
            if (response.ok) {
                const payments = await response.json();
                const termPayments = payments.filter(p => p.studentId === studentId && !p.additionalFeeId);
                const totalPaid = termPayments.reduce((sum, p) => sum + (p.amount || 0), 0);
                if (alreadyPaidSpan) alreadyPaidSpan.innerHTML = `UGX ${totalPaid.toLocaleString()}`;
                return totalPaid;
            }
        } catch (error) {
            console.error('Error loading payments:', error);
        }
        return 0;
    }
    
    // Helper function to calculate fee with bursary
    function calculateFeeWithBursary() {
        if (!feeSelect || !feeSelect.value) {
            if (summaryDiv) summaryDiv.classList.add('hidden');
            return;
        }
        
        const selectedOption = feeSelect.options[feeSelect.selectedIndex];
        const originalFee = parseInt(selectedOption.dataset.total) || 0;
        const structureData = selectedOption.dataset.structure ? JSON.parse(selectedOption.dataset.structure) : null;
        
        let discountAmount = 0;
        let discountPercentage = 0;
        let appliedBursaryName = '';
        
        if (bursarySelect && bursarySelect.value) {
            const option = bursarySelect.options[bursarySelect.selectedIndex];
            const type = option.dataset.type;
            const value = parseInt(option.dataset.value) || 0;
            appliedBursaryName = option.dataset.name || option.text;
            
            if (type === 'percentage') {
                discountAmount = (originalFee * value) / 100;
                discountPercentage = value;
            } else {
                discountAmount = value;
            }
        }
        
        const amountDue = originalFee - discountAmount;
        const alreadyPaid = parseInt(alreadyPaidSpan?.innerHTML?.replace(/[^0-9]/g, '') || '0');
        const outstanding = amountDue - alreadyPaid;
        
        if (originalFeeSpan) originalFeeSpan.innerHTML = `UGX ${originalFee.toLocaleString()}`;
        if (discountSpan) discountSpan.innerHTML = discountAmount > 0 ? `- UGX ${discountAmount.toLocaleString()} (${discountPercentage}% off)` : 'None';
        if (amountDueSpan) amountDueSpan.innerHTML = `UGX ${amountDue.toLocaleString()}`;
        if (outstandingSpan) outstandingSpan.innerHTML = `UGX ${outstanding.toLocaleString()}`;
        
        if (amountInput) {
            amountInput.max = outstanding;
            amountInput.placeholder = `Enter amount (max UGX ${outstanding.toLocaleString()})`;
        }
        if (maxHint) maxHint.innerHTML = `Maximum payable: UGX ${outstanding.toLocaleString()}`;
        
        if (outstanding <= 0 && amountInput) {
            amountInput.disabled = true;
            if (maxHint) maxHint.innerHTML = '✓ No outstanding balance for this term';
        } else if (amountInput) {
            amountInput.disabled = false;
        }
        
        if (summaryDiv) summaryDiv.classList.remove('hidden');
    }
    
    // Student selection change - auto-load fee structure and bursary
    if (studentSelect) {
        studentSelect.addEventListener('change', async function() {
            const studentId = this.value;
            if (!studentId) {
                if (summaryDiv) summaryDiv.classList.add('hidden');
                return;
            }
            
            // Show loading indicator
            if (feeSelect) feeSelect.innerHTML = '<option value="">Loading fee structures...</option>';
            
            // Reload fee data to ensure we have latest assignments
            await loadFeeData();
            
            // Populate fee structures based on student's class level
            const selectedOption = this.options[this.selectedIndex];
            const studentClass = selectedOption.dataset.class;
            
            // Get class level
            const classesRes = await fetch('/api/school/classes');
            const classes = await classesRes.json();
            const classObj = classes.find(c => c.name === studentClass);
            const studentLevel = classObj ? classObj.level : null;
            
            // Filter fee structures by level
            let availableStructures = feeStructuresList;
            if (studentLevel) {
                availableStructures = feeStructuresList.filter(fs => fs.level === studentLevel && fs.isActive);
            }
            
            // Populate fee structure dropdown
            if (feeSelect) {
                feeSelect.innerHTML = '<option value="">Select Fee Structure</option>';
                availableStructures.forEach(fs => {
                    const option = document.createElement('option');
                    option.value = fs.id;
                    option.textContent = `${fs.name} - UGX ${fs.total.toLocaleString()}/term`;
                    option.dataset.total = fs.total;
                    option.dataset.structure = JSON.stringify(fs);
                    feeSelect.appendChild(option);
                });
            }
            
            // Load student's assigned fee structure and bursary
            await loadStudentAssignment(studentId);
            
            // Load existing payments for the selected term
            const { currentTerm } = currentAcademicSettings;
            await loadTermPayments(studentId, currentTerm);
            
            // Recalculate fee with bursary
            calculateFeeWithBursary();
        });
    }
    
    // Fee structure change - recalculate
    if (feeSelect) {
        feeSelect.addEventListener('change', function() {
            calculateFeeWithBursary();
        });
    }
    
    // Bursary change - recalculate
    if (bursarySelect) {
        bursarySelect.addEventListener('change', function() {
            calculateFeeWithBursary();
        });
    }
    
    // Form submission
    form.addEventListener('submit', async (e) => {
        e.preventDefault();
        
        const studentId = studentSelect ? studentSelect.value : null;
        const { currentYear, currentTerm } = currentAcademicSettings;
        const feeStructureId = feeSelect ? feeSelect.value : null;
        const amount = amountInput ? parseInt(amountInput.value) : 0;
        const method = document.getElementById('paymentMethod')?.value || 'cash';
        const reference = document.getElementById('paymentReference')?.value || '';
        const notes = document.getElementById('paymentNotes')?.value || '';
        
        if (!studentId || !feeStructureId || !amount || amount <= 0) {
            alert('Please select a student and fee structure, and enter a valid amount');
            return;
        }
        
        // Get student name
        const studentName = studentSelect.options[studentSelect.selectedIndex]?.text || '';
        
        const submitBtn = form.querySelector('button[type="submit"]');
        const originalText = submitBtn.innerText;
        submitBtn.innerText = 'Processing...';
        submitBtn.disabled = true;
        
        try {
            const response = await fetch('/api/fee/payments', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    studentId,
                    studentName,
                    term: currentTerm,
                    amount,
                    method,
                    reference,
                    notes,
                    feeStructureId,
                    academicYear: currentYear.toString()
                })
            });
            
            if (response.ok) {
                const result = await response.json();
                alert(`✅ Payment recorded successfully!\nReceipt Number: ${result.receiptNumber}`);
                
                // Reset form
                if (amountInput) amountInput.value = '';
                if (document.getElementById('paymentReference')) document.getElementById('paymentReference').value = '';
                if (document.getElementById('paymentNotes')) document.getElementById('paymentNotes').value = '';
                if (summaryDiv) summaryDiv.classList.add('hidden');
                
                // Refresh the page
                showFeeManagement();
            } else {
                const error = await response.text();
                alert('❌ Error recording payment: ' + error);
            }
        } catch (error) {
            console.error('Payment error:', error);
            alert('Network error: ' + error.message);
        } finally {
            submitBtn.innerText = originalText;
            submitBtn.disabled = false;
        }
    });
}

