// Function to add activity component field
function addActivityComponentField() {
    const id = 'act_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);
    const html = `
        <div id="${id}" class="flex gap-2 items-center bg-white p-3 rounded-lg border shadow-sm hover:shadow-md transition">
            <input type="text" placeholder="Component name (e.g., Brooms, TP, Soap)" class="flex-1 border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 actName">
            <input type="number" placeholder="Amount (UGX)" class="w-36 border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 actAmount" value="0" oninput="updateModalTotals()">
            <button type="button" onclick="removeComponentField('${id}')" class="text-red-600 hover:text-red-800 px-2 py-2 rounded-lg hover:bg-red-50 transition">
                <i class="fas fa-trash"></i>
            </button>
        </div>
    `;
    
    const container = document.getElementById('modalActivityList');
    const emptyMsg = document.getElementById('emptyActivityMsg');
    if (emptyMsg && emptyMsg.parentNode === container) {
        emptyMsg.remove();
    }
    container.insertAdjacentHTML('beforeend', html);
    updateModalTotals();
    updateEmptyMessages();
}

