// ==================== LOAD EXISTING FEE STRUCTURE ====================
function loadExistingFeeStructure() {
    console.log('loadExistingFeeStructure called');
    
    const select = document.getElementById('loadFeeStructureSelect');
    const selectedId = select.value;
    const statusMsg = document.getElementById('loadStatusMsg');
    
    if (!selectedId) {
        alert('Please select a fee structure to load');
        return;
    }
    
    const feeStructure = window.existingFeeStructures.find(f => f.id === selectedId);
    if (!feeStructure) {
        alert('Fee structure not found');
        return;
    }
    
    console.log('Loading fee structure:', feeStructure.name);
    console.log('Activity components:', feeStructure.activityComponents);
    
    // Confirm loading
    if (!confirm(`Are you sure you want to load "${feeStructure.name}"?\n\nThis will replace all current activity groups.\n\nYou can still edit them after loading.`)) {
        return;
    }
    
    // Check if there are existing groups and confirm
    if (window.activityGroupsData && window.activityGroupsData.length > 0) {
        if (!confirm('You already have activity groups. Loading will replace them. Continue?')) {
            return;
        }
    }
    
    // Clear existing groups
    window.activityGroupsData = [];
    
    // Load tuition amount
    const tuitionInput = document.getElementById('modalFsTuition');
    if (tuitionInput) {
        tuitionInput.value = feeStructure.tuition || 0;
    }
    
    // Load activity components
    if (feeStructure.activityComponents && feeStructure.activityComponents.length > 0) {
        for (const component of feeStructure.activityComponents) {
            console.log('Processing component:', component.name, 'Period:', component.periodType);
            
            // Skip if no items
            if (!component.items || component.items.length === 0) {
                console.log('Component has no items, skipping');
                continue;
            }
            
            // Create a new group
            const newGroup = {
                id: `group_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
                name: component.name || 'Unnamed Group',
                periodType: component.periodType || 'termly',
                statusGroupId: component.statusGroupId || null,
                statusGroupName: component.statusGroupName || null,
                items: [],
                totalAmount: 0,
                createdAt: new Date().toISOString()
            };
            
            // Copy items
            for (const item of component.items) {
                const paymentOption = item.paymentOption || 'either';
                let cashAmount = item.cashAmount || item.totalAmount || 0;
                let quantity = item.quantity || 1;
                
                // If payment option is item_only, cashAmount should be 0
                if (paymentOption === 'item_only') {
                    cashAmount = 0;
                }
                // If payment option is cash_only, quantity should be 1
                if (paymentOption === 'cash_only') {
                    quantity = 1;
                }
                
                const newItem = {
                    id: `item_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
                    name: item.name || 'Unnamed Item',
                    quantity: quantity,
                    cashAmount: cashAmount,
                    totalAmount: cashAmount || (quantity * (item.unitPrice || 0)),
                    paymentOption: paymentOption,
                    isTangible: paymentOption !== 'cash_only'
                };
                
                newGroup.items.push(newItem);
            }
            
            // Calculate group total
            newGroup.totalAmount = newGroup.items.reduce((sum, i) => sum + (i.cashAmount || i.totalAmount || 0), 0);
            
            window.activityGroupsData.push(newGroup);
            console.log('Added group:', newGroup.name, 'with', newGroup.items.length, 'items, total:', newGroup.totalAmount);
        }
        
        statusMsg.innerHTML = `✅ Loaded ${feeStructure.activityComponents.length} groups from "${feeStructure.name}"`;
        statusMsg.className = 'text-green-600 font-semibold';
    } else {
        statusMsg.innerHTML = '⚠️ No activity groups found in the selected structure';
        statusMsg.className = 'text-yellow-600 font-semibold';
    }
    
    // Re-render the activity groups
    renderActivityGroupsList();
    updateSummaryTotals();
    updateActivityCountBadge();
    
    // Show success message
    setTimeout(() => {
        statusMsg.innerHTML = '';
    }, 5000);
}

// ==================== CLEAR ALL ACTIVITY GROUPS ====================
function clearAllActivityGroups() {
    if (!window.activityGroupsData || window.activityGroupsData.length === 0) {
        alert('No activity groups to clear');
        return;
    }
    
    if (!confirm('⚠️ Are you sure you want to remove ALL activity groups?\n\nThis cannot be undone.')) {
        return;
    }
    
    window.activityGroupsData = [];
    renderActivityGroupsList();
    updateSummaryTotals();
    updateActivityCountBadge();
    
    showToast('All activity groups cleared', 'info');
}

// ==================== UPDATE ACTIVITY COUNT BADGE ====================
function updateActivityCountBadge() {
    const badge = document.getElementById('activityCountBadge');
    if (!badge) return;
    
    const count = window.activityGroupsData ? window.activityGroupsData.length : 0;
    const totalItems = window.activityGroupsData ? window.activityGroupsData.reduce((sum, g) => sum + (g.items ? g.items.length : 0), 0) : 0;
    
    if (count > 0) {
        badge.innerHTML = `(${count} groups, ${totalItems} items)`;
        badge.className = 'text-sm font-normal text-gray-500 ml-2';
    } else {
        badge.innerHTML = '';
    }
}

// ==================== SHOW TOAST NOTIFICATION ====================
function showToast(message, type = 'success') {
    const toast = document.createElement('div');
    const bgColor = type === 'success' ? 'bg-green-500' : type === 'error' ? 'bg-red-500' : 'bg-blue-500';
    toast.className = `fixed bottom-4 right-4 ${bgColor} text-white px-4 py-2 rounded-lg shadow-lg z-50`;
    toast.innerHTML = message;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 3000);
}

// ==================== RENDER ACTIVITY GROUPS LIST (UPDATED) ====================
function renderActivityGroupsList() {
    const container = document.getElementById('activityGroupsContainer');
    if (!container) return;
    
    console.log('Rendering Activity Groups. Count:', window.activityGroupsData ? window.activityGroupsData.length : 0);
    
    if (!window.activityGroupsData || window.activityGroupsData.length === 0) {
        container.innerHTML = `
            <div class="text-center text-gray-400 py-8" id="emptyGroupsMsg">
                <i class="fas fa-inbox text-3xl mb-2"></i>
                <p>No activity groups added yet. Click "Add Activity Group" to create one.</p>
                <p class="text-xs mt-2 text-blue-400">Or use "Load Existing Fee Structure" to copy from another structure.</p>
            </div>
        `;
        updateActivityCountBadge();
        return;
    }
    
    const oneTimeGroups = window.activityGroupsData.filter(g => g.periodType === 'one_time');
    const termlyGroups = window.activityGroupsData.filter(g => g.periodType === 'termly');
    const yearlyGroups = window.activityGroupsData.filter(g => g.periodType === 'yearly');
    
    function renderGroupSection(groups, title, icon, bgColor, borderColor, textColor) {
        if (groups.length === 0) return '';
        
        return `
            <div class="mb-4">
                <h4 class="font-bold text-lg mb-2">${icon} ${title} <span class="text-sm font-normal text-gray-500">(${groups.length} groups)</span></h4>
                <div class="space-y-3">
                    ${groups.map(group => `
                        <div class="border-2 ${borderColor} rounded-lg p-4 ${bgColor}">
                            <div class="flex justify-between items-start mb-3">
                                <div>
                                    <h5 class="font-bold text-md">${escapeHtml(group.name)}</h5>
                                    ${group.statusGroupName ? `<p class="text-xs text-gray-500 mt-1">🏷️ Status: ${escapeHtml(group.statusGroupName)}</p>` : ''}
                                    <p class="text-xs text-gray-400 mt-1">${group.items.length} item(s) | Total: UGX ${(group.totalAmount || 0).toLocaleString()}</p>
                                </div>
                                <div class="flex gap-2">
                                    <button type="button" onclick="editActivityGroup('${group.id}')" class="bg-blue-500 text-white px-3 py-1 rounded text-sm hover:bg-blue-600">
                                        <i class="fas fa-edit"></i> Edit
                                    </button>
                                    <button type="button" onclick="deleteActivityGroup('${group.id}')" class="bg-red-500 text-white px-3 py-1 rounded text-sm hover:bg-red-600">
                                        <i class="fas fa-trash"></i> Delete
                                    </button>
                                </div>
                            </div>
                            <div class="space-y-2">
                                ${group.items.map(item => {
                                    let details = '';
                                    if (item.paymentOption === 'cash_only') {
                                        details = `💵 UGX ${(item.cashAmount || item.totalAmount || 0).toLocaleString()}`;
                                    } else if (item.paymentOption === 'item_only') {
                                        details = `📦 ${item.quantity} item(s)`;
                                    } else {
                                        const parts = [];
                                        if (item.cashAmount > 0) parts.push(`💵 UGX ${item.cashAmount.toLocaleString()}`);
                                        if (item.quantity > 0) parts.push(`📦 ${item.quantity} item(s)`);
                                        details = parts.join(' + ');
                                    }
                                    return `
                                        <div class="bg-white rounded p-2 flex justify-between items-center border border-gray-100">
                                            <span class="font-medium">📦 ${escapeHtml(item.name)}</span>
                                            <span class="font-semibold text-green-600">${details}</span>
                                        </div>
                                    `;
                                }).join('')}
                            </div>
                            <div class="mt-3 pt-2 border-t ${borderColor} flex justify-between font-semibold">
                                <span>Group Total:</span>
                                <span class="${textColor}">UGX ${(group.totalAmount || 0).toLocaleString()}</span>
                            </div>
                        </div>
                    `).join('')}
                </div>
            </div>
        `;
    }
    
    container.innerHTML = `
        ${renderGroupSection(oneTimeGroups, 'One-Time Activities', '⭐', 'bg-purple-50', 'border-purple-300', 'text-purple-600')}
        ${renderGroupSection(termlyGroups, 'Termly Activities', '📅', 'bg-green-50', 'border-green-300', 'text-green-600')}
        ${renderGroupSection(yearlyGroups, 'Yearly Activities', '📆', 'bg-orange-50', 'border-orange-300', 'text-orange-600')}
    `;
    
    updateActivityCountBadge();
}

// ==================== UPDATE SUMMARY TOTALS (UPDATED) ====================
function updateSummaryTotals() {
    const tuition = parseInt(document.getElementById('modalFsTuition')?.value) || 0;
    
    // Group items by status group
    const statusGroupTotals = {};
    const statusGroupDetails = {};
    
    if (window.activityGroupsData && window.activityGroupsData.length > 0) {
        for (const group of window.activityGroupsData) {
            const statusGroupId = group.statusGroupId || 'ungrouped';
            const statusGroupName = group.statusGroupName || 'Ungrouped Items';
            
            if (!statusGroupTotals[statusGroupId]) {
                statusGroupTotals[statusGroupId] = 0;
                statusGroupDetails[statusGroupId] = {
                    name: statusGroupName,
                    groups: [],
                    totalCash: 0,
                    totalItems: 0
                };
            }
            
            statusGroupTotals[statusGroupId] += group.totalAmount || 0;
            statusGroupDetails[statusGroupId].groups.push({
                name: group.name,
                periodType: group.periodType,
                totalAmount: group.totalAmount || 0,
                items: group.items || []
            });
            
            // Calculate cash and item totals
            for (const item of (group.items || [])) {
                if (item.paymentOption === 'cash_only' || item.paymentOption === 'either') {
                    statusGroupDetails[statusGroupId].totalCash += item.cashAmount || item.totalAmount || 0;
                }
                if (item.paymentOption === 'item_only' || item.paymentOption === 'either') {
                    statusGroupDetails[statusGroupId].totalItems += item.quantity || 0;
                }
            }
        }
    }
    
    // Render status group summary cards
    const summaryContainer = document.getElementById('statusGroupsSummaryContainer');
    if (summaryContainer) {
        if (Object.keys(statusGroupTotals).length === 0 && tuition === 0) {
            summaryContainer.innerHTML = `
                <div class="text-center text-gray-500 py-4" id="emptyStatusSummaryMsg">
                    <i class="fas fa-tags text-3xl mb-2"></i>
                    <p>No status groups added yet. Add items with status groups to see summary.</p>
                </div>
            `;
        } else {
            const summaryHtml = [];
            
            for (const [groupId, total] of Object.entries(statusGroupTotals)) {
                const details = statusGroupDetails[groupId];
                
                // Build period badges for this status group
                const periodTypes = new Set();
                for (const group of details.groups) {
                    periodTypes.add(group.periodType);
                }
                
                let periodBadges = '';
                if (periodTypes.has('one_time')) periodBadges += '<span class="bg-purple-100 text-purple-800 text-xs px-2 py-0.5 rounded-full">⭐ One-Time</span> ';
                if (periodTypes.has('termly')) periodBadges += '<span class="bg-green-100 text-green-800 text-xs px-2 py-0.5 rounded-full">📅 Termly</span> ';
                if (periodTypes.has('yearly')) periodBadges += '<span class="bg-orange-100 text-orange-800 text-xs px-2 py-0.5 rounded-full">📆 Yearly</span> ';
                
                summaryHtml.push(`
                    <div class="bg-white rounded-lg p-4 border shadow-sm">
                        <div class="flex justify-between items-start mb-3">
                            <div>
                                <h4 class="font-bold text-lg flex items-center gap-2">
                                    <i class="fas fa-tag text-purple-600"></i>
                                    ${escapeHtml(details.name)}
                                </h4>
                                <div class="flex flex-wrap gap-1 mt-1">${periodBadges}</div>
                            </div>
                            <div class="text-right">
                                <p class="text-2xl font-bold text-green-600">UGX ${total.toLocaleString()}</p>
                                ${details.totalItems > 0 ? `<p class="text-xs text-gray-500">+ ${details.totalItems} physical item(s)</p>` : ''}
                            </div>
                        </div>
                        <div class="text-sm text-gray-600 border-t pt-2 mt-2">
                            <div class="flex justify-between">
                                <span>Cash Component:</span>
                                <span class="font-semibold">UGX ${details.totalCash.toLocaleString()}</span>
                            </div>
                            ${details.totalItems > 0 ? `
                                <div class="flex justify-between">
                                    <span>Items Component:</span>
                                    <span class="font-semibold">${details.totalItems} item(s)</span>
                                </div>
                            ` : ''}
                        </div>
                        <div class="mt-2 text-xs text-gray-400">
                            From ${details.groups.length} activity group(s)
                        </div>
                    </div>
                `);
            }
            
            summaryContainer.innerHTML = summaryHtml.join('');
        }
    }
    
    // Update tuition display
    const summaryTuitionAmount = document.getElementById('summaryTuitionAmount');
    if (summaryTuitionAmount) summaryTuitionAmount.innerHTML = `UGX ${tuition.toLocaleString()}`;
    
    // Calculate grand total
    const grandTotal = tuition + Object.values(statusGroupTotals).reduce((sum, val) => sum + val, 0);
    const summaryGrandTotal = document.getElementById('summaryGrandTotal');
    if (summaryGrandTotal) summaryGrandTotal.innerHTML = `UGX ${grandTotal.toLocaleString()}`;
    
    console.log(`Grand Total: ${grandTotal}, Tuition: ${tuition}, Status Groups:`, statusGroupTotals);
}

