// ==================== SHOW ADD ITEM MODAL ====================

function showAddItemModal() {
    const modalHtml = `
        <div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[70]">
            <div class="bg-white rounded-2xl p-6 max-w-md w-full mx-4">
                <div class="flex justify-between items-center mb-4 pb-2 border-b">
                    <h4 class="text-lg font-bold">Add Item to Group</h4>
                    <button onclick="closeAddItemModal()" class="text-gray-500 hover:text-gray-700">&times;</button>
                </div>
                
                <div class="space-y-4">
                    <div>
                        <label class="block text-sm font-medium mb-1 required-field">Item Name *</label>
                        <input type="text" id="itemName" class="w-full border rounded-lg px-3 py-2">
                    </div>
                    
                    <div>
                        <label class="block text-sm font-medium mb-1 required-field">Payment Option *</label>
                        <div class="space-y-2">
                            <label class="flex items-start p-3 border rounded-lg cursor-pointer">
                                <input type="radio" name="paymentOption" value="cash_only" class="mr-3 mt-1">
                                <div><div class="font-medium">💵 Cash Only</div><div class="text-xs text-gray-500">Must be paid in cash</div></div>
                            </label>
                            <label class="flex items-start p-3 border rounded-lg cursor-pointer">
                                <input type="radio" name="paymentOption" value="item_only" class="mr-3 mt-1">
                                <div><div class="font-medium">📦 Item Only</div><div class="text-xs text-gray-500">Must be brought physically</div></div>
                            </label>
                            <label class="flex items-start p-3 border rounded-lg cursor-pointer">
                                <input type="radio" name="paymentOption" value="either" class="mr-3 mt-1" checked>
                                <div><div class="font-medium">🔄 Either (Cash or Item)</div><div class="text-xs text-gray-500">Can be paid cash OR bring items</div></div>
                            </label>
                        </div>
                    </div>
                    
                    <div id="addItemDynamicFields">
                        <div class="grid grid-cols-2 gap-3">
                            <div>
                                <label class="block text-sm font-medium mb-1">Cash Amount (UGX)</label>
                                <input type="number" id="itemCashAmount" class="w-full border rounded-lg px-3 py-2" value="0" min="0">
                            </div>
                            <div>
                                <label class="block text-sm font-medium mb-1">Quantity to Bring</label>
                                <input type="number" id="itemQuantity" class="w-full border rounded-lg px-3 py-2" value="0" min="0">
                            </div>
                        </div>
                        <div class="bg-yellow-50 p-2 rounded text-xs text-yellow-700 mt-2">Enter either cash amount, quantity, or both</div>
                    </div>
                    
                    <div class="flex gap-3 pt-2">
                        <button type="button" id="confirmAddItem" class="flex-1 bg-blue-600 text-white py-2 rounded-lg">Add Item</button>
                        <button type="button" onclick="closeAddItemModal()" class="flex-1 bg-gray-300 text-gray-700 py-2 rounded-lg">Cancel</button>
                    </div>
                </div>
            </div>
        </div>
    `;
    
    document.body.insertAdjacentHTML('beforeend', modalHtml);
    
    // Handle payment option changes
    const radioButtons = document.querySelectorAll('input[name="paymentOption"]');
    radioButtons.forEach(radio => {
        radio.addEventListener('change', (e) => {
            const container = document.getElementById('addItemDynamicFields');
            if (e.target.value === 'cash_only') {
                container.innerHTML = `<input type="number" id="itemCashAmount" class="w-full border rounded-lg px-3 py-2" placeholder="Amount (UGX)" value="0" min="0">`;
            } else if (e.target.value === 'item_only') {
                container.innerHTML = `<input type="number" id="itemQuantity" class="w-full border rounded-lg px-3 py-2" placeholder="Quantity" value="1" min="1">`;
            } else {
                container.innerHTML = `
                    <div class="grid grid-cols-2 gap-3">
                        <div><label class="block text-sm font-medium mb-1">Cash Amount (UGX)</label><input type="number" id="itemCashAmount" class="w-full border rounded-lg px-3 py-2" value="0" min="0"></div>
                        <div><label class="block text-sm font-medium mb-1">Quantity to Bring</label><input type="number" id="itemQuantity" class="w-full border rounded-lg px-3 py-2" value="0" min="0"></div>
                    </div>
                    <div class="bg-yellow-50 p-2 rounded text-xs text-yellow-700 mt-2">Enter either cash amount, quantity, or both</div>
                `;
            }
        });
    });
    
    document.getElementById('confirmAddItem').addEventListener('click', () => {
        const itemName = document.getElementById('itemName').value.trim();
        const paymentOption = document.querySelector('input[name="paymentOption"]:checked')?.value || 'either';
        
        if (!itemName) {
            alert('Please enter an item name');
            return;
        }
        
        let quantity = 0;
        let cashAmount = 0;
        
        if (paymentOption === 'cash_only') {
            cashAmount = parseInt(document.getElementById('itemCashAmount')?.value) || 0;
            if (cashAmount <= 0) {
                alert('Please enter a valid cash amount');
                return;
            }
            quantity = 1;
        } else if (paymentOption === 'item_only') {
            quantity = parseInt(document.getElementById('itemQuantity')?.value) || 0;
            if (quantity <= 0) {
                alert('Please enter a valid quantity');
                return;
            }
            cashAmount = 0;
        } else {
            cashAmount = parseInt(document.getElementById('itemCashAmount')?.value) || 0;
            quantity = parseInt(document.getElementById('itemQuantity')?.value) || 0;
            if (cashAmount <= 0 && quantity <= 0) {
                alert('Please enter either cash amount, quantity, or both');
                return;
            }
        }
        
        const newItem = {
            id: `item_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
            name: itemName,
            quantity: quantity,
            cashAmount: cashAmount,
            totalAmount: cashAmount,
            paymentOption: paymentOption
        };
        
        window.tempGroupItems.push(newItem);
        closeAddItemModal();
        renderCurrentGroupItems();
    });
}



// ==================== RENDER CURRENT GROUP ITEMS ====================

function renderCurrentGroupItems() {
    const container = document.getElementById('currentGroupItemsContainer');
    if (!container) return;
    
    if (!window.tempGroupItems || window.tempGroupItems.length === 0) {
        container.innerHTML = '<div class="text-center text-gray-400 py-4">No items added. Click "Add Item" to add.</div>';
        return;
    }
    
    container.innerHTML = window.tempGroupItems.map((item, index) => {
        let details = '';
        if (item.paymentOption === 'cash_only') {
            details = `UGX ${item.cashAmount.toLocaleString()}`;
        } else if (item.paymentOption === 'item_only') {
            details = `${item.quantity} item(s)`;
        } else {
            const parts = [];
            if (item.cashAmount > 0) parts.push(`UGX ${item.cashAmount.toLocaleString()}`);
            if (item.quantity > 0) parts.push(`${item.quantity} item(s)`);
            details = parts.join(' + ');
        }
        
        return `
            <div class="bg-white rounded-lg p-3 border flex justify-between items-center">
                <div>
                    <p class="font-medium">📦 ${escapeHtml(item.name)}</p>
                    <p class="text-sm text-green-600">${details}</p>
                </div>
                <button type="button" onclick="removeTempItem(${index})" class="text-red-600 hover:text-red-800">Remove</button>
            </div>
        `;
    }).join('');
}

function removeTempItem(index) {
    window.tempGroupItems.splice(index, 1);
    renderCurrentGroupItems();
}

// ==================== SAVE ACTIVITY GROUP ====================

function saveActivityGroup() {
    const groupName = document.getElementById('groupName').value.trim();
    const periodType = document.getElementById('groupPeriodType').value;
    const statusGroupId = document.getElementById('groupStatusGroupId').value || null;
    
    if (!groupName) {
        alert('Please enter a group name');
        return;
    }
    
    if (!window.tempGroupItems || window.tempGroupItems.length === 0) {
        alert('Please add at least one item to the group');
        return;
    }
    
    let statusGroupInfo = null;
    if (statusGroupId && window.existingStatusGroups) {
        statusGroupInfo = window.existingStatusGroups.find(g => g.id === statusGroupId);
    }
    
    let totalCashAmount = 0;
    for (const item of window.tempGroupItems) {
        if (item.paymentOption === 'cash_only') {
            totalCashAmount += item.cashAmount;
        } else if (item.paymentOption === 'either') {
            totalCashAmount += item.cashAmount;
        }
    }
    
    const newGroup = {
        id: `group_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
        name: groupName,
        periodType: periodType,
        statusGroupId: statusGroupId,
        statusGroupName: statusGroupInfo?.name || null,
        items: [...window.tempGroupItems],
        totalAmount: totalCashAmount,
        createdAt: new Date().toISOString()
    };
    
    if (!window.activityGroupsData) window.activityGroupsData = [];
    window.activityGroupsData.push(newGroup);
    
    console.log('Activity group saved:', newGroup);
    
    window.tempGroupItems = [];
    
    closeSubModal();
    renderActivityGroupsList();
    updateSummaryTotals();
}

// ==================== RENDER ACTIVITY GROUPS LIST ====================

function renderActivityGroupsList() {
    const container = document.getElementById('activityGroupsContainer');
    if (!container) return;
    
    if (!window.activityGroupsData || window.activityGroupsData.length === 0) {
        container.innerHTML = '<div class="text-center text-gray-400 py-8">No activity groups added yet. Click "Add Activity Group" to create one.</div>';
        return;
    }
    
    const oneTimeGroups = window.activityGroupsData.filter(g => g.periodType === 'one_time');
    const termlyGroups = window.activityGroupsData.filter(g => g.periodType === 'termly');
    const yearlyGroups = window.activityGroupsData.filter(g => g.periodType === 'yearly');
    
    function renderGroupSection(groups, title, icon, bgColor, borderColor, textColor) {
        if (groups.length === 0) return '';
        
        return `
            <div class="mb-4">
                <h4 class="font-bold text-lg mb-2">${icon} ${title}</h4>
                <div class="space-y-3">
                    ${groups.map(group => `
                        <div class="border-2 ${borderColor} rounded-lg p-4 ${bgColor}">
                            <div class="flex justify-between items-start mb-3">
                                <div>
                                    <h5 class="font-bold text-md">${escapeHtml(group.name)}</h5>
                                    ${group.statusGroupName ? `<p class="text-xs text-gray-500 mt-1">🏷️ Status: ${escapeHtml(group.statusGroupName)}</p>` : ''}
                                </div>
                                <div class="flex gap-2">
                                    <button type="button" onclick="editActivityGroup('${group.id}')" class="bg-blue-500 text-white px-3 py-1 rounded text-sm">Edit</button>
                                    <button type="button" onclick="deleteActivityGroup('${group.id}')" class="bg-red-500 text-white px-3 py-1 rounded text-sm">Delete</button>
                                </div>
                            </div>
                            <div class="space-y-2">
                                ${group.items.map(item => {
                                    let details = '';
                                    if (item.paymentOption === 'cash_only') {
                                        details = `UGX ${item.cashAmount.toLocaleString()}`;
                                    } else if (item.paymentOption === 'item_only') {
                                        details = `${item.quantity} item(s)`;
                                    } else {
                                        const parts = [];
                                        if (item.cashAmount > 0) parts.push(`UGX ${item.cashAmount.toLocaleString()}`);
                                        if (item.quantity > 0) parts.push(`${item.quantity} item(s)`);
                                        details = parts.join(' + ');
                                    }
                                    return `
                                        <div class="bg-white rounded p-2 flex justify-between items-center">
                                            <span class="font-medium">📦 ${escapeHtml(item.name)}</span>
                                            <span class="font-semibold text-green-600">${details}</span>
                                        </div>
                                    `;
                                }).join('')}
                            </div>
                            <div class="mt-3 pt-2 border-t ${borderColor} flex justify-between font-semibold">
                                <span>Group Total:</span>
                                <span class="${textColor}">UGX ${group.totalAmount.toLocaleString()}</span>
                            </div>
                        </div>
                    `).join('')}
                </div>
            </div>
        `;
    }
    
    container.innerHTML = `
        ${renderGroupSection(oneTimeGroups, 'One-Time Activities', '⭐', 'bg-purple-50', 'border-purple-300', 'text-purple-600')}
        ${renderGroupSection(termlyGroups, 'Termly Activities', '📅', 'bg-green-50', 'border-green-300', 'text-green-600')}
        ${renderGroupSection(yearlyGroups, 'Yearly Activities', '📆', 'bg-orange-50', 'border-orange-300', 'text-orange-600')}
    `;
}

// ==================== EDIT ACTIVITY GROUP ====================






function updateActivityGroup() {
    const groupName = document.getElementById('editGroupName').value.trim();
    const periodType = document.getElementById('editGroupPeriodType').value;
    const statusGroupId = document.getElementById('editGroupStatusGroupId').value || null;
    if (!groupName) { alert('Enter group name'); return; }
    if (window.tempGroupItems.length === 0) { alert('Add at least one item'); return; }
    
    let statusGroupInfo = null;
    if (statusGroupId && window.existingStatusGroups) statusGroupInfo = window.existingStatusGroups.find(g => g.id === statusGroupId);
    
    let totalCashAmount = 0;
    for (const item of window.tempGroupItems) {
        if (item.paymentOption === 'cash_only' || item.paymentOption === 'either') totalCashAmount += item.cashAmount;
    }
    
    const groupIndex = window.activityGroupsData.findIndex(g => g.id === window.editGroupId);
    if (groupIndex !== -1) {
        window.activityGroupsData[groupIndex] = { ...window.activityGroupsData[groupIndex], name: groupName, periodType, statusGroupId, statusGroupName: statusGroupInfo?.name || null, items: [...window.tempGroupItems], totalAmount: totalCashAmount, updatedAt: new Date().toISOString() };
    }
    
    window.tempGroupItems = [];
    window.editGroupId = null;
    closeSubModal();
    renderActivityGroupsList();
    updateSummaryTotals();
    alert('✅ Activity group updated!');
}

// ==================== DELETE ACTIVITY GROUP ====================

function deleteActivityGroup(groupId) {
    if (!confirm('Are you sure you want to delete this activity group?')) return;
    const groupIndex = window.activityGroupsData.findIndex(g => g.id === groupId);
    if (groupIndex !== -1) {
        const groupName = window.activityGroupsData[groupIndex].name;
        window.activityGroupsData.splice(groupIndex, 1);
        renderActivityGroupsList();
        updateSummaryTotals();
        alert(`✅ "${groupName}" deleted!`);
    }
}

// ==================== STATUS GROUP MODALS ====================

function showStatusGroupsModal() {
    const modalHtml = `
        <div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[60]">
            <div class="bg-white rounded-2xl p-6 max-w-md w-full mx-4">
                <div class="flex justify-between items-center mb-4"><h3 class="text-xl font-bold">Manage Status Groups</h3><button onclick="closeSubModal()" class="text-gray-500 text-2xl">&times;</button></div>
                <button onclick="showCreateStatusGroupModal()" class="w-full bg-green-600 text-white px-4 py-2 rounded-lg mb-4">Create New Status Group</button>
                <div class="space-y-2 max-h-96 overflow-y-auto">${window.existingStatusGroups.map(g => `<div class="border rounded-lg p-3 flex justify-between items-center"><div><div class="font-medium">${escapeHtml(g.name)}</div><div class="text-xs text-gray-500">${escapeHtml(g.description || '')}</div></div><button onclick="deleteStatusGroup('${g.id}')" class="text-red-600 text-sm">Delete</button></div>`).join('')}</div>
                <button onclick="closeSubModal()" class="w-full bg-gray-300 text-gray-700 py-2 rounded-lg mt-4">Close</button>
            </div>
        </div>
    `;
    document.body.insertAdjacentHTML('beforeend', modalHtml);
}

function showCreateStatusGroupModal() {
    const modalHtml = `
        <div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[70]">
            <div class="bg-white rounded-2xl p-6 max-w-md w-full mx-4">
                <div class="flex justify-between items-center mb-4"><h4 class="text-lg font-bold">Create Status Group</h4><button onclick="closeSubModal()" class="text-gray-500 text-2xl">&times;</button></div>
                <div class="space-y-4">
                    <div><label class="block text-sm font-medium mb-1">Group Name</label><input type="text" id="newStatusGroupName" class="w-full border rounded-lg px-3 py-2"></div>
                    <div><label class="block text-sm font-medium mb-1">Description</label><textarea id="newStatusGroupDesc" rows="2" class="w-full border rounded-lg px-3 py-2"></textarea></div>
                    <div class="flex gap-3"><button id="createStatusGroupBtn" class="flex-1 bg-blue-600 text-white py-2 rounded-lg">Create</button><button onclick="closeSubModal()" class="flex-1 bg-gray-300 text-gray-700 py-2 rounded-lg">Cancel</button></div>
                </div>
            </div>
        </div>
    `;
    document.body.insertAdjacentHTML('beforeend', modalHtml);
    document.getElementById('createStatusGroupBtn').addEventListener('click', async () => {
        const name = document.getElementById('newStatusGroupName').value.trim();
        if (!name) { alert('Enter group name'); return; }
        const description = document.getElementById('newStatusGroupDesc').value;
        const response = await fetch('/api/fee/status-groups', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, description, color: '#6b7280', isActive: true }) });
        if (response.ok) {
            const result = await response.json();
            window.existingStatusGroups.push(result.group);
            closeSubModal();
            showStatusGroupsModal();
            alert('✅ Status group created!');
        } else alert('❌ Error creating status group');
    });
}

function showQuickAddStatusGroup() {
    const modalHtml = `
        <div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[70]">
            <div class="bg-white rounded-2xl p-6 max-w-md w-full mx-4">
                <h4 class="text-lg font-bold mb-4">Create Status Group</h4>
                <div class="space-y-4">
                    <div><input type="text" id="quickStatusName" placeholder="Group Name" class="w-full border rounded-lg px-3 py-2"></div>
                    <div><textarea id="quickStatusDesc" rows="2" placeholder="Description" class="w-full border rounded-lg px-3 py-2"></textarea></div>
                    <div class="flex gap-3"><button id="quickCreateBtn" class="flex-1 bg-blue-600 text-white py-2 rounded-lg">Create & Select</button><button onclick="closeSubModal()" class="flex-1 bg-gray-300 text-gray-700 py-2 rounded-lg">Cancel</button></div>
                </div>
            </div>
        </div>
    `;
    document.body.insertAdjacentHTML('beforeend', modalHtml);
    document.getElementById('quickCreateBtn').addEventListener('click', async () => {
        const name = document.getElementById('quickStatusName').value.trim();
        if (!name) { alert('Enter group name'); return; }
        const description = document.getElementById('quickStatusDesc').value;
        const response = await fetch('/api/fee/status-groups', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, description, color: '#6b7280', isActive: true }) });
        if (response.ok) {
            const result = await response.json();
            window.existingStatusGroups.push(result.group);
            const select = document.getElementById('groupStatusGroupId');
            if (select) { const opt = document.createElement('option'); opt.value = result.group.id; opt.textContent = name; select.appendChild(opt); select.value = result.group.id; }
            closeSubModal();
            alert('✅ Status group created and selected!');
        } else alert('❌ Error creating status group');
    });
}

async function deleteStatusGroup(groupId) {
    if (!confirm('Delete this status group?')) return;
    const response = await fetch(`/api/fee/status-groups/${groupId}`, { method: 'DELETE' });
    if (response.ok) {
        window.existingStatusGroups = window.existingStatusGroups.filter(g => g.id !== groupId);
        closeSubModal();
        showStatusGroupsModal();
        alert('✅ Status group deleted');
    } else alert('❌ Error deleting');
}

// ==================== SAVE FEE STRUCTURE TO SERVER ====================

// ==================== VERIFIED SAVE FEE STRUCTURE FUNCTION ====================

async function saveFeeStructureToServer() {
    const name = document.getElementById('modalFsName').value.trim();
    const level = document.getElementById('modalFsLevel').value;
    const tuition = parseInt(document.getElementById('modalFsTuition').value) || 0;
    
    console.log('=== SAVING FEE STRUCTURE ===');
    console.log('Name:', name);
    console.log('Level:', level);
    console.log('Tuition:', tuition);
    console.log('Activity Groups Data:', window.activityGroupsData);
    
    if (!name) {
        alert('Please enter a fee structure name');
        return;
    }
    
    // Build activity components - MAKE SURE THIS IS CORRECT
    const activityComponents = [];
    
    if (window.activityGroupsData && window.activityGroupsData.length > 0) {
        for (const group of window.activityGroupsData) {
            console.log('Processing group:', group.name, 'Items:', group.items.length);
            
            const component = {
                id: group.id,
                name: group.name,
                periodType: group.periodType,
                statusGroupId: group.statusGroupId || null,
                statusGroupName: group.statusGroupName || null,
                items: group.items.map(item => ({
                    id: item.id,
                    name: item.name,
                    quantity: item.quantity || 1,
                    cashAmount: item.cashAmount || 0,
                    totalAmount: item.cashAmount || 0,
                    paymentOption: item.paymentOption,
                    isTangible: item.paymentOption !== 'cash_only'
                })),
                totalAmount: group.totalAmount || 0,
                createdAt: group.createdAt
            };
            
            activityComponents.push(component);
            console.log('  Added component:', component.name, 'with', component.items.length, 'items');
        }
    }
    
    console.log('Total activity components to send:', activityComponents.length);
    
    const feeStructureData = { 
        name, 
        level, 
        tuition, 
        activityComponents 
    };
    
    console.log('Sending data:', JSON.stringify(feeStructureData, null, 2));
    
    const submitBtn = document.querySelector('#addFeeStructureModalForm button[type="submit"]');
    const originalText = submitBtn.innerHTML;
    submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving...';
    submitBtn.disabled = true;
    
    try {
        const response = await fetch('/api/fee/structures/enhanced', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(feeStructureData)
        });
        
        const result = await response.json();
        console.log('Server response:', result);
        
        if (response.ok) {
            alert(`✅ Fee structure "${name}" saved successfully!\n\n💰 Tuition: UGX ${tuition.toLocaleString()}\n📊 Activity Groups: ${activityComponents.length}`);
            closeModal();
            if (typeof showFeeManagement === 'function') {
                showFeeManagement();
            } else {
                window.location.reload();
            }
        } else {
            alert('❌ Error: ' + (result.error || 'Unknown error'));
        }
    } catch (error) {
        console.error('Error:', error);
        alert('Network error: ' + error.message);
    } finally {
        submitBtn.innerHTML = originalText;
        submitBtn.disabled = false;
    }
}

// ==================== UTILITY FUNCTIONS ====================

function closeSubModal() {
    const modals = document.querySelectorAll('[class*="z-6"], [class*="z-7"]');
    if (modals.length > 0) modals[modals.length - 1].remove();
    else { const modal = document.querySelector('.fixed.inset-0.bg-black.bg-opacity-50'); if (modal && modal !== document.querySelector('.z-50')) modal.remove(); }
}

function closeModal() {
    const modal = document.querySelector('.fixed.inset-0.bg-black.bg-opacity-50.z-50');
    if (modal) modal.remove();
}

function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

// ==================== UPDATE SUMMARY TOTALS - FIXED ====================

function updateSummaryTotals() {
    const tuition = parseInt(document.getElementById('modalFsTuition')?.value) || 0;
    
    let oneTimeTotal = 0;
    let termlyTotal = 0;
    let yearlyTotal = 0;
    
    console.log('Updating summary totals. Groups count:', window.activityGroupsData ? window.activityGroupsData.length : 0);
    
    if (window.activityGroupsData && window.activityGroupsData.length > 0) {
        for (const group of window.activityGroupsData) {
            console.log(`Group: ${group.name}, Period: ${group.periodType}, Total: ${group.totalAmount}`);
            if (group.periodType === 'one_time') {
                oneTimeTotal += group.totalAmount;
            } else if (group.periodType === 'termly') {
                termlyTotal += group.totalAmount;
            } else if (group.periodType === 'yearly') {
                yearlyTotal += group.totalAmount;
            }
        }
    }
    
    const total = tuition + oneTimeTotal + termlyTotal + yearlyTotal;
    
    console.log(`Totals - Tuition: ${tuition}, OneTime: ${oneTimeTotal}, Termly: ${termlyTotal}, Yearly: ${yearlyTotal}, Grand: ${total}`);
    
    const summaryTuition = document.getElementById('summaryTuition');
    const summaryOneTime = document.getElementById('summaryOneTime');
    const summaryTermly = document.getElementById('summaryTermly');
    const summaryYearly = document.getElementById('summaryYearly');
    const summaryTotal = document.getElementById('summaryTotal');
    
    if (summaryTuition) summaryTuition.innerHTML = `UGX ${tuition.toLocaleString()}`;
    if (summaryOneTime) summaryOneTime.innerHTML = `UGX ${oneTimeTotal.toLocaleString()}`;
    if (summaryTermly) summaryTermly.innerHTML = `UGX ${termlyTotal.toLocaleString()}`;
    if (summaryYearly) summaryYearly.innerHTML = `UGX ${yearlyTotal.toLocaleString()}`;
    if (summaryTotal) summaryTotal.innerHTML = `UGX ${total.toLocaleString()}`;
}

