function updateStatusGroupDropdowns() {
    const optionsHtml = '<option value="">-- No Status Group --</option>' + window.existingStatusGroups.map(g => `<option value="${g.id}">${escapeHtml(g.name)}</option>`).join('');
    ['groupStatusGroupId', 'editGroupStatusGroupId'].forEach(id => {
        const select = document.getElementById(id);
        if (select) {
            const currentValue = select.value;
            select.innerHTML = optionsHtml;
            if (currentValue && window.existingStatusGroups.some(g => g.id === currentValue)) select.value = currentValue;
        }
    });
}

