function renderEditGroupItems() {
    if (!window.tempGroupItems || window.tempGroupItems.length === 0) {
        return '<div class="text-center text-gray-400 py-4">No items added. Click "Add Item" to add.</div>';
    }
    
    return window.tempGroupItems.map((item, idx) => {
        let detailsDisplay = '';
        if (item.paymentOption === 'cash_only') {
            detailsDisplay = `UGX ${(item.cashAmount || item.totalAmount || 0).toLocaleString()}`;
        } else if (item.paymentOption === 'item_only') {
            detailsDisplay = `${item.quantity} item(s)`;
        } else {
            const parts = [];
            if (item.cashAmount > 0) parts.push(`UGX ${item.cashAmount.toLocaleString()}`);
            if (item.quantity > 0) parts.push(`${item.quantity} item(s)`);
            detailsDisplay = parts.join(' + ');
        }
        
        return `
            <div class="bg-white rounded-lg p-3 border flex justify-between items-center">
                <div>
                    <p class="font-medium">${escapeHtml(item.name)}</p>
                    <p class="text-xs text-gray-500">${detailsDisplay}</p>
                </div>
                <button type="button" onclick="removeEditItem(${idx})" class="text-red-600 text-sm hover:text-red-800">Remove</button>
            </div>
        `;
    }).join('');
}

function addItemToEditGroup() {
    // Reuse the existing add item modal but with a callback for edit mode
    addItemToCurrentGroupWithCallback(() => {
        const container = document.getElementById('editGroupItemsContainer');
        if (container) {
            container.innerHTML = renderEditGroupItems();
        }
    });
}

function addItemToCurrentGroupWithCallback(callback) {
    const paymentOptions = [
        { value: 'cash_only', label: '💵 Cash Only', description: 'Must be paid in cash' },
        { value: 'item_only', label: '📦 Item Only', description: 'Must be brought physically' },
        { value: 'either', label: '🔄 Either (Cash or Item)', description: 'Can be paid cash OR bring items' }
    ];
    
    const modalHtml = `
        <div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[201]">
            <div class="bg-white rounded-2xl p-6 max-w-md w-full mx-4">
                <div class="flex justify-between items-center mb-4 pb-2 border-b">
                    <h4 class="text-lg font-bold">Add Item to Group</h4>
                    <button onclick="closeAddItemModal()" class="text-gray-500 hover:text-gray-700">&times;</button>
                </div>
                
                <div class="space-y-4">
                    <div>
                        <label class="block text-sm font-medium mb-1 required-field">Item Name *</label>
                        <input type="text" id="editItemName" class="w-full border rounded-lg px-3 py-2">
                    </div>
                    
                    <div>
                        <label class="block text-sm font-medium mb-1 required-field">Payment Option *</label>
                        <div class="space-y-2">
                            ${paymentOptions.map(opt => `
                                <label class="flex items-start p-3 border rounded-lg cursor-pointer hover:bg-gray-50">
                                    <input type="radio" name="editPaymentOption" value="${opt.value}" class="mr-3 mt-1 edit-payment-radio" ${opt.value === 'either' ? 'checked' : ''}>
                                    <div>
                                        <div class="font-medium">${opt.label}</div>
                                        <div class="text-xs text-gray-500">${opt.description}</div>
                                    </div>
                                </label>
                            `).join('')}
                        </div>
                    </div>
                    
                    <div id="editDynamicFields" class="space-y-4">
                        <div class="bg-blue-50 p-4 rounded-lg text-center text-blue-600">Select a payment option above</div>
                    </div>
                    
                    <div class="flex gap-3 pt-2">
                        <button type="button" id="confirmAddEditItem" class="flex-1 bg-blue-600 text-white py-2 rounded-lg">Add Item</button>
                        <button type="button" onclick="closeAddItemModal()" class="flex-1 bg-gray-300 text-gray-700 py-2 rounded-lg">Cancel</button>
                    </div>
                </div>
            </div>
        </div>
    `;
    
    document.body.insertAdjacentHTML('beforeend', modalHtml);
    
    function updateEditDynamicFields(selectedOption) {
        const container = document.getElementById('editDynamicFields');
        if (!container) return;
        
        if (selectedOption === 'cash_only') {
            container.innerHTML = `
                <div>
                    <label class="block text-sm font-medium mb-1 required-field">Amount (UGX) *</label>
                    <input type="number" id="editItemCashAmount" class="w-full border rounded-lg px-3 py-2" value="0" min="0" step="1000">
                </div>
            `;
        } 
        else if (selectedOption === 'item_only') {
            container.innerHTML = `
                <div>
                    <label class="block text-sm font-medium mb-1 required-field">Quantity to Bring *</label>
                    <input type="number" id="editItemQuantity" class="w-full border rounded-lg px-3 py-2" value="1" min="1">
                </div>
            `;
        } 
        else {
            container.innerHTML = `
                <div class="grid grid-cols-2 gap-3">
                    <div>
                        <label class="block text-sm font-medium mb-1">Cash Amount (UGX)</label>
                        <input type="number" id="editItemCashAmount" class="w-full border rounded-lg px-3 py-2" value="0" min="0" step="1000">
                    </div>
                    <div>
                        <label class="block text-sm font-medium mb-1">Quantity to Bring</label>
                        <input type="number" id="editItemQuantity" class="w-full border rounded-lg px-3 py-2" value="0" min="0">
                    </div>
                </div>
                <div class="bg-yellow-50 p-2 rounded text-xs text-yellow-700">Enter either cash amount, quantity, or both</div>
            `;
        }
    }
    
    const radioButtons = document.querySelectorAll('.edit-payment-radio');
    radioButtons.forEach(radio => {
        radio.addEventListener('change', (e) => {
            if (e.target.checked) updateEditDynamicFields(e.target.value);
        });
    });
    
    updateEditDynamicFields('either');
    
    document.getElementById('confirmAddEditItem').addEventListener('click', () => {
        const itemName = document.getElementById('editItemName').value.trim();
        const paymentOption = document.querySelector('input[name="editPaymentOption"]:checked')?.value || 'either';
        
        if (!itemName) {
            alert('Please enter an item name');
            return;
        }
        
        let quantity = 0;
        let cashAmount = 0;
        
        if (paymentOption === 'cash_only') {
            cashAmount = parseInt(document.getElementById('editItemCashAmount')?.value) || 0;
            if (cashAmount <= 0) {
                alert('Please enter a valid cash amount');
                return;
            }
            quantity = 1;
        } 
        else if (paymentOption === 'item_only') {
            quantity = parseInt(document.getElementById('editItemQuantity')?.value) || 0;
            if (quantity <= 0) {
                alert('Please enter a valid quantity');
                return;
            }
            cashAmount = 0;
        } 
        else {
            cashAmount = parseInt(document.getElementById('editItemCashAmount')?.value) || 0;
            quantity = parseInt(document.getElementById('editItemQuantity')?.value) || 0;
            if (cashAmount <= 0 && quantity <= 0) {
                alert('Please enter either cash amount, quantity, or both');
                return;
            }
        }
        
        const newItem = {
            id: `item_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
            name: itemName,
            quantity: quantity,
            cashAmount: cashAmount,
            totalAmount: cashAmount,
            paymentOption: paymentOption,
            isTangible: paymentOption !== 'cash_only'
        };
        
        window.tempGroupItems.push(newItem);
        closeAddItemModal();
        if (callback) callback();
    });
}



function removeEditItem(index) {
    window.tempGroupItems.splice(index, 1);
    const container = document.getElementById('editGroupItemsContainer');
    if (container) {
        container.innerHTML = renderEditGroupItems();
    }
}

function saveEditedActivityGroup() {
    const groupName = document.getElementById('editGroupName').value.trim();
    const periodType = document.getElementById('editGroupPeriodType').value;
    const statusGroupId = document.getElementById('editGroupStatusGroupId').value || null;
    
    if (!groupName) {
        alert('Please enter a group name');
        return;
    }
    
    if (window.tempGroupItems.length === 0) {
        alert('Please add at least one item to the group');
        return;
    }
    
    let statusGroupInfo = null;
    if (statusGroupId && window.existingStatusGroups) {
        statusGroupInfo = window.existingStatusGroups.find(g => g.id === statusGroupId);
    }
    
    let totalCashAmount = 0;
    for (const item of window.tempGroupItems) {
        if (item.paymentOption === 'cash_only') {
            totalCashAmount += item.cashAmount || item.totalAmount || 0;
        } else if (item.paymentOption === 'either') {
            totalCashAmount += item.cashAmount || 0;
        }
    }
    
    const groupIndex = window.activityGroupsData.findIndex(g => g.id === window.editGroupId);
    if (groupIndex !== -1) {
        window.activityGroupsData[groupIndex] = {
            ...window.activityGroupsData[groupIndex],
            name: groupName,
            periodType: periodType,
            statusGroupId: statusGroupId,
            statusGroupName: statusGroupInfo?.name || null,
            items: JSON.parse(JSON.stringify(window.tempGroupItems)),
            totalAmount: totalCashAmount,
            updatedAt: new Date().toISOString()
        };
        
        console.log('Group updated successfully');
    }
    
    window.tempGroupItems = [];
    window.editGroupId = null;
    
    closeEditModal();
    renderActivityGroupsList();
    updateSummaryTotals();
    
    alert(`✅ Activity group "${groupName}" updated successfully!`);
}

function closeEditModal() {
    const modal = document.querySelector('.z-\\[200\\]');
    if (modal) modal.remove();
}

function showAddStatusGroupQuickModalForEdit() {
    const modalHtml = `
        <div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[202]">
            <div class="bg-white rounded-2xl p-6 max-w-md w-full mx-4">
                <div class="flex justify-between items-center mb-4 pb-2 border-b">
                    <h4 class="text-lg font-bold">Create Status Group</h4>
                    <button onclick="closeStatusModal()" class="text-gray-500 hover:text-gray-700">&times;</button>
                </div>
                <div class="space-y-4">
                    <div>
                        <label class="block text-sm font-medium mb-1">Group Name *</label>
                        <input type="text" id="quickStatusGroupNameEdit" class="w-full border rounded-lg px-3 py-2">
                    </div>
                    <div>
                        <label class="block text-sm font-medium mb-1">Description</label>
                        <textarea id="quickStatusGroupDescEdit" rows="2" class="w-full border rounded-lg px-3 py-2"></textarea>
                    </div>
                    <div class="flex gap-3">
                        <button id="createQuickStatusEdit" class="flex-1 bg-blue-600 text-white py-2 rounded-lg">Create & Select</button>
                        <button onclick="closeStatusModal()" class="flex-1 bg-gray-300 text-gray-700 py-2 rounded-lg">Cancel</button>
                    </div>
                </div>
            </div>
        </div>
    `;
    
    document.body.insertAdjacentHTML('beforeend', modalHtml);
    
    document.getElementById('createQuickStatusEdit').addEventListener('click', async () => {
        const name = document.getElementById('quickStatusGroupNameEdit').value.trim();
        const description = document.getElementById('quickStatusGroupDescEdit').value;
        
        if (!name) {
            alert('Please enter a group name');
            return;
        }
        
        try {
            const response = await fetch('/api/fee/status-groups', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ name, description, color: '#6b7280', isActive: true })
            });
            
            if (response.ok) {
                const result = await response.json();
                if (!window.existingStatusGroups) window.existingStatusGroups = [];
                window.existingStatusGroups.push(result.group);
                
                // Update the dropdown
                const targetSelect = document.getElementById('editGroupStatusGroupId');
                if (targetSelect) {
                    const option = document.createElement('option');
                    option.value = result.group.id;
                    option.textContent = name;
                    targetSelect.appendChild(option);
                    targetSelect.value = result.group.id;
                }
                
                closeStatusModal();
                alert('✅ Status group created and selected!');
            } else {
                alert('❌ Error creating status group');
            }
        } catch (error) {
            alert('Network error: ' + error.message);
        }
    });
}

function closeStatusModal() {
    const modal = document.querySelector('.z-\\[202\\]');
    if (modal) modal.remove();
}


