// ==================== ADD ACTIVITY GROUP ====================

function addActivityGroup(periodType) {
    console.log('addActivityGroup called for:', periodType);
    
    const groupId = `${periodType}_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
    const color = periodType === 'one_time' ? 'purple' : periodType === 'termly' ? 'green' : 'orange';
    const bgColor = periodType === 'one_time' ? 'bg-purple-50' : periodType === 'termly' ? 'bg-green-50' : 'bg-orange-50';
    const borderColor = periodType === 'one_time' ? 'border-purple-200' : periodType === 'termly' ? 'border-green-200' : 'border-orange-200';
    
    const html = `
        <div id="${groupId}" class="border-2 ${borderColor} rounded-lg p-3 ${bgColor} mb-3" data-period-type="${periodType}">
            <div class="flex justify-between items-center mb-3">
                <input type="text" placeholder="Activity Group Name" 
                       class="flex-1 border rounded-lg px-3 py-2 text-sm groupNameInput" 
                       oninput="updateFeeStructureTotals()">
                <button type="button" onclick="removeActivityGroup('${groupId}')" class="text-red-600 ml-2 px-2 py-1">
                    <i class="fas fa-trash"></i> Remove
                </button>
            </div>
            <div class="ml-4">
                <div class="flex justify-between items-center mb-2">
                    <h4 class="text-sm font-semibold">Items:</h4>
                    <button type="button" onclick="addItemToGroup('${groupId}')" class="bg-gray-200 px-2 py-1 rounded text-xs">
                        <i class="fas fa-plus"></i> Add Item
                    </button>
                </div>
                <div id="${groupId}_items" class="space-y-2">
                    <div class="text-center text-gray-400 text-xs py-2">No items added.</div>
                </div>
            </div>
        </div>
    `;
    
    let container;
    if (periodType === 'one_time') container = document.getElementById('oneTimeGroupsContainer');
    else if (periodType === 'termly') container = document.getElementById('termlyGroupsContainer');
    else container = document.getElementById('yearlyGroupsContainer');
    
    if (!container) return;
    
    // Remove empty message
    const emptyMsgId = periodType === 'one_time' ? 'emptyOneTimeMsg' : periodType === 'termly' ? 'emptyTermlyMsg' : 'emptyYearlyMsg';
    const emptyMsg = document.getElementById(emptyMsgId);
    if (emptyMsg && emptyMsg.parentNode === container) emptyMsg.remove();
    
    container.insertAdjacentHTML('beforeend', html);
    
    // Store reference
    if (!window.tempActivityGroups) window.tempActivityGroups = { one_time: [], termly: [], yearly: [] };
    window.tempActivityGroups[periodType].push({ groupId: groupId });
    
    updateFeeStructureTotals();
}

// ==================== ADD ITEM TO GROUP - FIXED ====================

function addItemToGroup(groupId) {
    console.log('addItemToGroup called for group:', groupId);
    
    const itemId = `item_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
    
    const html = `
        <div id="${itemId}" class="flex gap-2 items-center bg-white p-2 rounded-lg border mb-2">
            <input type="text" placeholder="Item name" class="flex-1 border rounded px-2 py-1 text-sm" 
                   oninput="updateFeeStructureTotals()">
            <input type="number" placeholder="Qty" class="w-16 border rounded px-2 py-1 text-sm" 
                   value="1" min="1" oninput="updateFeeStructureTotals()">
            <input type="number" placeholder="Total Amount" class="w-28 border rounded px-2 py-1 text-sm" 
                   value="0" min="0" oninput="updateFeeStructureTotals()">
            <button type="button" onclick="removeItemFromGroup('${itemId}', '${groupId}')" class="text-red-600 px-1">
                <i class="fas fa-times"></i>
            </button>
        </div>
    `;
    
    const itemsContainer = document.getElementById(`${groupId}_items`);
    if (!itemsContainer) {
        console.error('Items container not found for group:', groupId);
        return;
    }
    
    // Remove empty message
    const emptyMsg = itemsContainer.querySelector('.text-center.text-gray-400');
    if (emptyMsg && emptyMsg.parentNode === itemsContainer) emptyMsg.remove();
    
    itemsContainer.insertAdjacentHTML('beforeend', html);
    updateFeeStructureTotals();
}

