function addItemToGroup(groupId, periodType) {
    const itemId = 'item_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);
    const html = `
        <div id="${itemId}" class="flex gap-2 items-center bg-gray-50 p-2 rounded-lg border">
            <input type="text" placeholder="Item name" 
                   class="flex-1 border rounded px-2 py-1 text-sm itemNameInput" data-item-id="${itemId}">
            <input type="number" placeholder="Qty" 
                   class="w-16 border rounded px-2 py-1 text-sm itemQuantityInput" value="1" min="1" data-item-id="${itemId}">
            <input type="number" placeholder="Total Amount" 
                   class="w-28 border rounded px-2 py-1 text-sm itemAmountInput" value="0" min="0" data-item-id="${itemId}">
            <button type="button" onclick="removeItem('${itemId}', '${groupId}')" class="text-red-600 hover:text-red-800 px-1">
                <i class="fas fa-times"></i>
            </button>
        </div>
    `;
    
    const container = document.getElementById(`${groupId}_items`);
    if (!container) return;
    
    // Remove empty message
    const emptyMsg = container.querySelector('.text-center.text-gray-400');
    if (emptyMsg && emptyMsg.parentNode === container) {
        emptyMsg.remove();
    }
    
    container.insertAdjacentHTML('beforeend', html);
    
    // Add event listeners to the new inputs
    const amountInput = container.querySelector(`#${itemId} .itemAmountInput`);
    if (amountInput) {
        amountInput.addEventListener('input', function() {
            updateModalTotals();
        });
        amountInput.addEventListener('change', function() {
            updateModalTotals();
        });
    }
    
    const quantityInput = container.querySelector(`#${itemId} .itemQuantityInput`);
    if (quantityInput) {
        quantityInput.addEventListener('input', function() {
            updateModalTotals();
        });
    }
    
    const nameInput = container.querySelector(`#${itemId} .itemNameInput`);
    if (nameInput) {
        nameInput.addEventListener('input', function() {
            updateModalTotals();
        });
    }
    
    updateModalTotals();
}

// ==================== REMOVE FUNCTIONS ====================

function removeItem(itemId, groupId) {
    const element = document.getElementById(itemId);
    if (element) element.remove();
    
    // Check if container is empty
    const container = document.getElementById(`${groupId}_items`);
    if (container && container.children.length === 0) {
        container.innerHTML = '<div class="text-center text-gray-400 text-xs py-2">No items added. Click "Add Item" to add.</div>';
    }
    
    updateModalTotals();
}

function removeGroup(groupId) {
    const element = document.getElementById(groupId);
    if (element) element.remove();
    
    // Remove from temp arrays
    window.tempOneTimeGroups = window.tempOneTimeGroups.filter(g => g.groupId !== groupId);
    window.tempTermlyGroups = window.tempTermlyGroups.filter(g => g.groupId !== groupId);
    window.tempYearlyGroups = window.tempYearlyGroups.filter(g => g.groupId !== groupId);
    
    // Check if containers are empty and add back empty messages
    const oneTimeContainer = document.getElementById('oneTimeGroupsContainer');
    if (oneTimeContainer && oneTimeContainer.children.length === 0 && !document.getElementById('emptyOneTimeMsg')) {
        oneTimeContainer.innerHTML = '<div class="text-center text-gray-400 py-4" id="emptyOneTimeMsg">No one-time activity groups added. Click "Add Activity Group" to add.</div>';
    }
    
    const termlyContainer = document.getElementById('termlyGroupsContainer');
    if (termlyContainer && termlyContainer.children.length === 0 && !document.getElementById('emptyTermlyMsg')) {
        termlyContainer.innerHTML = '<div class="text-center text-gray-400 py-4" id="emptyTermlyMsg">No termly activity groups added. Click "Add Activity Group" to add.</div>';
    }
    
    const yearlyContainer = document.getElementById('yearlyGroupsContainer');
    if (yearlyContainer && yearlyContainer.children.length === 0 && !document.getElementById('emptyYearlyMsg')) {
        yearlyContainer.innerHTML = '<div class="text-center text-gray-400 py-4" id="emptyYearlyMsg">No yearly activity groups added. Click "Add Activity Group" to add.</div>';
    }
    
    updateModalTotals();
}

