// Function to collect data from all components and save
async function saveEnhancedFeeStructure() {
    const name = document.getElementById('modalFsName').value.trim();
    const level = document.getElementById('modalFsLevel').value;
    const tuition = parseInt(document.getElementById('modalFsTuition').value) || 0;
    
    if (!name) {
        alert('Please enter a fee structure name');
        return;
    }
    
    // Collect one-time activities
    const oneTimeActivities = [];
    document.querySelectorAll('#oneTimeActivitiesList > div[id^="ot_"]').forEach(groupDiv => {
        const groupNameInput = groupDiv.querySelector('.oneTimeGroupName');
        const groupName = groupNameInput ? groupNameInput.value.trim() : '';
        
        const items = [];
        const itemDivs = groupDiv.querySelectorAll(`#${groupDiv.id}_items > div[id^="item_"]`);
        itemDivs.forEach(itemDiv => {
            const nameInput = itemDiv.querySelector('.itemName');
            const quantityInput = itemDiv.querySelector('.itemQuantity');
            const amountInput = itemDiv.querySelector('.itemTotalAmount');
            
            const itemName = nameInput ? nameInput.value.trim() : '';
            const quantity = quantityInput ? parseInt(quantityInput.value) || 1 : 1;
            const totalAmount = amountInput ? parseInt(amountInput.value) || 0 : 0;
            
            if (itemName && totalAmount > 0) {
                items.push({
                    name: itemName,
                    quantity: quantity,
                    totalAmount: totalAmount
                });
            }
        });
        
        if (groupName && items.length > 0) {
            oneTimeActivities.push({
                name: groupName,
                items: items
            });
        }
    });
    
    // Collect termly activities similarly
    const termlyActivities = [];
    document.querySelectorAll('#termlyActivitiesList > div[id^="term_"]').forEach(groupDiv => {
        const groupNameInput = groupDiv.querySelector('.termlyGroupName');
        const groupName = groupNameInput ? groupNameInput.value.trim() : '';
        
        const items = [];
        const itemDivs = groupDiv.querySelectorAll(`#${groupDiv.id}_items > div[id^="item_"]`);
        itemDivs.forEach(itemDiv => {
            const nameInput = itemDiv.querySelector('.itemName');
            const quantityInput = itemDiv.querySelector('.itemQuantity');
            const amountInput = itemDiv.querySelector('.itemTotalAmount');
            
            const itemName = nameInput ? nameInput.value.trim() : '';
            const quantity = quantityInput ? parseInt(quantityInput.value) || 1 : 1;
            const totalAmount = amountInput ? parseInt(amountInput.value) || 0 : 0;
            
            if (itemName && totalAmount > 0) {
                items.push({
                    name: itemName,
                    quantity: quantity,
                    totalAmount: totalAmount
                });
            }
        });
        
        if (groupName && items.length > 0) {
            termlyActivities.push({
                name: groupName,
                items: items
            });
        }
    });
    
    // Collect yearly activities similarly
    const yearlyActivities = [];
    document.querySelectorAll('#yearlyActivitiesList > div[id^="year_"]').forEach(groupDiv => {
        const groupNameInput = groupDiv.querySelector('.yearlyGroupName');
        const groupName = groupNameInput ? groupNameInput.value.trim() : '';
        
        const items = [];
        const itemDivs = groupDiv.querySelectorAll(`#${groupDiv.id}_items > div[id^="item_"]`);
        itemDivs.forEach(itemDiv => {
            const nameInput = itemDiv.querySelector('.itemName');
            const quantityInput = itemDiv.querySelector('.itemQuantity');
            const amountInput = itemDiv.querySelector('.itemTotalAmount');
            
            const itemName = nameInput ? nameInput.value.trim() : '';
            const quantity = quantityInput ? parseInt(quantityInput.value) || 1 : 1;
            const totalAmount = amountInput ? parseInt(amountInput.value) || 0 : 0;
            
            if (itemName && totalAmount > 0) {
                items.push({
                    name: itemName,
                    quantity: quantity,
                    totalAmount: totalAmount
                });
            }
        });
        
        if (groupName && items.length > 0) {
            yearlyActivities.push({
                name: groupName,
                items: items
            });
        }
    });
    
    // Collect development components
    const developmentComponents = [];
    document.querySelectorAll('#developmentComponentsList > div[id^="dev_"]').forEach(devDiv => {
        const nameInput = devDiv.querySelector('.devName');
        const amountInput = devDiv.querySelector('.devAmount');
        
        const name = nameInput ? nameInput.value.trim() : '';
        const amount = amountInput ? parseInt(amountInput.value) || 0 : 0;
        
        if (name && amount > 0) {
            developmentComponents.push({
                name: name,
                amount: amount
            });
        }
    });
    
    const feeStructureData = {
        name: name,
        level: level,
        tuition: tuition,
        oneTimeActivities: oneTimeActivities,
        termlyActivities: termlyActivities,
        yearlyActivities: yearlyActivities,
        developmentComponents: developmentComponents
    };
    
    console.log('Saving fee structure:', feeStructureData);
    
    const submitBtn = document.querySelector('#addFeeStructureModalForm button[type="submit"]');
    const originalText = submitBtn.innerText;
    submitBtn.innerText = 'Saving...';
    submitBtn.disabled = true;
    
    try {
        const response = await fetch('/api/fee/structures/enhanced', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(feeStructureData)
        });
        
        if (response.ok) {
            const result = await response.json();
            
            // Calculate totals for summary
            const oneTimeTotal = oneTimeActivities.reduce((sum, act) => 
                sum + act.items.reduce((s, i) => s + i.totalAmount, 0), 0);
            const termlyTotal = termlyActivities.reduce((sum, act) => 
                sum + act.items.reduce((s, i) => s + i.totalAmount, 0), 0);
            const yearlyTotal = yearlyActivities.reduce((sum, act) => 
                sum + act.items.reduce((s, i) => s + i.totalAmount, 0), 0);
            const developmentTotal = developmentComponents.reduce((sum, c) => sum + c.amount, 0);
            
            alert(`✅ Fee structure "${name}" saved successfully!\n\n📊 Summary:\n- Tuition: UGX ${tuition.toLocaleString()}\n- One-Time Activities: UGX ${oneTimeTotal.toLocaleString()}\n- Termly Activities: UGX ${termlyTotal.toLocaleString()} (per term)\n- Yearly Activities: UGX ${yearlyTotal.toLocaleString()}\n- Development Fees: UGX ${developmentTotal.toLocaleString()}`);
            closeModal();
            showFeeManagement();
        } else {
            const error = await response.json();
            alert('❌ Error saving fee structure: ' + (error.error || 'Unknown error'));
        }
    } catch (error) {
        console.error('Error:', error);
        alert('Network error: ' + error.message);
    } finally {
        submitBtn.innerText = originalText;
        submitBtn.disabled = false;
    }
}

