// ==================== ATTACH EXPAND HANDLERS ====================

function attachExpandHandlers() {
    document.querySelectorAll('#reportTable td .cursor-pointer').forEach(function(cell) {
        cell.removeEventListener('click', handleCellClick);
        cell.addEventListener('click', handleCellClick);
    });
}

function handleCellClick(e) {
    var parentTd = this.closest('td');
    if (!parentTd) return;
    
    var button = parentTd.querySelector('button');
    if (button) {
        button.click();
    }
}

// ==================== RENDER REPORT RESULTS ====================

function renderReportResultsV3(data) {
    var container = document.getElementById('reportTableContainer');
    var recordCount = document.getElementById('reportRecordCount');
    
    if (!container) return;
    
    var students = data.students || [];
    var totals = data.totals || {};
    var statusGroupTotals = data.statusGroupTotals || {};
    var filters = data.filters || {};
    var includeTuition = filters.includeTuition !== false;
    var metadata = data.metadata || {};
    var periodsIncluded = metadata.periodsIncluded || [];
    
    if (typeof window.expandedItems === 'undefined') {
        window.expandedItems = {};
    }
    if (typeof window.expandedPeriods === 'undefined') {
        window.expandedPeriods = {};
    }
    
    if (recordCount) {
        recordCount.innerText = students.length;
    }
    
    if (students.length === 0) {
        container.innerHTML = `
            <div class="text-center py-12 text-gray-500">
                <i class="fas fa-inbox text-5xl mb-4 text-gray-300"></i>
                <p>No records found matching your filters</p>
                <p class="text-sm mt-2">Try adjusting your filter criteria</p>
            </div>
        `;
        return;
    }
    
    try {
        // Add periodsIncluded to filters for display
        filters.periodsIncluded = periodsIncluded;
        totals.periodsIncluded = periodsIncluded.length || 1;
        
        var summaryHtml = buildSummaryCardsV3(totals, students.length);
        var tableHtml = buildReportTable(students, totals, statusGroupTotals, includeTuition, filters);
        
        container.innerHTML = summaryHtml + tableHtml;
        attachExpandHandlers();
        
        console.log('✅ Report rendered with', students.length, 'students');
        console.log('📅 Periods:', periodsIncluded.join(', '));
    } catch (error) {
        console.error('Error rendering report:', error);
        container.innerHTML = `
            <div class="bg-red-50 p-6 text-center rounded-lg border border-red-200">
                <i class="fas fa-exclamation-triangle text-red-600 text-4xl mb-3"></i>
                <p class="text-red-600 font-semibold">Error rendering report</p>
                <p class="text-red-500 text-sm mt-1">${error.message}</p>
                <button onclick="generateReportV3()" class="mt-3 bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700">
                    <i class="fas fa-sync-alt"></i> Try Again
                </button>
            </div>
        `;
    }
}

// ==================== SHOW REPORTS PAGE ====================

async function showReports() {
    console.log('showReports called - Version 7.0');
    
    var pageTitle = document.getElementById('pageTitle');
    if (pageTitle) pageTitle.innerHTML = '<i class="fas fa-file-alt mr-2"></i>Comprehensive Reports';
    
    var mainContent = document.getElementById('mainContent');
    if (mainContent) {
        mainContent.innerHTML = '<div class="flex justify-center items-center h-64"><div class="loading-spinner"></div></div>';
    }
    
    try {
        await initializeAcademicSettings();
        var currentYear = currentAcademicSettings.currentYear || new Date().getFullYear();
        var currentTerm = currentAcademicSettings.currentTerm || 1;
        var termName = getTermName(currentTerm);
        
        var filterRes = await fetch('/api/reports/filter-options');
        var result = await filterRes.json();
        reportFilterOptions = result.data;
        
        renderReportsPageV3(reportFilterOptions, termName, currentYear, currentTerm);
        
    } catch (error) {
        console.error('Error loading reports:', error);
        if (mainContent) {
            mainContent.innerHTML = `
                <div class="bg-red-50 p-6 text-center rounded-lg border border-red-200">
                    <i class="fas fa-exclamation-triangle text-red-600 text-4xl mb-3"></i>
                    <p class="text-red-600 font-semibold">Error loading report data</p>
                    <p class="text-red-500 text-sm mt-1">${error.message}</p>
                    <button onclick="showReports()" class="mt-3 bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700">
                        <i class="fas fa-sync-alt"></i> Retry
                    </button>
                </div>
            `;
        }
    }
}

