                        var customBadge6 = itemData4.isCustomized ? ' ⚡' : '';
                        var oneTimeBadge6 = isOneTime4 ? ' ⭐' : '';
                        var optionIcon6 = '';
                        if (paymentOption4 === 'cash_only') optionIcon6 = ' 💵';
