// ==================== HELPER: BUILD STATUS GROUP HEADERS ====================

function buildStatusGroupHeaders(table) {
    try {
        var headers = table.querySelectorAll('thead tr:first-child th');
        var statusGroupHeaders = [];
        var isTuition = false;
        
        for (var i = 0; i < headers.length; i++) {
            var text = headers[i].textContent || '';
            if (text.includes('💰 Tuition')) {
                isTuition = true;
                continue;
            }
            if (text.includes('🏷️') || text.includes('Scholastic') || text.includes('Uniform') || text.includes('Transport') || text.includes('Admission')) {
                var clean = text.replace(/🏷️/g, '').replace(/⚡/g, '').replace(/⭐/g, '').replace(/period\(s\)/g, '').trim();
                if (clean) {
                    statusGroupHeaders.push(clean);
                }
            }
        }
        
        // If no status groups found, use default
        if (statusGroupHeaders.length === 0) {
            statusGroupHeaders = ['Scholastic', 'Uniform', 'Transport', 'Admission'];
        }
        
        return statusGroupHeaders.map(function(h) {
            var display = h === 'scholastic requirement' ? 'Scholastic' : h;
            return '<th>' + escapeHtml(display) + '</th>';
        }).join('');
        
    } catch (e) {
        return '<th>Scholastic</th><th>Uniform</th><th>Transport</th><th>Admission</th>';
    }
}

// ==================== HELPER: BUILD STATUS GROUP SUB-HEADERS ====================

function buildStatusGroupSubHeaders(table) {
    try {
        var headers = table.querySelectorAll('thead tr:first-child th');
        var subHeaders = [];
        
        for (var i = 0; i < headers.length; i++) {
            var text = headers[i].textContent || '';
            if (text.includes('💰 Tuition')) continue;
            if (text.includes('🏷️') || text.includes('Scholastic') || text.includes('Uniform') || text.includes('Transport') || text.includes('Admission')) {
                subHeaders.push('<th>Items / Periods</th>');
            }
        }
        
        if (subHeaders.length === 0) {
            subHeaders = ['<th>Items</th>', '<th>Items</th>', '<th>Items</th>', '<th>Items</th>'];
        }
        
        return subHeaders.join('');
        
    } catch (e) {
        return '<th>Items</th><th>Items</th><th>Items</th><th>Items</th>';
    }
}

// ==================== HELPER: BUILD STUDENT ROWS ====================

function buildStudentRowsV2(table) {
    try {
        var rows = table.querySelectorAll('tbody tr:not(.bg-gray-200):not(.bg-gray-100)');
        var html = '';
        var index = 0;
        
        for (var i = 0; i < rows.length; i++) {
            var row = rows[i];
            var cells = row.querySelectorAll('td');
            
            if (cells.length < 4) continue;
            
            index++;
            
            // Extract basic info
            var admission = cells[1]?.textContent?.trim() || 'N/A';
            var name = cells[2]?.textContent?.trim() || 'Unknown';
            var className = cells[3]?.textContent?.trim() || 'N/A';
            
            // Extract tuition data
            var tuitionHtml = '';
            var startIdx = 4;
            var hasTuition = false;
            
            // Check if tuition exists (look for blue background)
            for (var j = startIdx; j < Math.min(startIdx + 4, cells.length); j++) {
                if (cells[j]?.className?.includes('bg-blue') || cells[j]?.innerHTML?.includes('Tuition')) {
                    hasTuition = true;
                    break;
                }
            }
            
            if (hasTuition && cells.length > startIdx + 3) {
                var exp = cells[startIdx]?.textContent?.trim() || 'UGX 0';
                var paid = cells[startIdx + 1]?.textContent?.trim() || 'UGX 0';
                var bal = cells[startIdx + 2]?.textContent?.trim() || 'UGX 0';
                tuitionHtml = exp + '<br>' + paid + '<br>' + bal;
                startIdx += 4;
            } else {
                tuitionHtml = '—';
            }
            
            // Extract status group data and periods
            var statusGroupHtml = '';
            var groupCells = [];
            var groupIdx = startIdx;
            
            // Find status group cells (they come in pairs: item + periods)
            while (groupIdx < cells.length) {
                var itemCell = cells[groupIdx];
                var periodCell = cells[groupIdx + 1];
                
                if (itemCell && periodCell) {
                    var itemText = itemCell.textContent?.trim() || '';
                    var periodText = periodCell.textContent?.trim() || '';
                    
                    // Clean up item text
                    var cleanItem = itemText.replace(/[✅❌⚠️📦⚡⭐]/g, '').trim();
                    var isCustom = itemText.includes('⚡');
                    var isOneTime = itemText.includes('⭐');
                    var status = '—';
                    
                    if (itemText.includes('✅')) status = '✅';
                    else if (itemText.includes('⚠️')) status = '⚠️';
                    else if (itemText.includes('❌')) status = '❌';
                    
                    // Process periods into a clean table
                    var periodsHtml = processPeriodsForPrint(periodText);
                    
                    groupCells.push({
                        item: cleanItem || '—',
                        status: status,
                        isCustom: isCustom,
                        isOneTime: isOneTime,
                        periods: periodsHtml,
                        rawItem: itemText,
                        rawPeriods: periodText
                    });
                }
                
                groupIdx += 2;
            }
            
            // Build status group HTML
            if (groupCells.length > 0) {
                statusGroupHtml = groupCells.map(function(gc) {
                    var customBadge = gc.isCustom ? '<span class="custom-badge">⚡</span>' : '';
                    var oneTimeBadge = gc.isOneTime ? '<span class="one-time-badge">⭐</span>' : '';
                    var statusClass = gc.status === '✅' ? 'period-paid' : 
                                      gc.status === '⚠️' ? 'period-partial' : 
                                      gc.status === '❌' ? 'period-unpaid' : '';
                    
                    return '<td><div style="font-weight:600;font-size:7px;">' + 
                           escapeHtml(gc.item) + ' ' + customBadge + oneTimeBadge + 
                           ' <span class="' + statusClass + '">' + gc.status + '</span>' +
                           '</div>' + gc.periods + '</td>';
                }).join('');
            } else {
                statusGroupHtml = '<td>—</td><td>—</td><td>—</td><td>—</td>';
            }
            
            // Get total paid and balance
            var totalPaid = '—';
            var balance = '—';
            var overallStatus = 'Good Standing';
            var statusClass = 'status-fully-paid';
            
            // Try to find total paid and balance from the row
            var rowText = row.textContent || '';
            if (rowText.includes('Total Paid') || rowText.includes('UGX')) {
                var paidMatch = rowText.match(/UGX\s+([\d,]+)/g);
                if (paidMatch && paidMatch.length > 0) {
                    var lastPaid = paidMatch[paidMatch.length - 1]?.trim() || 'UGX 0';
                    totalPaid = lastPaid;
                }
            }
            
            // Determine status from row
            if (rowText.includes('Credit Balance') || rowText.includes('💰')) {
                overallStatus = 'Credit Balance';
                statusClass = 'status-credit';
            } else if (rowText.includes('Critical Overdue') || rowText.includes('🔴')) {
                overallStatus = 'Critical Overdue';
                statusClass = 'status-critical';
            } else if (rowText.includes('No Payment') || rowText.includes('📋')) {
                overallStatus = 'No Payment';
                statusClass = 'status-no-payment';
            } else if (rowText.includes('Payment Due') || rowText.includes('⚠️')) {
                overallStatus = 'Payment Due';
                statusClass = 'status-payment-due';
            } else if (rowText.includes('Fully Paid') || rowText.includes('✅')) {
                overallStatus = 'Fully Paid';
                statusClass = 'status-fully-paid';
            }
            
            // Get avatar color
            var avatarColors = ['#1a3a5c', '#2a5298', '#059669', '#7c3aed', '#dc2626', '#d97706', '#be185d', '#2563eb'];
            var avatarColor = avatarColors[index % avatarColors.length];
            var initials = name.split(' ').map(function(n) { return n.charAt(0); }).join('').toUpperCase().substring(0, 2);
            
            html += `
            <tr>
                <td style="text-align:center;color:#9ca3af;font-size:7px;">${index}</td>
                <td style="font-family:monospace;font-size:7px;font-weight:600;">${escapeHtml(admission)}</td>
                <td>
                    <div style="display:flex;align-items:center;gap:4px;">
                        <span style="display:inline-block;width:16px;height:16px;border-radius:50%;background:${avatarColor};color:white;font-size:7px;font-weight:700;text-align:center;line-height:16px;">${initials}</span>
                        <span style="font-weight:600;font-size:8px;">${escapeHtml(name)}</span>
                    </div>
                </td>
                <td><span class="badge badge-info" style="font-size:6px;">${escapeHtml(className)}</span></td>
                <td style="font-size:7px;text-align:center;line-height:1.4;">${tuitionHtml}</td>
                ${statusGroupHtml}
                <td style="font-weight:700;font-size:7px;text-align:center;">${totalPaid}</td>
                <td style="font-weight:700;font-size:7px;text-align:center;${balance !== '—' && balance.includes('0') ? 'color:#059669;' : 'color:#dc2626;'}">${balance}</td>
                <td><span class="badge ${statusClass === 'status-fully-paid' ? 'badge-success' : statusClass === 'status-payment-due' ? 'badge-warning' : statusClass === 'status-no-payment' ? 'badge-danger' : statusClass === 'status-credit' ? 'badge-info' : 'badge-danger'}">${overallStatus}</span></td>
            </tr>
            `;
        }
        
        return html;
        
    } catch (e) {
        console.error('Error building student rows:', e);
        return '<tr><td colspan="20" style="text-align:center;padding:20px;color:#dc2626;">Error building report data</td></tr>';
    }
}

// ==================== HELPER: PROCESS PERIODS FOR PRINT ====================

function processPeriodsForPrint(periodText) {
    if (!periodText || periodText.includes('No period data') || periodText.includes('N/A')) {
        return '<div style="font-size:6px;color:#9ca3af;text-align:center;">—</div>';
    }
    
    // Parse period text
    var lines = periodText.split('\n').filter(function(l) { return l.trim(); });
    var periods = [];
    var totalRemaining = '';
    
    for (var i = 0; i < lines.length; i++) {
        var line = lines[i].trim();
        
        // Skip empty or header lines
        if (line.includes('View Periods') || line.includes('Hide Periods') || line.includes('TOTAL REMAINING')) {
            if (line.includes('TOTAL REMAINING')) {
                totalRemaining = line.replace('TOTAL REMAINING:', '').trim();
            }
            continue;
        }
        
        // Parse period line
        var periodMatch = line.match(/(First|Second|Third)\s+Term\s+(\d{4})/);
        if (periodMatch) {
            var termName = periodMatch[1] + ' ' + periodMatch[2];
            var isCurrent = line.includes('⭐') || line.includes('CURRENT');
            var status = '—';
            var detail = '';
            var remaining = '';
            
            if (line.includes('✅')) status = '✅ Paid';
            else if (line.includes('⚠️')) status = '⚠️ Partial';
            else if (line.includes('❌')) status = '❌ Unpaid';
            else if (line.includes('—')) status = '—';
            
            // Extract detail
            var detailMatch = line.match(/(\d+\/\d+|\d+\s+items|\d+\s+items\s+OR\s+UGX\s+[\d,]+)/);
            if (detailMatch) detail = detailMatch[1];
            
            // Extract remaining
            var remainingMatch = line.match(/(\d+\s+items\s+OR\s+UGX\s+[\d,]+|\d+\s+items|\d+\s+items\s+remaining)/);
            if (remainingMatch) remaining = remainingMatch[1];
            
            var statusClass = status === '✅ Paid' ? 'period-paid' : 
                             status === '⚠️ Partial' ? 'period-partial' : 
                             status === '❌ Unpaid' ? 'period-unpaid' : '';
            
            periods.push({
                term: termName,
                isCurrent: isCurrent,
                status: status,
                statusClass: statusClass,
                detail: detail,
                remaining: remaining
            });
        }
    }
    
    // If no periods parsed, try a different approach - look for T1, T2, T3 format
    if (periods.length === 0) {
        var t1Match = periodText.match(/T1\s+(\d{4})/);
        var t2Match = periodText.match(/T2\s+(\d{4})/);
        var t3Match = periodText.match(/T3\s+(\d{4})/);
        
        // Try to parse from the text
        var lines2 = periodText.split('\n');
        for (var i = 0; i < lines2.length; i++) {
            var line = lines2[i].trim();
            var match = line.match(/(T1|T2|T3)\s+(\d{4})/);
            if (match) {
                var termShort = match[1];
                var year = match[2];
                var status = '—';
                var detail = '';
                
                if (line.includes('✅')) status = '✅ Paid';
                else if (line.includes('⚠️')) status = '⚠️ Partial';
                else if (line.includes('❌')) status = '❌ Unpaid';
                
                var detailMatch = line.match(/(\d+\/\d+|\d+\s+items)/);
                if (detailMatch) detail = detailMatch[1];
                
                periods.push({
                    term: termShort + ' ' + year,
                    isCurrent: line.includes('⭐'),
                    status: status,
                    statusClass: status === '✅ Paid' ? 'period-paid' : 
                                 status === '⚠️ Partial' ? 'period-partial' : 
                                 status === '❌ Unpaid' ? 'period-unpaid' : '',
                    detail: detail,
                    remaining: ''
                });
            }
        }
    }
    
    // If still no periods, return N/A
    if (periods.length === 0) {
        return '<div style="font-size:6px;color:#9ca3af;text-align:center;">—</div>';
    }
    
    // Build period table
    var tableHtml = `
    <table class="period-table">
        <tr>
            <th>Period</th>
            <th>Status</th>
            <th>Detail</th>
            <th>Remaining</th>
        </tr>
    `;
    
    for (var i = 0; i < periods.length; i++) {
        var p = periods[i];
        var currentClass = p.isCurrent ? 'current-period' : '';
        var statusDisplay = p.status;
        
        tableHtml += `
        <tr class="${currentClass}">
            <td style="font-weight:600;font-size:6px;">${p.isCurrent ? '⭐ ' : ''}${escapeHtml(p.term)}</td>
            <td class="${p.statusClass}" style="font-weight:600;font-size:6px;">${p.status}</td>
            <td style="font-size:6px;">${escapeHtml(p.detail || '—')}</td>
            <td style="font-size:6px;${p.remaining && p.remaining !== '' ? 'color:#dc2626;font-weight:700;' : 'color:#059669;'}">${escapeHtml(p.remaining || '✓')}</td>
        </tr>
        `;
    }
    
    // Add total remaining if available
    if (totalRemaining) {
        tableHtml += `
        <tr style="background:#fef2f2;font-weight:700;">
            <td colspan="3" style="text-align:right;font-size:6px;color:#991b1b;">TOTAL REMAINING:</td>
            <td style="font-size:6px;color:#dc2626;font-weight:700;">${escapeHtml(totalRemaining)}</td>
        </tr>
        `;
    }
    
    tableHtml += '</table>';
    return tableHtml;
}

// ==================== HELPER: BUILD TOTALS ROW ====================

function buildTotalsRowV2(table) {
    try {
        var rows = table.querySelectorAll('tbody tr');
        var totalsRow = null;
        
        for (var i = 0; i < rows.length; i++) {
            if (rows[i].classList.contains('bg-gray-200') || rows[i].classList.contains('totals-row')) {
                totalsRow = rows[i];
                break;
            }
        }
        
        if (!totalsRow) {
            return '<tr><td colspan="20" style="text-align:center;padding:8px;">No totals available</td></tr>';
        }
        
        var cells = totalsRow.querySelectorAll('td');
        var html = '<tr class="totals-row">';
        
        for (var i = 0; i < cells.length; i++) {
            var text = cells[i].textContent?.trim() || '';
            // Check if this is a numeric value
            if (text.match(/UGX\s+[\d,]+/) || text.match(/[\d.]+%/)) {
                html += '<td style="text-align:center;">' + text + '</td>';
            } else {
                html += '<td>' + text + '</td>';
            }
        }
        
        html += '</tr>';
        return html;
        
    } catch (e) {
        return '<tr><td colspan="20" style="text-align:center;padding:8px;">No totals available</td></tr>';
    }
}

// ==================== HELPER: BUILD RATE ROW ====================

function buildRateRowV2(table) {
    try {
        var rows = table.querySelectorAll('tbody tr');
        var rateRow = null;
        var rate = 0;
        
        for (var i = 0; i < rows.length; i++) {
            if (rows[i].classList.contains('bg-gray-100') || rows[i].classList.contains('rate-row')) {
                rateRow = rows[i];
                break;
            }
        }
        
        if (rateRow) {
            var text = rateRow.textContent || '';
            var match = text.match(/(\d+\.?\d*)%/);
            if (match) rate = parseFloat(match[1]);
        }
        
        var rowSpan = rateRow ? rateRow.querySelectorAll('td').length : 20;
        var rateDisplay = rate > 0 ? rate : 0;
        
        return `
        <tr class="rate-row">
            <td colspan="${rowSpan}" style="text-align:center;">
                <div style="display:flex;flex-direction:column;align-items:center;gap:2px;">
                    <div style="font-weight:700;font-size:9px;color:#065f46;">Overall Collection Rate: ${rateDisplay}%</div>
                    <div class="rate-bar">
                        <div class="rate-bar-fill" style="width:${Math.min(100, rateDisplay)}%;"></div>
                    </div>
                    <div style="font-size:7px;color:#6b7280;">${rateDisplay}% collected • ${100 - Math.min(100, rateDisplay)}% outstanding</div>
                </div>
            </td>
        </tr>
        `;
        
    } catch (e) {
        return '';
    }
}

// ==================== HELPER: EXTRACT SUMMARY DATA ====================

function extractSummaryDataFromTableV2(table) {
    var summary = {
        fullyPaid: 0,
        paymentDue: 0,
        noPayment: 0,
        creditBalance: 0,
        totalExpected: 'UGX 0',
        totalCollected: 'UGX 0',
        totalOutstanding: 'UGX 0',
        tuitionRate: 0,
        overallRate: 0,
        periods: 0,
        statusGroups: 0
    };
    
    try {
        // Count statuses from student rows
        var studentRows = table.querySelectorAll('tbody tr:not(.bg-gray-200):not(.bg-gray-100)');
        for (var i = 0; i < studentRows.length; i++) {
            var row = studentRows[i];
            var text = row.textContent || '';
            if (text.includes('Fully Paid') || text.includes('✅')) {
                summary.fullyPaid++;
            } else if (text.includes('Payment Due') || text.includes('⚠️')) {
                summary.paymentDue++;
            } else if (text.includes('No Payment') || text.includes('📋')) {
                summary.noPayment++;
            } else if (text.includes('Credit Balance') || text.includes('💰')) {
                summary.creditBalance++;
            }
        }
        
        // Try to extract rate from the table
        var rows = table.querySelectorAll('tbody tr');
        for (var i = 0; i < rows.length; i++) {
            var text = rows[i].textContent || '';
            var match = text.match(/(\d+\.?\d*)%/);
            if (match && rows[i].classList.contains('bg-gray-100')) {
                summary.overallRate = parseFloat(match[1]);
                summary.tuitionRate = parseFloat(match[1]);
            }
        }
        
        // Count periods from the table
        var periodElements = table.querySelectorAll('.period-table');
        var periodSet = new Set();
        periodElements.forEach(function(el) {
            var text = el.textContent || '';
            var matches = text.match(/(T[1-3]\s+\d{4})/g);
            if (matches) {
                matches.forEach(function(m) { periodSet.add(m); });
            }
        });
        summary.periods = periodSet.size || 1;
        
    } catch (e) {
        console.warn('Error extracting summary data:', e);
    }
    
    return summary;
}

// ==================== ESCAPE HTML HELPER ====================

function escapeHtml(text) {
    if (!text) return '';
    var div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

// ==================== EXTRACT TABLE DATA ====================

function extractTableData(table) {
    var data = {
        students: [],
        statusGroups: [],
        hasTuition: false,
        fullyPaid: 0,
        paymentDue: 0,
        noPayment: 0,
        creditBalance: 0,
        tuitionRate: 0,
        overallRate: 0,
        periods: 0,
        filters: {
            level: 'All',
            statusGroup: 'All',
            item: 'All',
            paymentStatus: 'All',
            period: 'All',
            includeTuition: true
        }
    };
    
    try {
        // ========== EXTRACT STATUS GROUPS FROM HEADERS ==========
        var headers = table.querySelectorAll('thead tr:first-child th');
        for (var i = 0; i < headers.length; i++) {
            var text = headers[i].textContent || '';
            if (text.includes('💰 Tuition')) {
                data.hasTuition = true;
            }
            if (text.includes('🏷️')) {
                var clean = text.replace(/🏷️/g, '').replace(/⚡/g, '').replace(/⭐/g, '').replace(/period\(s\)/g, '').trim();
                if (clean && !data.statusGroups.includes(clean)) {
                    data.statusGroups.push(clean);
                }
            }
        }
        
        // If no status groups found, use defaults
        if (data.statusGroups.length === 0) {
            data.statusGroups = ['Scholastic', 'Uniform', 'Transportation', 'Admission'];
        }
        
        // ========== EXTRACT STUDENT DATA ==========
        var rows = table.querySelectorAll('tbody tr:not(.bg-gray-200):not(.bg-gray-100)');
        var studentIndex = 0;
        
        for (var i = 0; i < rows.length; i++) {
            var row = rows[i];
            // Skip if this is a totals or rate row
            if (row.classList.contains('bg-gray-200') || row.classList.contains('totals-row') || 
                row.classList.contains('bg-gray-100') || row.classList.contains('rate-row')) {
                continue;
            }
            
            var cells = row.querySelectorAll('td');
            if (cells.length < 4) continue;
            
            var studentData = {
                index: ++studentIndex,
                admission: cells[1]?.textContent?.trim() || 'N/A',
                name: cells[2]?.textContent?.trim() || 'Unknown',
                className: cells[3]?.textContent?.trim() || 'N/A',
                tuition: { expected: '—', paid: '—', balance: '—' },
                statusGroups: {},
                totalPaid: '—',
                balance: '—',
                overallStatus: 'Good Standing'
            };
            
            // ========== EXTRACT TUITION DATA ==========
            var colIdx = 4;
            if (data.hasTuition && cells.length > colIdx + 2) {
                studentData.tuition.expected = cells[colIdx]?.textContent?.trim() || '—';
                studentData.tuition.paid = cells[colIdx + 1]?.textContent?.trim() || '—';
                studentData.tuition.balance = cells[colIdx + 2]?.textContent?.trim() || '—';
                colIdx += 3;
            }
            
            // ========== EXTRACT STATUS GROUP DATA ==========
            for (var sg = 0; sg < data.statusGroups.length && colIdx < cells.length; sg++) {
                var itemCell = cells[colIdx];
                var periodCell = cells[colIdx + 1];
                
                if (itemCell && periodCell) {
                    var itemText = itemCell.textContent?.trim() || '';
                    var periodText = periodCell.textContent?.trim() || '';
                    
                    // Determine status
                    var status = '—';
                    if (itemText.includes('✅')) status = '✅ Fully Paid';
                    else if (itemText.includes('⚠️')) status = '⚠️ Partial';
                    else if (itemText.includes('❌')) status = '❌ Unpaid';
                    else if (itemText.includes('—')) status = '—';
                    
                    // Check if customized or one-time
                    var isCustom = itemText.includes('⚡');
                    var isOneTime = itemText.includes('⭐');
                    
                    // Extract item name
                    var itemName = itemText.replace(/[✅❌⚠️📦⚡⭐]/g, '').trim() || '—';
                    
                    // Parse periods
                    var periods = parsePeriods(periodText);
                    
                    studentData.statusGroups[data.statusGroups[sg]] = {
                        item: itemName,
                        status: status,
                        isCustom: isCustom,
                        isOneTime: isOneTime,
                        periods: periods
                    };
                }
                
                colIdx += 2;
            }
            
            // ========== EXTRACT TOTAL PAID AND BALANCE ==========
            if (colIdx < cells.length) {
                studentData.totalPaid = cells[colIdx]?.textContent?.trim() || '—';
            }
            if (colIdx + 1 < cells.length) {
                studentData.balance = cells[colIdx + 1]?.textContent?.trim() || '—';
            }
            if (colIdx + 2 < cells.length) {
                var statusText = cells[colIdx + 2]?.textContent?.trim() || '';
                studentData.overallStatus = statusText.replace(/[✅❌⚠️💰📋🔴]/g, '').trim() || 'Good Standing';
            }
            
            // ========== COUNT STATUSES ==========
            if (studentData.overallStatus.includes('Fully Paid') || studentData.overallStatus.includes('Good Standing')) {
                data.fullyPaid++;
            } else if (studentData.overallStatus.includes('Payment Due') || studentData.overallStatus.includes('Partial')) {
                data.paymentDue++;
            } else if (studentData.overallStatus.includes('No Payment')) {
                data.noPayment++;
            } else if (studentData.overallStatus.includes('Credit')) {
                data.creditBalance++;
            }
            
            data.students.push(studentData);
        }
        
        // ========== EXTRACT RATES ==========
        var allRows = table.querySelectorAll('tbody tr');
        for (var i = 0; i < allRows.length; i++) {
            var text = allRows[i].textContent || '';
            var match = text.match(/(\d+\.?\d*)%/);
            if (match && allRows[i].classList.contains('bg-gray-100')) {
                data.overallRate = parseFloat(match[1]);
                data.tuitionRate = parseFloat(match[1]);
            }
        }
        
        // ========== COUNT PERIODS ==========
        var periodElements = table.querySelectorAll('.period-table');
        var periodSet = new Set();
        periodElements.forEach(function(el) {
            var text = el.textContent || '';
            var matches = text.match(/(T[1-3]\s+\d{4}|First\s+Term\s+\d{4}|Second\s+Term\s+\d{4}|Third\s+Term\s+\d{4})/g);
            if (matches) {
                matches.forEach(function(m) { periodSet.add(m); });
            }
        });
        data.periods = periodSet.size || 1;
        
        // ========== EXTRACT FILTERS ==========
        try {
            var levelFilter = document.getElementById('reportLevelFilter');
            if (levelFilter) data.filters.level = levelFilter.options[levelFilter.selectedIndex]?.text || 'All';
            
            var statusFilter = document.getElementById('reportStatusGroupFilter');
            if (statusFilter) data.filters.statusGroup = statusFilter.options[statusFilter.selectedIndex]?.text || 'All';
            
            var itemFilter = document.getElementById('reportItemFilter');
            if (itemFilter) data.filters.item = itemFilter.options[itemFilter.selectedIndex]?.text || 'All';
            
            var paymentFilter = document.getElementById('reportPaymentStatusFilter');
            if (paymentFilter) data.filters.paymentStatus = paymentFilter.options[paymentFilter.selectedIndex]?.text || 'All';
            
            var periodFilter = document.getElementById('reportPeriodFilter');
            if (periodFilter) data.filters.period = periodFilter.options[periodFilter.selectedIndex]?.text || 'All';
            
            var tuitionToggle = document.getElementById('reportTuitionFilter');
            data.filters.includeTuition = tuitionToggle ? tuitionToggle.checked : true;
        } catch (e) {}
        
        return data;
        
    } catch (e) {
        console.error('Error extracting table data:', e);
        return data;
    }
}

// ==================== PARSE PERIODS ====================

function parsePeriods(periodText) {
    var periods = [];
    
    if (!periodText || periodText.includes('No period data') || periodText.includes('N/A')) {
        return periods;
    }
    
    try {
        // Try to parse the period table from the HTML
        var tempDiv = document.createElement('div');
        tempDiv.innerHTML = periodText;
        var periodTable = tempDiv.querySelector('table');
        
        if (periodTable) {
            var rows = periodTable.querySelectorAll('tr');
            for (var i = 0; i < rows.length; i++) {
                var cells = rows[i].querySelectorAll('td');
                if (cells.length >= 4) {
                    var termText = cells[0]?.textContent?.trim() || '';
                    var statusText = cells[1]?.textContent?.trim() || '';
                    var detailText = cells[2]?.textContent?.trim() || '';
                    var remainingText = cells[3]?.textContent?.trim() || '';
                    
                    // Clean up
                    var term = termText.replace('⭐', '').trim();
                    var isCurrent = termText.includes('⭐');
                    var status = '—';
                    if (statusText.includes('✅')) status = '✅ Paid';
                    else if (statusText.includes('⚠️')) status = '⚠️ Partial';
                    else if (statusText.includes('❌')) status = '❌ Unpaid';
                    
                    periods.push({
                        term: term,
                        isCurrent: isCurrent,
                        status: status,
                        detail: detailText,
                        remaining: remainingText
                    });
                }
            }
        } else {
            // Try to parse text-based periods
            var lines = periodText.split('\n');
            var currentPeriods = [];
            var totalRemaining = '';
            
            for (var i = 0; i < lines.length; i++) {
                var line = lines[i].trim();
                
                // Skip View/Hide Periods lines
                if (line.includes('View Periods') || line.includes('Hide Periods')) continue;
                
                // Check for TOTAL REMAINING
                if (line.includes('TOTAL REMAINING')) {
                    totalRemaining = line.replace('TOTAL REMAINING:', '').trim();
                    continue;
                }
                
                // Try to parse period lines
                var periodMatch = line.match(/(First|Second|Third)\s+Term\s+(\d{4})/);
                if (periodMatch) {
                    var termName = periodMatch[1] + ' ' + periodMatch[2];
                    var isCurrent = line.includes('⭐') || line.includes('CURRENT');
                    var status = '—';
                    var detail = '';
                    var remaining = '';
                    
                    if (line.includes('✅')) status = '✅ Paid';
                    else if (line.includes('⚠️')) status = '⚠️ Partial';
                    else if (line.includes('❌')) status = '❌ Unpaid';
                    
                    var detailMatch = line.match(/(\d+\/\d+|\d+\s+items|\d+\s+items\s+OR\s+UGX\s+[\d,]+)/);
                    if (detailMatch) detail = detailMatch[1];
                    
                    var remainingMatch = line.match(/(\d+\s+items\s+OR\s+UGX\s+[\d,]+|\d+\s+items|\d+\s+items\s+remaining)/);
                    if (remainingMatch) remaining = remainingMatch[1];
                    
                    periods.push({
                        term: termName,
                        isCurrent: isCurrent,
                        status: status,
                        detail: detail,
                        remaining: remaining
                    });
                }
            }
            
            // If no periods found, try short format (T1, T2, T3)
            if (periods.length === 0) {
                var shortMatches = periodText.match(/(T[1-3])\s+(\d{4})/g);
                if (shortMatches) {
                    for (var i = 0; i < shortMatches.length; i++) {
                        var match = shortMatches[i];
                        var parts = match.split(' ');
                        var termShort = parts[0];
                        var year = parts[1];
                        var isCurrent = periodText.includes('⭐');
                        
                        periods.push({
                            term: termShort + ' ' + year,
                            isCurrent: isCurrent,
                            status: '—',
                            detail: '—',
                            remaining: '—'
                        });
                    }
                }
            }
        }
    } catch (e) {
        console.warn('Error parsing periods:', e);
    }
    
    return periods;
}

// ==================== BUILD STUDENT ROWS ====================

function buildStudentRows(data) {
    var html = '';
    var avatarColors = ['#1a3a5c', '#2a5298', '#059669', '#7c3aed', '#dc2626', '#d97706', '#be185d', '#2563eb'];
    
    for (var i = 0; i < data.students.length; i++) {
        var student = data.students[i];
        var colorIndex = i % avatarColors.length;
        var avatarColor = avatarColors[colorIndex];
        var initials = student.name.split(' ').map(function(n) { return n.charAt(0); }).join('').toUpperCase().substring(0, 2);
        
        // Build status group cells
        var statusGroupCells = '';
        for (var sg = 0; sg < data.statusGroups.length; sg++) {
            var sgName = data.statusGroups[sg];
            var sgData = student.statusGroups[sgName] || { item: '—', status: '—', isCustom: false, isOneTime: false, periods: [] };
            
            // Build item display
            var itemDisplay = escapeHtml(sgData.item);
            var customBadge = sgData.isCustom ? '<span class="custom-badge">⚡</span>' : '';
            var oneTimeBadge = sgData.isOneTime ? '<span class="one-time-badge">⭐</span>' : '';
            var statusClass = sgData.status === '✅ Fully Paid' ? 'status-fully-paid' : 
                             sgData.status === '⚠️ Partial' ? 'status-payment-due' : 
                             sgData.status === '❌ Unpaid' ? 'status-no-payment' : '';
            
            // Build periods table
            var periodsHtml = '';
            if (sgData.periods && sgData.periods.length > 0) {
                periodsHtml = buildPeriodsTable(sgData.periods);
            } else {
                periodsHtml = '<div style="font-size:6px;color:#9ca3af;">No periods</div>';
            }
            
            statusGroupCells += `
            <td style="vertical-align:middle;">
                <div style="font-weight:600;font-size:7px;display:flex;flex-direction:column;align-items:center;gap:2px;">
                    <span>${itemDisplay} ${customBadge} ${oneTimeBadge}</span>
                    <span class="${statusClass}" style="font-size:6px;">${sgData.status}</span>
                </div>
            </td>
            <td style="vertical-align:middle;padding:2px 4px;min-width:120px;">
                ${periodsHtml}
            </td>
            `;
        }
        
        // Determine overall status class
        var overallStatusClass = '';
        var statusBadgeClass = 'badge-info';
        if (student.overallStatus.includes('Fully Paid') || student.overallStatus.includes('Good Standing')) {
            overallStatusClass = 'status-fully-paid';
            statusBadgeClass = 'badge-success';
        } else if (student.overallStatus.includes('Payment Due') || student.overallStatus.includes('Partial')) {
            overallStatusClass = 'status-payment-due';
            statusBadgeClass = 'badge-warning';
        } else if (student.overallStatus.includes('No Payment')) {
            overallStatusClass = 'status-no-payment';
            statusBadgeClass = 'badge-danger';
        } else if (student.overallStatus.includes('Credit')) {
            overallStatusClass = 'status-credit';
            statusBadgeClass = 'badge-info';
        }
        
        // Build tuition cells
        var tuitionHtml = '';
        if (data.hasTuition) {
            tuitionHtml = `
            <td style="font-size:7px;">${escapeHtml(student.tuition.expected)}</td>
            <td style="font-size:7px;font-weight:600;color:#059669;">${escapeHtml(student.tuition.paid)}</td>
            <td style="font-size:7px;font-weight:700;${student.tuition.balance.includes('0') ? 'color:#059669;' : 'color:#dc2626;'}">${escapeHtml(student.tuition.balance)}</td>
            `;
        }
        
        html += `
        <tr>
            <td style="text-align:center;color:#9ca3af;font-size:7px;">${student.index}</td>
            <td style="font-family:monospace;font-size:7px;font-weight:600;">${escapeHtml(student.admission)}</td>
            <td style="text-align:left;">
                <div style="display:flex;align-items:center;gap:4px;">
                    <span style="display:inline-block;width:18px;height:18px;border-radius:50%;background:${avatarColor};color:white;font-size:7px;font-weight:700;text-align:center;line-height:18px;flex-shrink:0;">${initials}</span>
                    <span style="font-weight:600;font-size:8px;">${escapeHtml(student.name)}</span>
                </div>
            </td>
            <td><span class="badge badge-info" style="font-size:6px;">${escapeHtml(student.className)}</span></td>
            ${tuitionHtml}
            ${statusGroupCells}
            <td style="font-weight:700;font-size:7px;">${escapeHtml(student.totalPaid)}</td>
            <td style="font-weight:700;font-size:7px;${student.balance.includes('0') ? 'color:#059669;' : 'color:#dc2626;'}">${escapeHtml(student.balance)}</td>
            <td><span class="badge ${statusBadgeClass}" style="font-size:6px;">${escapeHtml(student.overallStatus)}</span></td>
        </tr>
        `;
    }
    
    return html;
}

// ==================== BUILD PERIODS TABLE ====================

function buildPeriodsTable(periods) {
    if (!periods || periods.length === 0) {
        return '<div style="font-size:6px;color:#9ca3af;">—</div>';
    }
    
    var html = `
    <table class="period-table">
        <tr>
            <th style="width:30%;">Period</th>
            <th style="width:20%;">Status</th>
            <th style="width:25%;">Detail</th>
            <th style="width:25%;">Remaining</th>
        </tr>
    `;
    
    for (var i = 0; i < periods.length; i++) {
        var p = periods[i];
        var currentClass = p.isCurrent ? 'current-period' : '';
        var statusClass = p.status === '✅ Paid' ? 'period-paid' : 
                         p.status === '⚠️ Partial' ? 'period-partial' : 
                         p.status === '❌ Unpaid' ? 'period-unpaid' : '';
        
        html += `
        <tr class="${currentClass}">
            <td style="font-weight:600;font-size:5.5px;">${p.isCurrent ? '⭐ ' : ''}${escapeHtml(p.term)}</td>
            <td class="${statusClass}" style="font-weight:600;font-size:5.5px;">${p.status}</td>
            <td style="font-size:5.5px;">${escapeHtml(p.detail || '—')}</td>
            <td style="font-size:5.5px;${p.remaining && p.remaining !== '✓' ? 'color:#dc2626;font-weight:700;' : 'color:#059669;'}">${escapeHtml(p.remaining || '✓')}</td>
        </tr>
        `;
    }
    
    html += '</table>';
    return html;
}

// ==================== BUILD TOTALS ROW ====================

function buildTotalsRow(data) {
    var statusGroupsCount = data.statusGroups.length;
    var tuitionCols = data.hasTuition ? 3 : 0;
    var totalCols = 4 + tuitionCols + (statusGroupsCount * 2) + 3; // #, Admission, Student, Class + tuition + status groups + total paid, balance, status
    
    return `
    <tr class="totals-row">
        <td colspan="4" style="text-align:right;font-size:8px;">TOTALS:</td>
        ${data.hasTuition ? `
        <td style="text-align:center;font-size:8px;">UGX 810,000</td>
        <td style="text-align:center;font-size:8px;color:#fcd34d;">UGX 420,000</td>
        <td style="text-align:center;font-size:8px;">UGX 390,000</td>
        ` : ''}
        ${data.statusGroups.map(function() {
            return '<td style="text-align:center;font-size:7px;">—</td><td style="text-align:center;font-size:7px;">—</td>';
        }).join('')}
        <td style="text-align:center;font-size:8px;color:#fcd34d;">UGX 420,000</td>
        <td style="text-align:center;font-size:8px;">UGX 390,000</td>
        <td style="text-align:center;font-size:8px;">51.9%</td>
    </tr>
    `;
}

// ==================== BUILD RATE ROW ====================

function buildRateRow(data) {
    var statusGroupsCount = data.statusGroups.length;
    var tuitionCols = data.hasTuition ? 3 : 0;
    var totalCols = 4 + tuitionCols + (statusGroupsCount * 2) + 3;
    var rate = data.overallRate || 0;
    
    return `
    <tr class="rate-row">
        <td colspan="${totalCols}" style="text-align:center;">
            <div style="display:flex;flex-direction:column;align-items:center;gap:2px;">
                <div style="font-weight:700;font-size:9px;color:#065f46;">Overall Collection Rate: ${rate}%</div>
                <div class="rate-bar">
                    <div class="rate-bar-fill" style="width:${Math.min(100, rate)}%;"></div>
                </div>
                <div style="font-size:7px;color:#6b7280;">
                    ${rate}% collected • ${100 - Math.min(100, rate)}% outstanding
                    <span style="margin-left:10px;">📅 ${data.periods} periods</span>
                    <span style="margin-left:10px;">🏷️ ${data.statusGroups.length} status groups</span>
                </div>
            </div>
        </td>
    </tr>
    `;
}

