async function saveTransactionEditV7(transactionId) {
    var quantity = parseInt(document.getElementById('editQuantity').value) || 0;
    var destination = document.getElementById('editDestination').value;
    var recipient = document.getElementById('editRecipient').value.trim();
    var comment = document.getElementById('editComment').value.trim();

    if (quantity <= 0) { alert('Please enter a valid quantity'); return; }
    if (!recipient) { alert('Please enter a recipient name'); return; }

    var submitBtn = document.querySelector('#editTransactionForm button[type="submit"]');
    var originalText = submitBtn.innerHTML;
    submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving...';
    submitBtn.disabled = true;

    try {
        var response = await fetch('/api/inventory/transaction/' + transactionId, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ quantity: quantity, destination: destination, recipient: recipient, comment: comment })
        });

        var result = await response.json();

        if (result.success) {
            showToast('✅ Transaction updated successfully', 'success');
            closeModal();
            refreshInventoryV7();
        } else {
            showToast('❌ Error: ' + (result.error || 'Unknown error'), 'error');
        }
    } catch (error) {
        console.error('Error updating transaction:', error);
        showToast('Network error: ' + error.message, 'error');
    } finally {
        submitBtn.innerHTML = originalText;
        submitBtn.disabled = false;
    }
}

// ========== REVERSE TRANSACTION ==========
function reverseTransaction(transactionId) {
    var transaction = inventoryTransactionsGlobal.find(function (t) { return t.id === transactionId; });
    if (!transaction) { alert('Transaction not found'); return; }
    if (transaction.reversed) { alert('Transaction already reversed'); return; }

    var confirmMsg = '↩️ Reverse Transaction\n\n' +
        'Item: ' + transaction.itemName + '\n' +
        'Quantity: ' + transaction.quantity + '\n' +
        'Destination: ' + transaction.destination + '\n' +
        'Recipient: ' + transaction.recipient + '\n\n' +
        'This will return ' + transaction.quantity + ' ' + transaction.itemName + '(s) to stock.\n\n' +
        'Are you sure you want to reverse this transaction?';

    if (!confirm(confirmMsg)) return;

    var reason = prompt('Reason for reversal (optional):');

    fetch('/api/inventory/reverse/' + transactionId, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reason: reason || 'Transaction reversed' })
    })
        .then(function (res) { return res.json(); })
        .then(function (result) {
            if (result.success) { showToast('✅ Transaction reversed successfully', 'success'); refreshInventoryV7(); }
            else showToast('❌ Error: ' + (result.error || 'Unknown error'), 'error');
        })
        .catch(function (error) { console.error('Error reversing transaction:', error); showToast('Network error: ' + error.message, 'error'); });
}

