// Close the customization modal
function closeItemCustomizationModal() {
    const modal = document.getElementById('itemCustomizationModal');
    if (modal) modal.remove();
    window.currentCustomizationContext = null;
}

// Save customization
async function saveItemCustomization(studentId, itemId, componentId, periodType) {
    console.log('Saving customization for:', { studentId, itemId });
    
    const amount = document.getElementById('customizeAmount').value;
    const quantity = document.getElementById('customizeQuantity')?.value;
    const paymentOption = document.getElementById('customizePaymentOption').value;
    const reason = document.getElementById('customizeReason').value;
    
    // Validate: At least one custom value should be provided
    if (!amount && !quantity && !reason) {
        showToast('Please enter at least a custom amount or reason', 'warning');
        return;
    }
    
    const data = {
        componentId: componentId,
        customAmount: amount && amount !== '' ? parseFloat(amount) : null,
        customQuantity: quantity && quantity !== '' ? parseInt(quantity) : null,
        paymentOption: paymentOption || null,
        reason: reason || 'Customized by bursar'
    };
    
    // Show loading
    const saveBtn = document.querySelector('#itemCustomizationModal button:first-child');
    const originalText = saveBtn.innerHTML;
    saveBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving...';
    saveBtn.disabled = true;
    
    try {
        const response = await fetch(`/api/students/${studentId}/customizations/${itemId}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(data)
        });
        
        if (response.ok) {
            const result = await response.json();
            showToast('✅ Item customization saved successfully!', 'success');
            closeItemCustomizationModal();
            
            // Clear cached data
            window.allStudentsData = null;
            window.enhancedStudentsData = null;
            
            // Refresh the current view
            refreshCurrentViewAfterCustomization();
        } else {
            const error = await response.json();
            showToast('❌ Error saving customization: ' + (error.error || 'Unknown error'), 'error');
        }
    } catch (error) {
        console.error('Error saving customization:', error);
        showToast('Network error: ' + error.message, 'error');
    } finally {
        saveBtn.innerHTML = originalText;
        saveBtn.disabled = false;
    }
}

// Remove customization (revert to default)
async function removeItemCustomization(studentId, itemId) {
    if (!confirm('⚠️ Remove customization for this item?\n\nThis will revert to the default fee structure amount for this student.')) {
        return;
    }
    
    try {
        const response = await fetch(`/api/students/${studentId}/customizations/${itemId}`, {
            method: 'DELETE'
        });
        
        if (response.ok) {
            showToast('✅ Customization removed. Item will use default values.', 'success');
            closeItemCustomizationModal();
            
            window.allStudentsData = null;
            window.enhancedStudentsData = null;
            refreshCurrentViewAfterCustomization();
        } else {
            const error = await response.json();
            showToast('❌ Error removing customization: ' + (error.error || 'Unknown error'), 'error');
        }
    } catch (error) {
        console.error('Error removing customization:', error);
        showToast('Network error: ' + error.message, 'error');
    }
}

// Refresh current view after customization
function refreshCurrentViewAfterCustomization() {
    const pageTitle = document.getElementById('pageTitle')?.innerText || '';
    console.log('Refreshing view after customization:', pageTitle);
    
    // Check which page we're on and refresh accordingly
    if (pageTitle.includes('All Students') || pageTitle.includes('Students')) {
        showStudentList();
    } else if (pageTitle.includes('Fee Management')) {
        showFeeManagement();
    } else if (pageTitle.includes('Dashboard')) {
        showDashboard();
    } else if (pageTitle.includes('Student Profile')) {
        // If in a student detail view, reload the student
        const currentStudentId = window.currentViewingStudentId;
        if (currentStudentId) {
            viewStudentDetailsList(currentStudentId);
        } else {
            showStudentList();
        }
    } else {
        // Default: refresh fee management
        showFeeManagement();
    }
}

// ==================== HELPER: GET CUSTOMIZED ITEM VALUE ====================

// ==================== COMPLETE REBUILT COMPREHENSIVE REPORT ====================
// Version: 6.0 - Respects Customizations (customItemOverrides)

// ========== HELPER: GET CUSTOMIZED ITEM VALUE ==========
function getCustomizedItemValueForReport(student, itemId, itemName, defaultAmount, defaultQuantity, defaultPaymentOption, defaultUnitPrice) {
    // Guard against null/undefined
    if (!student) {
        return {
            amount: defaultAmount || 0,
            quantity: defaultQuantity || 1,
            paymentOption: defaultPaymentOption || 'either',
            unitPrice: defaultUnitPrice || (defaultAmount / (defaultQuantity || 1)),
            isCustomized: false,
            reason: null,
            updatedAt: null,
            customAmount: null,
            customQuantity: null,
            defaultAmount: defaultAmount || 0,
            defaultQuantity: defaultQuantity || 1
        };
    }
    
    // Check if student has custom overrides for this item
    if (student.customItemOverrides && student.customItemOverrides[itemId]) {
        const custom = student.customItemOverrides[itemId];
        
        // CRITICAL: If custom is active and has values, use them
        if (custom.isActive !== false) {
            const customAmount = (custom.customAmount !== null && custom.customAmount !== undefined) 
                ? custom.customAmount 
                : defaultAmount;
            const customQuantity = (custom.customQuantity !== null && custom.customQuantity !== undefined) 
                ? custom.customQuantity 
                : defaultQuantity;
            const customPaymentOption = custom.paymentOption || defaultPaymentOption;
            
            // Calculate unit price from custom values
            let customUnitPrice = defaultUnitPrice;
            if (customQuantity > 0 && customAmount > 0) {
                customUnitPrice = customAmount / customQuantity;
            } else if (customAmount > 0) {
                customUnitPrice = customAmount / (customQuantity || 1);
            } else if (customQuantity > 0) {
                customUnitPrice = defaultUnitPrice || (defaultAmount / (defaultQuantity || 1));
            }
            
            return {
                amount: customAmount,
                quantity: customQuantity,
                paymentOption: customPaymentOption,
                unitPrice: customUnitPrice,
                isCustomized: true,
                reason: custom.reason || null,
                updatedAt: custom.updatedAt || null,
                customAmount: custom.customAmount,
                customQuantity: custom.customQuantity,
                defaultAmount: custom.defaultAmount || defaultAmount,
                defaultQuantity: custom.defaultQuantity || defaultQuantity
            };
        }
    }
    
    // No customization - return defaults
    return {
        amount: defaultAmount || 0,
        quantity: defaultQuantity || 1,
        paymentOption: defaultPaymentOption || 'either',
        unitPrice: defaultUnitPrice || (defaultAmount / (defaultQuantity || 1)),
        isCustomized: false,
        reason: null,
        updatedAt: null,
        customAmount: null,
        customQuantity: null,
        defaultAmount: defaultAmount || 0,
        defaultQuantity: defaultQuantity || 1
    };
}

function getLevelKey(classLevel, currentClass) {
    var levelKey = 'Unknown';
    var classLevelLower = (classLevel || '').toLowerCase();
    var classNameLower = (currentClass || '').toLowerCase();
    
    if (classLevelLower === 'nursery') {
        levelKey = 'Nursery';
    } else if (classLevelLower === 'lowerprimary') {
        levelKey = 'LowerPrimary';
    } else if (classLevelLower === 'upperprimary') {
        levelKey = 'UpperPrimary';
    } else {
        // Try to infer from class name
        if (classNameLower.includes('baby') || classNameLower.includes('middle') || classNameLower.includes('top') || classNameLower.includes('nursery')) {
            levelKey = 'Nursery';
        } else if (classNameLower.includes('p.1') || classNameLower.includes('p.2') || classNameLower.includes('p.3')) {
            levelKey = 'LowerPrimary';
        } else if (classNameLower.includes('p.4') || classNameLower.includes('p.5') || classNameLower.includes('p.6') || classNameLower.includes('p.7')) {
            levelKey = 'UpperPrimary';
        }
    }
    
    return levelKey;
}

// ========== HELPER: DEDUPLICATE PAYMENT HISTORIES ==========
function deduplicateHistoriesForReport(histories) {
    if (!histories || histories.length === 0) return [];
    
    const seen = new Set();
    const unique = [];
    
    for (const history of histories) {
        const key = `${history.date || ''}_${history.type || ''}_${history.amount || 0}_${history.quantity || 0}_${history.receiptNumber || ''}`;
        if (!seen.has(key)) {
            seen.add(key);
            unique.push(history);
        }
    }
    
    return unique;
}

// ========== HELPER: GET PAID AMOUNTS FOR ITEM (WITH CUSTOM OVERRIDES) ==========
function getPaidAmountsForItemForReport(studentId, componentName, itemName, periodType, allPayments, currentYear, currentTerm) {
    let cashPaid = 0;
    let itemsBrought = 0;
    const paymentHistories = [];
    const processedKeys = new Set();
    
    // Filter payments for this student and current term
    const studentPayments = allPayments.filter(p => 
        p && p.studentId === studentId && 
        p.term === currentTerm && 
        p.academicYear === currentYear.toString()
    );
    
    for (const payment of studentPayments) {
        // Process activityItemPayments
        if (payment.activityItemPayments && Array.isArray(payment.activityItemPayments)) {
            for (const item of payment.activityItemPayments) {
                const itemPeriod = item.periodType || 'unknown';
                if (periodType && itemPeriod !== periodType) continue;
                
                const key = `${item.componentName || ''}_${item.itemName || ''}_${itemPeriod}_${item.paymentType || ''}_${item.amountPaid || 0}_${item.itemsBrought || 0}`;
                if (processedKeys.has(key)) continue;
                
                const compMatch = item.componentName && item.componentName.toLowerCase() === componentName.toLowerCase();
                const itemMatch = item.itemName && item.itemName.toLowerCase() === itemName.toLowerCase();
                
                if (compMatch && itemMatch) {
                    if (item.paymentType === 'paid_cash') {
                        const amount = (item.amountPaid || 0);
                        cashPaid += amount;
                        paymentHistories.push({
                            type: 'paid_cash',
                            amount: amount,
                            date: payment.date || new Date().toISOString(),
                            receiptNumber: payment.receiptNumber || 'N/A',
                            paymentId: payment.id
                        });
                    } else if (item.paymentType === 'brought_item') {
                        const qty = (item.itemsBrought || 0);
                        itemsBrought += qty;
                        paymentHistories.push({
                            type: 'brought_item',
                            quantity: qty,
                            date: payment.date || new Date().toISOString(),
                            receiptNumber: payment.receiptNumber || 'N/A',
                            paymentId: payment.id
                        });
                    }
                    processedKeys.add(key);
                }
            }
        }
        
        // Process paymentsByPeriodType
        if (payment.paymentsByPeriodType) {
            for (const period of ['one_time', 'termly', 'yearly']) {
                if (periodType && period !== periodType) continue;
                
                const periodItems = payment.paymentsByPeriodType[period] || [];
                for (const item of periodItems) {
                    const key = `${item.componentName || ''}_${item.itemName || ''}_${period}_${item.paymentType || ''}_${item.amountPaid || 0}_${item.itemsBrought || 0}`;
                    if (processedKeys.has(key)) continue;
                    
                    const compMatch = item.componentName && item.componentName.toLowerCase() === componentName.toLowerCase();
                    const itemMatch = item.itemName && item.itemName.toLowerCase() === itemName.toLowerCase();
                    
                    if (compMatch && itemMatch) {
                        if (item.paymentType === 'paid_cash') {
                            const amount = (item.amountPaid || 0);
                            cashPaid += amount;
                            paymentHistories.push({
                                type: 'paid_cash',
                                amount: amount,
                                date: payment.date || new Date().toISOString(),
                                receiptNumber: payment.receiptNumber || 'N/A',
                                paymentId: payment.id
                            });
                        } else if (item.paymentType === 'brought_item') {
                            const qty = (item.itemsBrought || 0);
                            itemsBrought += qty;
                            paymentHistories.push({
                                type: 'brought_item',
                                quantity: qty,
                                date: payment.date || new Date().toISOString(),
                                receiptNumber: payment.receiptNumber || 'N/A',
                                paymentId: payment.id
                            });
                        }
                        processedKeys.add(key);
                    }
                }
            }
        }
    }
    
    return { cashPaid, itemsBrought, paymentHistories };
}

// ========== BUILD REPORT DATA WITH CUSTOMIZATIONS ==========
function buildReportDataWithCustomizations(students, feeStructures, feeAssignments, allPayments, feeBursaries, classes, currentYear, currentTerm) {
    console.log('=== BUILDING REPORT DATA WITH CUSTOMIZATIONS ===');
    
    const isFirstTerm = currentTerm === 1;
    const assignmentsMap = {};
    feeAssignments.forEach(a => { if (a && a.studentId) assignmentsMap[a.studentId] = a; });
    
    const classesMap = {};
    classes.forEach(c => { if (c && c.id) classesMap[c.id] = c; });
    
    const bursariesMap = {};
    feeBursaries.forEach(b => { if (b && b.id) bursariesMap[b.id] = b; });
    
    // Get all status groups from fee structures
    const allStatusGroups = new Map();
    feeStructures.forEach(fs => {
        (fs.activityComponents || []).forEach(comp => {
            const statusGroupName = comp.statusGroupName || comp.name || 'Other';
            if (!allStatusGroups.has(statusGroupName)) {
                allStatusGroups.set(statusGroupName, {
                    name: statusGroupName,
                    periodTypes: new Set(),
                    color: getStatusGroupColorForReport(statusGroupName)
                });
            }
            allStatusGroups.get(statusGroupName).periodTypes.add(comp.periodType);
        });
    });
    
    const sortedStatusGroups = Array.from(allStatusGroups.values()).sort((a, b) => {
        const order = { 'Transportation': 1, 'Admission Fee': 2, 'schoolastic requirement': 3 };
        const aOrder = order[a.name] || 99;
        const bOrder = order[b.name] || 99;
        return aOrder - bOrder || a.name.localeCompare(b.name);
    });
    
    const processedStudents = [];
    
    for (const student of students) {
        const assignment = assignmentsMap[student.id] || {};
        const feeStructure = feeStructures.find(f => f && f.id === assignment.feeStructureId);
        
        // Get class name
        let currentClass = 'Not Assigned';
        let classLevel = 'Unknown';
        if (student.currentClassId && classesMap[student.currentClassId]) {
            currentClass = classesMap[student.currentClassId].name;
            classLevel = classesMap[student.currentClassId].level || 'Unknown';
        } else if (student.currentClass) {
            currentClass = student.currentClass;
        }
        
        // ========== CALCULATE TUITION WITH CUSTOM BURSARY ==========
        let expectedTuition = feeStructure ? (feeStructure.tuition || 0) : 0;
        let discountAmount = 0;
        let discountDisplay = '';
        let appliedBursary = null;
        
        // Check custom bursary from student record FIRST
        if (student.customBursary && student.customBursary.amount > 0) {
            discountAmount = student.customBursary.amount;
            discountDisplay = `UGX ${discountAmount.toLocaleString()} off (Custom)`;
            expectedTuition = Math.max(0, expectedTuition - discountAmount);
            appliedBursary = { 
                name: 'Custom Bursary', 
                type: 'fixed', 
                value: student.customBursary.amount, 
                isCustom: true 
            };
        } else if (assignment.bursaryId && bursariesMap[assignment.bursaryId]) {
            const bursary = bursariesMap[assignment.bursaryId];
            appliedBursary = bursary;
            if (bursary.type === 'percentage') {
                discountAmount = (expectedTuition * bursary.value) / 100;
                discountDisplay = `${bursary.value}% off`;
                expectedTuition = Math.max(0, expectedTuition - discountAmount);
            } else {
                discountAmount = bursary.value;
                discountDisplay = `UGX ${discountAmount.toLocaleString()} off`;
                expectedTuition = Math.max(0, expectedTuition - discountAmount);
            }
        }
        
        // Calculate tuition paid
        let tuitionPaid = 0;
        const studentPayments = allPayments.filter(p => p && p.studentId === student.id);
        const currentTermPayments = studentPayments.filter(p => p.term === currentTerm && p.academicYear === currentYear.toString());
        
        for (const payment of currentTermPayments) {
            tuitionPaid += (payment.tuitionPaid || 0);
        }
        const tuitionBalance = expectedTuition - tuitionPaid;
        
        // ========== BUILD STATUS GROUP DATA WITH CUSTOM OVERRIDES ==========
        const statusGroupData = {};
        
        if (feeStructure && feeStructure.activityComponents) {
            // Get custom transportation from student
            let customTransportation = null;
            if (student.customTransportation) {
                customTransportation = student.customTransportation;
            }
            
            for (const component of feeStructure.activityComponents) {
                const periodType = component.periodType || 'termly';
                const statusGroupName = component.statusGroupName || component.name || 'Other';
                
                const shouldInclude = (periodType === 'termly') || 
                                     (periodType === 'one_time' && isFirstTerm) ||
                                     (periodType === 'yearly' && isFirstTerm);
                
                if (!shouldInclude) continue;
                
                // Check if this is a transportation component
                const isTransportation = statusGroupName.toLowerCase().includes('transport') || 
                                        component.name.toLowerCase().includes('transport');
                
                let componentTotal = component.totalAmount || 0;
                let customAmountApplied = false;
                let customTransportAmount = null;
                
                // Apply custom transportation
                if (isTransportation && customTransportation) {
                    if (customTransportation.hasTransportation === false) {
                        continue; // Skip this component
                    }
                    if (customTransportation.amount && customTransportation.amount > 0) {
                        componentTotal = customTransportation.amount;
                        customAmountApplied = true;
                        customTransportAmount = customTransportation.amount;
                    }
                }
                
                if (!statusGroupData[statusGroupName]) {
                    statusGroupData[statusGroupName] = {
                        name: statusGroupName,
                        periodTypes: new Set([periodType]),
                        totalExpected: 0,
                        totalPaid: 0,
                        totalBalance: 0,
                        items: [],
                        isTransportation: isTransportation,
                        customAmountApplied: customAmountApplied,
                        customTransportAmount: customTransportAmount
                    };
                }
                
                // Process each item in the component
                for (const item of (component.items || [])) {
                    const itemId = item.id || item.name;
                    const defaultAmount = item.totalAmount || 0;
                    const defaultQuantity = item.quantity || 1;
                    const defaultUnitPrice = item.unitPrice || (defaultAmount / defaultQuantity);
                    const defaultPaymentOption = item.paymentOption || 'either';
                    
                    // ========== GET CUSTOM VALUES ==========
                    const customValues = getCustomizedItemValueForReport(
                        student,
                        itemId,
                        item.name,
                        defaultAmount,
                        defaultQuantity,
                        defaultPaymentOption,
                        defaultUnitPrice
                    );
                    
                    // USE CUSTOM VALUES
                    const effectiveAmount = customValues.amount;
                    const effectiveQuantity = customValues.quantity;
                    const effectiveUnitPrice = customValues.unitPrice;
                    const effectivePaymentOption = customValues.paymentOption;
                    const isCustomized = customValues.isCustomized;
                    const customReason = customValues.reason;
                    
                    // For transportation with custom amount
                    let finalAmount = effectiveAmount;
                    let finalUnitPrice = effectiveUnitPrice;
                    let finalQuantity = effectiveQuantity;
                    
                    if (isTransportation && customAmountApplied && customTransportAmount) {
                        finalAmount = customTransportAmount;
                        finalUnitPrice = customTransportAmount / (finalQuantity || 1);
                    }
                    
                    // Get paid amounts for this item
                    const { cashPaid, itemsBrought, paymentHistories } = getPaidAmountsForItemForReport(
                        student.id,
                        component.name,
                        item.name,
                        periodType,
                        allPayments,
                        currentYear,
                        currentTerm
                    );
                    
                    // Calculate remaining
                    let remainingAmount = 0;
                    let remainingQuantity = 0;
                    let isFullyPaid = false;
                    
                    if (effectivePaymentOption === 'cash_only') {
                        const totalRequiredCash = finalQuantity * finalUnitPrice;
                        isFullyPaid = (cashPaid >= totalRequiredCash);
                        remainingAmount = Math.max(0, totalRequiredCash - cashPaid);
                        remainingQuantity = 0;
                    } else if (effectivePaymentOption === 'item_only') {
                        isFullyPaid = (itemsBrought >= finalQuantity);
                        remainingQuantity = Math.max(0, finalQuantity - itemsBrought);
                        remainingAmount = remainingQuantity * finalUnitPrice;
                    } else {
                        const totalRequired = finalQuantity * finalUnitPrice;
                        const totalPaidValue = cashPaid + (itemsBrought * finalUnitPrice);
                        isFullyPaid = (totalPaidValue >= totalRequired);
                        
                        const cashCoversFullItems = Math.floor(cashPaid / finalUnitPrice);
                        const totalItemsCovered = itemsBrought + cashCoversFullItems;
                        remainingQuantity = Math.max(0, finalQuantity - totalItemsCovered);
                        remainingAmount = remainingQuantity * finalUnitPrice;
                    }
                    
                    if (isFullyPaid) {
                        remainingAmount = 0;
                        remainingQuantity = 0;
                    }
                    
                    // Add to status group
                    statusGroupData[statusGroupName].totalExpected += finalAmount;
                    statusGroupData[statusGroupName].totalPaid += cashPaid;
                    statusGroupData[statusGroupName].totalBalance += remainingAmount;
                    
                    statusGroupData[statusGroupName].items.push({
                        id: itemId,
                        name: item.name,
                        componentName: component.name,
                        periodType: periodType,
                        quantityRequired: finalQuantity,
                        totalAmount: finalAmount,
                        unitPrice: finalUnitPrice,
                        paymentOption: effectivePaymentOption,
                        isTangible: effectivePaymentOption !== 'cash_only',
                        alreadyPaidCash: cashPaid,
                        alreadyBroughtItems: itemsBrought,
                        remainingAmount: remainingAmount,
                        remainingQuantity: remainingQuantity,
                        isFullyPaid: isFullyPaid,
                        isCustomized: isCustomized,
                        customReason: customReason,
                        defaultAmount: defaultAmount,
                        defaultQuantity: defaultQuantity,
                        paymentHistories: deduplicateHistoriesForReport(paymentHistories)
                    });
                }
            }
        }
        
        // Calculate totals
        const totalExpected = expectedTuition + Object.values(statusGroupData).reduce((sum, sg) => sum + sg.totalExpected, 0);
        const totalPaid = tuitionPaid + Object.values(statusGroupData).reduce((sum, sg) => sum + sg.totalPaid, 0);
        const totalBalance = totalExpected - totalPaid;
        
        // Determine overall status
        let overallStatus = 'Good Standing';
        let statusColor = 'bg-green-100 text-green-800';
        let statusIcon = '✅';
        
        if (totalBalance > totalExpected && totalExpected > 0) {
            overallStatus = 'Critical Overdue';
            statusColor = 'bg-red-100 text-red-800';
            statusIcon = '🔴';
        } else if (totalBalance > 0) {
            overallStatus = 'Payment Due';
            statusColor = 'bg-yellow-100 text-yellow-800';
            statusIcon = '⚠️';
        } else if (totalBalance < 0) {
            overallStatus = 'Credit Balance';
            statusColor = 'bg-blue-100 text-blue-800';
            statusIcon = '💰';
        } else if (totalPaid === 0 && totalExpected > 0) {
            overallStatus = 'No Payment';
            statusColor = 'bg-gray-100 text-gray-800';
            statusIcon = '📋';
        }
        
        // Count customized items
        const customizedItems = Object.values(statusGroupData).reduce((count, sg) => {
            return count + sg.items.filter(item => item.isCustomized).length;
        }, 0);
        
        processedStudents.push({
            id: student.id,
            admissionNumber: student.admissionNumber || '',
            firstName: student.firstName || '',
            lastName: student.lastName || '',
            currentClass: currentClass,
            classLevel: classLevel,
            gender: student.gender || '',
            parentName: student.parentInfo?.name || '',
            parentPhone: student.parentInfo?.phone || '',
            parentEmail: student.parentInfo?.email || '',
            address: student.address || '',
            status: student.status || 'Active',
            enrollmentDate: student.enrolledAt || student.createdAt || new Date().toISOString(),
            
            // Tuition data
            tuition: {
                expected: expectedTuition,
                paid: tuitionPaid,
                balance: tuitionBalance,
                discountAmount: discountAmount,
                discountDisplay: discountDisplay,
                bursaryName: appliedBursary?.name || null,
                isCustomBursary: appliedBursary?.isCustom || false
            },
            
            // Status groups
            statusGroups: statusGroupData,
            
            // Totals
            totalExpected: totalExpected,
            totalPaid: totalPaid,
            totalBalance: totalBalance,
            overallStatus: overallStatus,
            statusColor: statusColor,
            statusIcon: statusIcon,
            
            // Fee structure info
            feeStructureName: feeStructure?.name || 'Not Assigned',
            feeStructureId: feeStructure?.id || null,
            feeStructureLevel: feeStructure?.level || null,
            
            // Customization info
            customizedItemsCount: customizedItems,
            hasCustomizations: customizedItems > 0 || Object.keys(student.customItemOverrides || {}).length > 0,
            customItemOverrides: student.customItemOverrides || {},
            customTransportation: student.customTransportation || null,
            customBursary: student.customBursary || null
        });
    }
    
    return {
        students: processedStudents,
        statusGroups: sortedStatusGroups
    };
}

// ========== RENDER COMPREHENSIVE REPORT TABLE WITH CUSTOMIZATIONS ==========
function renderReportTableWithCustomizations(students, statusGroups, includeTuition) {
    if (!students || students.length === 0) {
        return '<div class="text-center py-8 text-gray-500">No students found matching the criteria</div>';
    }
    
    const showTuition = includeTuition !== false;
    
    // Build table headers
    let headerRow1 = `
        <th class="p-2 text-center border" rowspan="2">#</th>
        <th class="p-2 text-left border" rowspan="2">Admission</th>
        <th class="p-2 text-left border" rowspan="2">Student Name</th>
        <th class="p-2 text-left border" rowspan="2">Class</th>
    `;
    
    let headerRow2 = '';
    
    if (showTuition) {
        headerRow1 += '<th class="p-2 text-center border bg-blue-50" colspan="3">💰 TUITION</th>';
        headerRow2 += `
            <th class="p-2 text-right border bg-blue-50">Expected</th>
            <th class="p-2 text-right border bg-blue-50">Paid</th>
            <th class="p-2 text-right border bg-blue-50">Balance</th>
        `;
    }
    
    // Status group headers
    for (const sg of statusGroups) {
        const displayName = sg.name === 'schoolastic requirement' ? 'Scholastic' : sg.name;
        const colorClass = sg.color || 'bg-gray-50';
        const periodBadges = [];
        if (sg.periodTypes.has('one_time')) periodBadges.push('⭐');
        if (sg.periodTypes.has('termly')) periodBadges.push('📅');
        if (sg.periodTypes.has('yearly')) periodBadges.push('📆');
        
        // Get unique items across all students for this status group
        const allItems = new Set();
        for (const student of students) {
            if (student.statusGroups && student.statusGroups[sg.name]) {
                for (const item of student.statusGroups[sg.name].items) {
                    allItems.add(item.name);
                }
            }
        }
        
        const itemArray = Array.from(allItems).sort();
        
        if (itemArray.length > 0) {
            headerRow1 += `<th class="p-2 text-center border ${colorClass}" colspan="${itemArray.length}">🏷️ ${displayName} ${periodBadges.join(' ')}</th>`;
            
            for (const itemName of itemArray) {
                headerRow2 += `<th class="p-2 text-center border ${colorClass} text-xs">${escapeHtmlForReport(itemName)}</th>`;
            }
        }
    }
    
    // Add total columns
    headerRow1 += `
        <th class="p-2 text-right border" rowspan="2">Total Paid</th>
        <th class="p-2 text-right border" rowspan="2">Balance</th>
        <th class="p-2 text-center border" rowspan="2">Status</th>
        <th class="p-2 text-center border" rowspan="2">Customizations</th>
    `;
    
    // Build table body
    let bodyRows = '';
    
    for (let i = 0; i < students.length; i++) {
        const student = students[i];
        let row = '';
        let rowClass = '';
        
        if (student.overallStatus === 'Critical Overdue') rowClass = 'bg-red-50';
        else if (student.overallStatus === 'Credit Balance') rowClass = 'bg-blue-50';
        else if (student.overallStatus === 'Fully Paid') rowClass = 'bg-green-50';
        else if (student.hasCustomizations) rowClass = 'bg-orange-50/30';
        
        row += `
            <tr class="border-b hover:bg-gray-50 ${rowClass}">
                <td class="p-2 text-center text-gray-400 text-xs">${i + 1}</td>
                <td class="p-2 font-mono text-xs font-semibold">${escapeHtmlForReport(student.admissionNumber)}</td>
                <td class="p-2 font-medium">${escapeHtmlForReport(student.firstName)} ${escapeHtmlForReport(student.lastName)}</td>
                <td class="p-2"><span class="px-2 py-0.5 rounded-full text-xs bg-purple-100 text-purple-800">${escapeHtmlForReport(student.currentClass)}</span></td>
        `;
        
        // Tuition columns
        if (showTuition) {
            const tuition = student.tuition || { expected: 0, paid: 0, balance: 0 };
            const isCustomBursary = tuition.isCustomBursary || false;
            const bursaryBadge = isCustomBursary ? '🎖️' : '';
            
            row += `
                <td class="p-2 text-right">
                    UGX ${formatMoneyForReport(tuition.expected)}
                    ${isCustomBursary ? `<span class="text-xs text-green-500 ml-1" title="Custom Bursary">🎖️</span>` : ''}
                </td>
                <td class="p-2 text-right text-green-600 font-semibold">UGX ${formatMoneyForReport(tuition.paid)}</td>
                <td class="p-2 text-right font-bold ${tuition.balance > 0 ? 'text-red-600' : 'text-green-600'}">
                    UGX ${formatMoneyForReport(Math.abs(tuition.balance))}
                </td>
            `;
        }
        
        // Status group columns
        for (const sg of statusGroups) {
            const sgData = student.statusGroups ? student.statusGroups[sg.name] : null;
            
            if (!sgData || !sgData.items || sgData.items.length === 0) {
                // Check if this student has this status group
                const hasGroup = student.statusGroups && student.statusGroups[sg.name];
                if (hasGroup) {
                    // Show empty cells for each item
                    const allItems = new Set();
                    for (const s of students) {
                        if (s.statusGroups && s.statusGroups[sg.name]) {
                            for (const item of s.statusGroups[sg.name].items) {
                                allItems.add(item.name);
                            }
                        }
                    }
                    const itemArray = Array.from(allItems).sort();
                    for (let j = 0; j < itemArray.length; j++) {
                        row += `<td class="p-2 text-center border text-xs text-gray-300">—</td>`;
                    }
                } else {
                    row += `<td class="p-2 text-center border text-xs text-gray-300">—</td>`;
                }
                continue;
            }
            
            // Get all item names for this status group
            const allItems = new Set();
            for (const s of students) {
                if (s.statusGroups && s.statusGroups[sg.name]) {
                    for (const item of s.statusGroups[sg.name].items) {
                        allItems.add(item.name);
                    }
                }
            }
            const itemArray = Array.from(allItems).sort();
            
            // Map student's items to the full list
            const studentItemsMap = {};
            for (const item of sgData.items) {
                studentItemsMap[item.name] = item;
            }
            
            for (const itemName of itemArray) {
                const item = studentItemsMap[itemName];
                
                if (!item) {
                    row += `<td class="p-2 text-center border text-xs text-gray-300">—</td>`;
                    continue;
                }
                
                const isCustomized = item.isCustomized || false;
                const isFullyPaid = item.isFullyPaid || false;
                
                let displayText = '';
                let cellClass = '';
                
                if (item.paymentOption === 'cash_only') {
                    const totalAmount = item.totalAmount || 0;
                    const paidAmount = item.alreadyPaidCash || 0;
                    const remainingAmount = item.remainingAmount || 0;
                    
                    if (isFullyPaid) {
                        displayText = `<span class="text-green-600">✓ UGX ${formatMoneyForReport(paidAmount)}</span>`;
                        cellClass = 'text-green-600';
                    } else if (paidAmount > 0) {
                        displayText = `UGX ${formatMoneyForReport(paidAmount)}<br><span class="text-xs text-red-500">Due: UGX ${formatMoneyForReport(remainingAmount)}</span>`;
                        cellClass = 'text-yellow-600';
                    } else {
                        displayText = `UGX ${formatMoneyForReport(totalAmount)}<br><span class="text-xs text-red-500">Due</span>`;
                        cellClass = 'text-red-600';
                    }
                } else if (item.paymentOption === 'item_only') {
                    const required = item.quantityRequired || 0;
                    const brought = item.alreadyBroughtItems || 0;
                    const remaining = item.remainingQuantity || 0;
                    
                    if (isFullyPaid) {
                        displayText = `<span class="text-green-600">✓ ${brought}/${required}</span>`;
                        cellClass = 'text-green-600';
                    } else if (brought > 0) {
                        displayText = `${brought}/${required}<br><span class="text-xs text-red-500">${remaining} remaining</span>`;
                        cellClass = 'text-yellow-600';
                    } else {
                        displayText = `0/${required}<br><span class="text-xs text-red-500">Due</span>`;
                        cellClass = 'text-red-600';
                    }
                } else {
                    // Mixed - show both
                    const required = item.quantityRequired || 0;
                    const brought = item.alreadyBroughtItems || 0;
                    const remainingQty = item.remainingQuantity || 0;
                    const totalAmount = item.totalAmount || 0;
                    const paidAmount = item.alreadyPaidCash || 0;
                    const remainingAmt = item.remainingAmount || 0;
                    
                    if (isFullyPaid) {
                        displayText = `<span class="text-green-600">✓ ${brought}/${required}</span>`;
                        if (paidAmount > 0) {
                            displayText += `<br><span class="text-xs text-green-600">UGX ${formatMoneyForReport(paidAmount)}</span>`;
                        }
                        cellClass = 'text-green-600';
                    } else if (brought > 0 && paidAmount > 0) {
                        displayText = `${brought}/${required}<br>UGX ${formatMoneyForReport(paidAmount)}`;
                        if (remainingQty > 0 || remainingAmt > 0) {
                            displayText += `<br><span class="text-xs text-red-500">${remainingQty} items OR UGX ${formatMoneyForReport(remainingAmt)}</span>`;
                        }
                        cellClass = 'text-yellow-600';
                    } else if (brought > 0) {
                        displayText = `${brought}/${required}<br><span class="text-xs text-red-500">${remainingQty} remaining</span>`;
                        cellClass = 'text-yellow-600';
                    } else if (paidAmount > 0) {
                        displayText = `UGX ${formatMoneyForReport(paidAmount)}<br><span class="text-xs text-red-500">UGX ${formatMoneyForReport(remainingAmt)} due</span>`;
                        cellClass = 'text-yellow-600';
                    } else {
                        displayText = `0/${required}<br><span class="text-xs text-red-500">Due</span>`;
                        cellClass = 'text-red-600';
                    }
                }
                
                // Add customization indicator
                let customBadge = '';
                if (isCustomized) {
                    customBadge = `<span class="ml-1 text-xs text-orange-500" title="Customized: ${item.defaultAmount || 'Default'} → ${item.totalAmount || 'Custom'}">⚡</span>`;
                }
                
                row += `
                    <td class="p-2 text-center border text-xs ${cellClass}">
                        ${displayText}
                        ${customBadge}
                        ${isCustomized ? `<div class="text-xs text-orange-500 mt-0.5">Custom</div>` : ''}
                    </td>
                `;
            }
        }
        
        // Total columns
        row += `
            <td class="p-2 text-right font-semibold ${student.totalPaid > 0 ? 'text-green-600' : 'text-gray-400'}">
                UGX ${formatMoneyForReport(student.totalPaid)}
            </td>
            <td class="p-2 text-right font-bold ${student.totalBalance > 0 ? 'text-red-600' : 'text-green-600'}">
                UGX ${formatMoneyForReport(Math.abs(student.totalBalance))}
            </td>
            <td class="p-2"><span class="px-2 py-0.5 rounded-full text-xs ${student.statusColor}">${student.statusIcon} ${student.overallStatus}</span></td>
            <td class="p-2 text-center">
                ${student.hasCustomizations ? 
                    `<span class="px-2 py-0.5 rounded-full text-xs bg-orange-100 text-orange-700">⚡ ${student.customizedItemsCount || 'Custom'}</span>` : 
                    '<span class="text-xs text-gray-400">—</span>'
                }
            </td>
        </tr>`;
        
        bodyRows += row;
    }
    
    // Build the complete table
    return `
        <div class="overflow-x-auto" id="reportTableWrapper">
            <table class="w-full text-sm border-collapse" id="reportTable">
                <thead class="bg-gray-100 sticky top-0 z-10">
                    <tr>
                        ${headerRow1}
                    </tr>
                    <tr>
                        ${headerRow2}
                    </tr>
                </thead>
                <tbody>
                    ${bodyRows}
                </tbody>
            </table>
        </div>
    `;
}

// ========== RENDER STATUS GROUP SUMMARY WITH CUSTOMIZATIONS ==========
function renderStatusGroupSummaryWithCustomizations(students, statusGroups, formatMoneyFn) {
    const groupSummary = {};
    
    for (const sg of statusGroups) {
        groupSummary[sg.name] = {
            expected: 0,
            paid: 0,
            balance: 0,
            studentsWithBalance: 0,
            customizedItems: 0
        };
    }
    
    for (const student of students) {
        for (const sg of statusGroups) {
            const sgData = student.statusGroups ? student.statusGroups[sg.name] : null;
            if (sgData) {
                groupSummary[sg.name].expected += sgData.totalExpected || 0;
                groupSummary[sg.name].paid += sgData.totalPaid || 0;
                if (sgData.totalBalance > 0) {
                    groupSummary[sg.name].studentsWithBalance++;
                }
                // Count customized items
                const customCount = (sgData.items || []).filter(item => item.isCustomized).length;
                groupSummary[sg.name].customizedItems += customCount;
            }
        }
    }
    
    for (const sg of statusGroups) {
        groupSummary[sg.name].balance = groupSummary[sg.name].expected - groupSummary[sg.name].paid;
    }
    
    const sortedGroups = [...statusGroups].sort((a, b) => {
        return groupSummary[b.name].balance - groupSummary[a.name].balance;
    });
    
    return sortedGroups.map(sg => {
        const data = groupSummary[sg.name];
        const balanceClass = data.balance > 0 ? 'text-red-600' : data.balance < 0 ? 'text-blue-600' : 'text-green-600';
        const rate = data.expected > 0 ? ((data.paid / data.expected) * 100).toFixed(1) : 0;
        const rateClass = data.expected > 0 && (data.paid / data.expected) >= 0.8 ? 'text-green-600' : 
                         data.expected > 0 && (data.paid / data.expected) >= 0.5 ? 'text-yellow-600' : 'text-red-600';
        
        const colorClass = getStatusGroupColorForReport(sg.name);
        let displayName = sg.name;
        if (displayName === 'schoolastic requirement') displayName = 'Scholastic';
        if (displayName === 'Admission Fee') displayName = 'Admission';
        
        const customBadge = data.customizedItems > 0 ? 
            `<span class="ml-2 text-xs bg-orange-100 text-orange-700 px-1.5 py-0.5 rounded-full">⚡ ${data.customizedItems} customized</span>` : '';
        
        return `
            <div class="border rounded-lg p-4 ${colorClass} shadow-sm">
                <div class="flex justify-between items-start mb-3">
                    <div>
                        <h4 class="font-bold text-md flex items-center gap-2">
                            <i class="fas fa-tag"></i> ${escapeHtmlForReport(displayName)}
                            ${customBadge}
                        </h4>
                        <div class="flex gap-1 mt-1">
                            ${sg.periodTypes.has('one_time') ? '<span class="text-xs bg-purple-200 px-1.5 py-0.5 rounded">⭐ One-Time</span>' : ''}
                            ${sg.periodTypes.has('termly') ? '<span class="text-xs bg-green-200 px-1.5 py-0.5 rounded">📅 Termly</span>' : ''}
                            ${sg.periodTypes.has('yearly') ? '<span class="text-xs bg-orange-200 px-1.5 py-0.5 rounded">📆 Yearly</span>' : ''}
                        </div>
                    </div>
                    <div class="text-right">
                        <p class="text-2xl font-bold ${balanceClass}">${data.balance > 0 ? `UGX ${formatMoneyFn(data.balance)}` : data.balance < 0 ? `Credit: ${formatMoneyFn(Math.abs(data.balance))}` : '✓ Paid'}</p>
                        <p class="text-xs text-gray-500">outstanding</p>
                    </div>
                </div>
                <div class="space-y-2 text-sm">
                    <div class="flex justify-between">
                        <span>Expected:</span>
                        <span class="font-semibold">UGX ${formatMoneyFn(data.expected)}</span>
                    </div>
                    <div class="flex justify-between">
                        <span>Collected:</span>
                        <span class="font-semibold text-green-600">UGX ${formatMoneyFn(data.paid)}</span>
                    </div>
                    <div class="flex justify-between">
                        <span>Collection Rate:</span>
                        <span class="font-semibold ${rateClass}">${rate}%</span>
                    </div>
                    <div class="flex justify-between text-xs text-gray-500">
                        <span>Students with balance:</span>
                        <span>${data.studentsWithBalance}</span>
                    </div>
                </div>
                <div class="w-full bg-gray-200 rounded-full h-1.5 mt-3">
                    <div class="bg-green-500 rounded-full h-1.5" style="width: ${Math.min(100, rate)}%"></div>
                </div>
            </div>
        `;
    }).join('');
}

// ========== HELPER FUNCTIONS ==========
function formatMoneyForReport(amount) {
    const num = Math.round(amount || 0);
    return num.toLocaleString('en-US');
}

function escapeHtmlForReport(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function getStatusGroupColorForReport(name) {
    if (!name) return 'bg-gray-100 text-gray-800 border-gray-200';
    
    const colors = {
        'Transportation': 'bg-orange-100 text-orange-800 border-orange-200',
        'Admission Fee': 'bg-purple-100 text-purple-800 border-purple-200',
        'schoolastic requirement': 'bg-green-100 text-green-800 border-green-200',
        'Scholastic': 'bg-green-100 text-green-800 border-green-200',
        'Sports': 'bg-blue-100 text-blue-800 border-blue-200',
        'Development': 'bg-red-100 text-red-800 border-red-200',
        'Tuition': 'bg-indigo-100 text-indigo-800 border-indigo-200'
    };
    
    const lowerName = (name || '').toLowerCase();
    for (const [key, color] of Object.entries(colors)) {
        if (lowerName.includes(key.toLowerCase()) || key.toLowerCase().includes(lowerName)) {
            return color;
        }
    }
    
    return 'bg-gray-100 text-gray-800 border-gray-200';
}

function getTermNameForReport(term) {
    const names = { 1: 'First Term', 2: 'Second Term', 3: 'Third Term' };
    return names[term] || `Term ${term}`;
}

// ========== MAIN REPORT GENERATION FUNCTION ==========
async function generateComprehensiveReportWithCustomizations() {
    console.log('=== GENERATING COMPREHENSIVE REPORT WITH CUSTOMIZATIONS ===');
    
    const mainContent = document.getElementById('mainContent');
    if (mainContent) {
        mainContent.innerHTML = '<div class="flex justify-center items-center h-64"><div class="loading-spinner"></div></div>';
    }
    
    try {
        await initializeAcademicSettings();
        const { currentYear, currentTerm } = currentAcademicSettings;
        const termName = getTermNameForReport(currentTerm);
        
        // Fetch all data
        const [studentsRes, classesRes, feeStructuresRes, feeAssignmentsRes, feePaymentsRes, feeBursariesRes] = await Promise.all([
            fetch('/api/students'),
            fetch('/api/school/classes'),
            fetch('/api/fee/structures'),
            fetch('/api/student-fee-assignments'),
            fetch('/api/fee/payments'),
            fetch('/api/fee/bursaries')
        ]);
        
        let students = await studentsRes.json();
        let classes = await classesRes.json();
        let feeStructures = await feeStructuresRes.json();
        let feeAssignments = await feeAssignmentsRes.json();
        let allPayments = await feePaymentsRes.json();
        let feeBursaries = await feeBursariesRes.json();
        
        students = Array.isArray(students) ? students : [];
        feeStructures = Array.isArray(feeStructures) ? feeStructures : [];
        feeAssignments = Array.isArray(feeAssignments) ? feeAssignments : [];
        allPayments = Array.isArray(allPayments) ? allPayments : [];
        
        // Build report data with customizations
        const reportData = buildReportDataWithCustomizations(
            students,
            feeStructures,
            feeAssignments,
            allPayments,
            feeBursaries,
            classes,
            currentYear,
            currentTerm
        );
        
        const { students: reportStudents, statusGroups } = reportData;
        
        // Calculate totals
        const totalStudents = reportStudents.length;
        const totalExpected = reportStudents.reduce((sum, s) => sum + s.totalExpected, 0);
        const totalPaid = reportStudents.reduce((sum, s) => sum + s.totalPaid, 0);
        const totalBalance = totalExpected - totalPaid;
        const totalCustomized = reportStudents.filter(s => s.hasCustomizations).length;
        const totalCustomizedItems = reportStudents.reduce((sum, s) => sum + s.customizedItemsCount, 0);
        
        const collectionRate = totalExpected > 0 ? (totalPaid / totalExpected * 100).toFixed(1) : 0;
        
        // Render the page
        const html = `
            <div class="space-y-6">
                <!-- Header -->
                <div class="bg-gradient-to-r from-blue-700 via-indigo-700 to-purple-700 rounded-2xl p-5 text-white">
                    <div class="flex justify-between items-center flex-wrap gap-4">
                        <div>
                            <h1 class="text-2xl font-bold flex items-center gap-2">
                                <i class="fas fa-file-alt mr-2"></i>Comprehensive Report
                            </h1>
                            <p class="text-sm opacity-90">${termName} ${currentYear} - Customization-Aware Report</p>
                        </div>
                        <div class="flex gap-2">
                            <button onclick="refreshReportWithCustomizations()" class="bg-white/20 backdrop-blur-sm text-white px-4 py-2 rounded-lg text-sm font-semibold hover:bg-white/30">
                                <i class="fas fa-sync-alt"></i> Refresh
                            </button>
                            <button onclick="exportReportWithCustomizations()" class="bg-white/20 backdrop-blur-sm text-white px-4 py-2 rounded-lg text-sm font-semibold hover:bg-white/30">
                                <i class="fas fa-download"></i> Export CSV
                            </button>
                            <button onclick="printReportWithCustomizations()" class="bg-white/20 backdrop-blur-sm text-white px-4 py-2 rounded-lg text-sm font-semibold hover:bg-white/30">
                                <i class="fas fa-print"></i> Print
                            </button>
                        </div>
                    </div>
                </div>
                
                <!-- Statistics Cards -->
                <div class="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-3">
                    <div class="bg-blue-50 rounded-xl p-4 text-center border border-blue-200">
                        <p class="text-xs text-gray-500">Total Students</p>
                        <p class="text-2xl font-bold text-blue-600">${totalStudents}</p>
                    </div>
                    <div class="bg-green-50 rounded-xl p-4 text-center border border-green-200">
                        <p class="text-xs text-gray-500">Total Expected</p>
                        <p class="text-xl font-bold text-green-600">UGX ${formatMoneyForReport(totalExpected)}</p>
                    </div>
                    <div class="bg-purple-50 rounded-xl p-4 text-center border border-purple-200">
                        <p class="text-xs text-gray-500">Total Collected</p>
                        <p class="text-xl font-bold text-purple-600">UGX ${formatMoneyForReport(totalPaid)}</p>
                    </div>
                    <div class="bg-red-50 rounded-xl p-4 text-center border border-red-200">
                        <p class="text-xs text-gray-500">Total Balance</p>
                        <p class="text-xl font-bold text-red-600">UGX ${formatMoneyForReport(totalBalance)}</p>
                    </div>
                    <div class="bg-yellow-50 rounded-xl p-4 text-center border border-yellow-200">
                        <p class="text-xs text-gray-500">Collection Rate</p>
                        <p class="text-2xl font-bold text-yellow-600">${collectionRate}%</p>
                    </div>
                    <div class="bg-orange-50 rounded-xl p-4 text-center border border-orange-200">
                        <p class="text-xs text-gray-500">Customizations</p>
                        <p class="text-2xl font-bold text-orange-600">${totalCustomized} / ${totalCustomizedItems}</p>
                        <p class="text-xs text-gray-400">students / items</p>
                    </div>
                </div>
                
                <!-- Status Group Summary -->
                <div>
                    <h3 class="font-bold text-lg mb-3 flex items-center gap-2">
                        <i class="fas fa-tags text-purple-600"></i> Status Group Summary
                        <span class="text-sm font-normal text-gray-500">(with customization indicators)</span>
                    </h3>
                    <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        ${renderStatusGroupSummaryWithCustomizations(reportStudents, statusGroups, formatMoneyForReport)}
                    </div>
                </div>
                
                <!-- Students Table -->
                <div>
                    <h3 class="font-bold text-lg mb-3 flex items-center gap-2">
                        <i class="fas fa-table text-blue-600"></i> Student Details
                        <span class="text-sm font-normal text-gray-500">(⚡ = customized item)</span>
                    </h3>
                    ${renderReportTableWithCustomizations(reportStudents, statusGroups, true)}
                </div>
            </div>
        `;
        
        if (mainContent) {
            mainContent.innerHTML = html;
        }
        
        // Store data for export
        window.reportDataWithCustomizations = {
            students: reportStudents,
            statusGroups: statusGroups,
            totals: { totalStudents, totalExpected, totalPaid, totalBalance, collectionRate, totalCustomized, totalCustomizedItems }
        };
        
        console.log('✅ Report generated with customizations!');
        console.log(`   ${totalCustomized} students have ${totalCustomizedItems} customized items`);
        
    } catch (error) {
        console.error('Error generating report:', error);
        if (mainContent) {
            mainContent.innerHTML = `
                <div class="bg-red-50 p-6 text-center rounded-lg border border-red-200">
                    <i class="fas fa-exclamation-triangle text-red-600 text-4xl mb-3"></i>
                    <p class="text-red-600 font-semibold">Error generating report</p>
                    <p class="text-red-500 text-sm mt-1">${error.message}</p>
                    <button onclick="generateComprehensiveReportWithCustomizations()" class="mt-3 bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700">
                        <i class="fas fa-sync-alt"></i> Retry
                    </button>
                </div>
            `;
        }
    }
}

// ========== EXPORT REPORT WITH CUSTOMIZATIONS ==========
function exportReportWithCustomizations() {
    const data = window.reportDataWithCustomizations;
    if (!data || !data.students || data.students.length === 0) {
        alert('No data to export. Please generate the report first.');
        return;
    }
    
    const { students, statusGroups } = data;
    
    // Build CSV headers
    let headers = ['Admission', 'First Name', 'Last Name', 'Class', 'Status', 'Total Expected', 'Total Paid', 'Total Balance', 'Customized Items'];
    
    // Add tuition columns
    headers.push('Tuition Expected', 'Tuition Paid', 'Tuition Balance', 'Bursary');
    
    // Add status group columns
    for (const sg of statusGroups) {
        const displayName = sg.name === 'schoolastic requirement' ? 'Scholastic' : sg.name;
        // Get all unique item names for this status group
        const allItems = new Set();
        for (const student of students) {
            if (student.statusGroups && student.statusGroups[sg.name]) {
                for (const item of student.statusGroups[sg.name].items) {
                    allItems.add(item.name);
                }
            }
        }
        const itemArray = Array.from(allItems).sort();
        for (const itemName of itemArray) {
            headers.push(`${displayName} - ${itemName} (Status)`);
            headers.push(`${displayName} - ${itemName} (Collected/Required)`);
            headers.push(`${displayName} - ${itemName} (Customized)`);
        }
    }
    
    // Build CSV rows
    const rows = students.map(student => {
        const row = [
            student.admissionNumber || '',
            student.firstName || '',
            student.lastName || '',
            student.currentClass || '',
            student.overallStatus || '',
            student.totalExpected || 0,
            student.totalPaid || 0,
            student.totalBalance || 0,
            student.customizedItemsCount || 0
        ];
        
        // Tuition
        const tuition = student.tuition || {};
        row.push(tuition.expected || 0);
        row.push(tuition.paid || 0);
        row.push(tuition.balance || 0);
        row.push(tuition.bursaryName || (tuition.isCustomBursary ? 'Custom Bursary' : 'None'));
        
        // Status groups
        for (const sg of statusGroups) {
            const sgData = student.statusGroups ? student.statusGroups[sg.name] : null;
            const allItems = new Set();
            for (const s of students) {
                if (s.statusGroups && s.statusGroups[sg.name]) {
                    for (const item of s.statusGroups[sg.name].items) {
                        allItems.add(item.name);
                    }
                }
            }
            const itemArray = Array.from(allItems).sort();
            
            for (const itemName of itemArray) {
                let item = null;
                if (sgData && sgData.items) {
                    item = sgData.items.find(i => i.name === itemName);
                }
                
                if (item) {
                    const status = item.isFullyPaid ? 'Fully Paid' : 
                                  (item.alreadyPaidCash > 0 || item.alreadyBroughtItems > 0) ? 'Partial' : 'Unpaid';
                    const collected = item.paymentOption === 'item_only' ? 
                        `${item.alreadyBroughtItems || 0}/${item.quantityRequired || 0}` :
                        `${item.alreadyPaidCash || 0}/${item.totalAmount || 0}`;
                    const customized = item.isCustomized ? 'Yes' : 'No';
                    row.push(status, collected, customized);
                } else {
                    row.push('N/A', '0/0', 'No');
                }
            }
        }
        
        return row;
    });
    
    // Create CSV
    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `report_with_customizations_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    URL.revokeObjectURL(link.href);
    
    alert('✅ Report exported successfully!');
}

