function editSchoolStockTransaction(transactionId) {
    var transaction = schoolStockTransactions.find(function(t) { return t.id === transactionId; });
    if (!transaction) {
        alert('Transaction not found');
        return;
    }
    
    if (transaction.reversed) {
        alert('Cannot edit a reversed transaction');
        return;
    }
    
    var modalHtml = `
        <div id="editSchoolStockTxModal" class="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div class="bg-white rounded-2xl shadow-2xl w-full max-w-md">
                <div class="flex justify-between items-center p-5 border-b">
                    <h3 class="text-xl font-bold flex items-center gap-2">
                        <i class="fas fa-edit text-blue-600"></i> Edit Transaction
                    </h3>
                    <button onclick="closeModal()" class="text-gray-400 hover:text-gray-600 text-2xl leading-none">&times;</button>
                </div>
                <form id="editSchoolStockTxForm" class="p-5 space-y-4" onsubmit="return false;">
                    <div><label class="block text-sm font-semibold text-gray-700 mb-1">Item</label><input type="text" value="${escapeHtml(transaction.itemName)}" class="w-full border border-gray-300 rounded-lg px-3 py-2 bg-gray-100" disabled></div>
                    <div><label class="block text-sm font-semibold text-gray-700 mb-1">Quantity</label><input type="number" id="editTxQuantity" value="${transaction.quantity}" class="w-full border border-gray-300 rounded-lg px-3 py-2" min="1"></div>
                    <div><label class="block text-sm font-semibold text-gray-700 mb-1">Destination</label><select id="editTxDestination" class="w-full border border-gray-300 rounded-lg px-3 py-2">
                        ${['classroom','office','kitchen','store','staff_room','other'].map(function(d) {
                            return `<option value="${d}" ${transaction.destination === d ? 'selected' : ''}>${d.charAt(0).toUpperCase() + d.slice(1).replace('_', ' ')}</option>`;
                        }).join('')}
                    </select></div>
                    <div><label class="block text-sm font-semibold text-gray-700 mb-1">Recipient</label><input type="text" id="editTxRecipient" value="${escapeHtml(transaction.recipient || '')}" class="w-full border border-gray-300 rounded-lg px-3 py-2"></div>
                    <div><label class="block text-sm font-semibold text-gray-700 mb-1">Comment</label><textarea id="editTxComment" rows="2" class="w-full border border-gray-300 rounded-lg px-3 py-2">${escapeHtml(transaction.comment || '')}</textarea></div>
                    <div class="flex gap-3 pt-2">
                        <button type="submit" class="flex-1 bg-blue-600 hover:bg-blue-700 text-white py-2 rounded-lg font-semibold text-sm transition"><i class="fas fa-save mr-1"></i> Save Changes</button>
                        <button type="button" onclick="closeModal()" class="flex-1 bg-gray-200 hover:bg-gray-300 text-gray-700 py-2 rounded-lg text-sm transition">Cancel</button>
                    </div>
                </form>
            </div>
        </div>
    `;
    document.body.insertAdjacentHTML('beforeend', modalHtml);
    
    document.getElementById('editSchoolStockTxForm').addEventListener('submit', async function(e) {
        e.preventDefault();
        
        var quantity = parseInt(document.getElementById('editTxQuantity').value || 0);
        var destination = document.getElementById('editTxDestination').value;
        var recipient = document.getElementById('editTxRecipient').value.trim();
        var comment = document.getElementById('editTxComment').value.trim();
        
        if (quantity <= 0) { alert('Please enter a valid quantity'); return; }
        if (!recipient) { alert('Please enter a recipient name'); return; }
        
        try {
            var response = await fetch('/api/school-stock/transaction/' + transactionId, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ quantity, destination, recipient, comment })
            });
            
            var result = await response.json();
            
            if (result.success) {
                showToast('✅ Transaction updated successfully', 'success');
                closeModal();
                await refreshSchoolStock();
            } else {
                alert('❌ ' + (result.error || 'Error updating transaction'));
            }
        } catch (err) {
            console.error('Error updating transaction:', err);
            alert('Network error: ' + err.message);
        }
    });
}

async function reverseSchoolStockTransaction(transactionId) {
    if (!confirm('↩️ Reverse this transaction?\n\nThis will return the items to stock.')) return;
    
    var reason = prompt('Reason for reversal (optional):');
    
    try {
        var response = await fetch('/api/school-stock/reverse/' + transactionId, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ reason: reason || 'Transaction reversed' })
        });
        
        var result = await response.json();
        
        if (result.success) {
            showToast('✅ Transaction reversed successfully', 'success');
            await refreshSchoolStock();
        } else {
            alert('❌ ' + (result.error || 'Error reversing transaction'));
        }
    } catch (err) {
        console.error('Error reversing transaction:', err);
        alert('Network error: ' + err.message);
    }
}

