function showHistoryTooltip(el) {
    const tooltip = el.querySelector('.history-tooltip');
    if (tooltip) {
        tooltip.style.display = 'block';
        // Optional: position adjustment to prevent overflow
        const rect = el.getBoundingClientRect();
        const tooltipRect = tooltip.getBoundingClientRect();
        if (rect.right + tooltipRect.width > window.innerWidth) {
            tooltip.style.left = 'auto';
            tooltip.style.right = '0';
        } else {
            tooltip.style.left = '0';
            tooltip.style.right = 'auto';
        }
        el.classList.add('show');
    }
}

function hideHistoryTooltip(el) {
    const tooltip = el.querySelector('.history-tooltip');
    if (tooltip) {
        tooltip.style.display = 'none';
        el.classList.remove('show');
    }
}


// ==================== PAGE RENDERER ====================
function renderPage(html) {
    // Try to find the main content container
    let mainArea = document.getElementById('mainContent');
    
    // If not found, try other common containers
    if (!mainArea) {
        mainArea = document.querySelector('.content-area');
    }
    if (!mainArea) {
        mainArea = document.querySelector('#content');
    }
    if (!mainArea) {
        mainArea = document.querySelector('.page-content');
    }
    
    // If still not found, create it
    if (!mainArea) {
        mainArea = document.createElement('div');
        mainArea.id = 'mainContent';
        mainArea.className = 'p-6';
        // Find where to insert it
        const container = document.querySelector('.container') || document.querySelector('main') || document.body;
        container.appendChild(mainArea);
    }
    
    mainArea.innerHTML = html;
    
    // Update active sidebar item
    document.querySelectorAll('.sidebar-item').forEach(el => {
        el.classList.remove('active', 'bg-blue-50', 'text-blue-700');
    });
    const active = document.querySelector(`.sidebar-item[data-page="${window.currentPage || ''}"]`);
    if (active) {
        active.classList.add('active', 'bg-blue-50', 'text-blue-700');
    }
    
    // Scroll to top
    window.scrollTo({ top: 0, behavior: 'smooth' });
}

// ==================== TOAST NOTIFICATIONS ====================
function showToast(message, type = 'success') {
    const existing = document.querySelector('.toast-notification');
    if (existing) existing.remove();
    
    const colors = {
        success: 'bg-green-500',
        error: 'bg-red-500',
        warning: 'bg-yellow-500',
        info: 'bg-blue-500'
    };
    const icons = {
        success: 'fa-check-circle',
        error: 'fa-exclamation-circle',
        warning: 'fa-exclamation-triangle',
        info: 'fa-info-circle'
    };
    
    const toast = document.createElement('div');
    toast.className = `toast-notification fixed top-4 right-4 z-50 ${colors[type] || 'bg-gray-700'} text-white px-5 py-3 rounded-xl shadow-lg max-w-md flex items-center gap-3 animate-slide-in`;
    toast.innerHTML = `
        <i class="fas ${icons[type] || 'fa-info-circle'} text-lg"></i>
        <span class="text-sm">${message}</span>
        <button onclick="this.parentElement.remove()" class="ml-auto text-white/70 hover:text-white">
            <i class="fas fa-times"></i>
        </button>
    `;
    document.body.appendChild(toast);
    
    setTimeout(() => {
        toast.classList.add('animate-slide-out');
        setTimeout(() => toast.remove(), 300);
    }, 5000);
}

// ==================== HTML ESCAPE HELPER ====================
function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}
