async function loadAnnouncements() {
    try {
        const res = await fetch('/api/announcements');
        if (res.ok) {
            const data = await res.json();
            announcementsData = data.success ? data.announcements || [] : [];
        } else {
            console.warn('Failed to load announcements, using empty array');
            announcementsData = [];
        }
    } catch (error) {
        console.error('Error loading announcements:', error);
        announcementsData = [];
    }
}

