// ========== LOAD CHAT CONTACTS ==========
async function loadChatContacts(filter = 'all') {
    try {
        const url = filter === 'all' ? '/api/chat/contacts' : `/api/chat/contacts?type=${filter}`;
        const res = await fetch(url);
        if (res.ok) {
            window.chatContacts = await res.json();
            renderChatContacts(window.chatContacts);
        } else {
            console.warn('Failed to load contacts:', res.status);
            showToast('Could not load contacts', 'warning');
        }
    } catch (e) {
        console.error('Error loading contacts:', e);
        showToast('Error loading contacts - make sure server is running', 'error');
    }
}

// ========== RENDER CHAT CONTACTS ==========
function renderChatContacts(contacts) {
    const container = document.getElementById('chatContactList');
    if (!container) return;
    
    if (!contacts || contacts.length === 0) {
        container.innerHTML = `
            <div class="flex flex-col items-center justify-center h-full text-gray-400">
                <i class="fas fa-users text-4xl text-gray-300 mb-2"></i>
                <p class="text-sm">No contacts found</p>
                <p class="text-xs">Try changing the filter</p>
            </div>
        `;
        return;
    }
    
    // Get unread counts
    fetch('/api/chat/unread')
        .then(res => {
            if (!res.ok) throw new Error('Failed to fetch unread');
            return res.json();
        })
        .then(data => {
            const unreadByContact = data.unreadByContact || {};
            
            container.innerHTML = contacts.map(contact => {
                const unread = unreadByContact[contact.id] || 0;
                const isActive = window.currentChatContact?.id === contact.id;
                const initials = contact.name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);
                const avatarColor = getAvatarColor(contact.id);
                
                return `
                    <div class="chat-contact-item flex items-center gap-3 p-3 hover:bg-gray-50 cursor-pointer transition border-b border-gray-100 ${isActive ? 'bg-green-50' : ''}"
                         onclick="selectChatContact('${contact.id}')" data-contact-id="${contact.id}">
                        <div class="relative flex-shrink-0">
                            <div class="w-10 h-10 rounded-full flex items-center justify-center text-white font-bold text-sm" style="background: ${avatarColor}">
                                ${contact.avatar ? `<img src="${contact.avatar}" class="w-full h-full rounded-full object-cover" alt="${contact.name}">` : initials}
                            </div>
                            ${contact.isOnline ? '<span class="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white"></span>' : ''}
                        </div>
                        <div class="flex-1 min-w-0">
                            <div class="flex justify-between items-start">
                                <span class="font-medium text-gray-800 truncate">${contact.name}</span>
                                ${unread > 0 ? `<span class="bg-green-500 text-white text-xs px-2 py-0.5 rounded-full flex-shrink-0">${unread}</span>` : ''}
                            </div>
                            <div class="flex items-center gap-2">
                                <span class="text-xs text-gray-400">${getContactTypeLabel(contact.type)}</span>
                                ${contact.phone ? `<span class="text-xs text-gray-300">• ${contact.phone}</span>` : ''}
                            </div>
                        </div>
                    </div>
                `;
            }).join('');
        })
        .catch(e => {
            console.warn('Error loading unread counts:', e);
            // Fallback: render without unread counts
            container.innerHTML = contacts.map(contact => {
                const isActive = window.currentChatContact?.id === contact.id;
                const initials = contact.name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);
                const avatarColor = getAvatarColor(contact.id);
                
                return `
                    <div class="chat-contact-item flex items-center gap-3 p-3 hover:bg-gray-50 cursor-pointer transition border-b border-gray-100 ${isActive ? 'bg-green-50' : ''}"
                         onclick="selectChatContact('${contact.id}')" data-contact-id="${contact.id}">
                        <div class="relative flex-shrink-0">
                            <div class="w-10 h-10 rounded-full flex items-center justify-center text-white font-bold text-sm" style="background: ${avatarColor}">
                                ${contact.avatar ? `<img src="${contact.avatar}" class="w-full h-full rounded-full object-cover" alt="${contact.name}">` : initials}
                            </div>
                            ${contact.isOnline ? '<span class="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white"></span>' : ''}
                        </div>
                        <div class="flex-1 min-w-0">
                            <span class="font-medium text-gray-800 truncate">${contact.name}</span>
                            <div class="flex items-center gap-2">
                                <span class="text-xs text-gray-400">${getContactTypeLabel(contact.type)}</span>
                                ${contact.phone ? `<span class="text-xs text-gray-300">• ${contact.phone}</span>` : ''}
                            </div>
                        </div>
                    </div>
                `;
            }).join('');
        });
}

// ========== FILTER CHAT CONTACTS ==========
function filterChatContacts(filter) {
    document.querySelectorAll('.chat-filter-btn').forEach(btn => {
        const isActive = btn.dataset.filter === filter;
        btn.classList.toggle('bg-white', isActive);
        btn.classList.toggle('shadow-sm', isActive);
        btn.classList.toggle('text-green-600', isActive);
        btn.classList.toggle('text-gray-600', !isActive);
    });
    loadChatContacts(filter);
}

// ========== SEARCH CHAT CONTACTS ==========
function searchChatContacts(query) {
    const container = document.getElementById('chatContactList');
    if (!container) return;
    const items = container.querySelectorAll('.chat-contact-item');
    const searchLower = query.toLowerCase().trim();
    items.forEach(item => {
        const name = item.querySelector('.font-medium')?.textContent?.toLowerCase() || '';
        item.style.display = (!searchLower || name.includes(searchLower)) ? '' : 'none';
    });
}

// ========== SELECT CHAT CONTACT ==========
async function selectChatContact(contactId) {
    const contact = window.chatContacts.find(c => c.id === contactId);
    if (!contact) return;
    
    window.currentChatContact = contact;
    
    // Update header
    const nameEl = document.getElementById('chatContactName');
    const statusEl = document.getElementById('chatContactStatus');
    if (nameEl) nameEl.textContent = contact.name;
    if (statusEl) {
        const typeLabel = getContactTypeLabel(contact.type);
        const phone = contact.phone ? ` • ${contact.phone}` : '';
        statusEl.textContent = `${typeLabel}${phone}`;
    }
    
    // Update header avatar
    const headerAvatar = document.querySelector('#chatHeader .w-10.h-10');
    if (headerAvatar) {
        const initials = contact.name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);
        const color = getAvatarColor(contact.id);
        if (contact.avatar) {
            headerAvatar.innerHTML = `<img src="${contact.avatar}" class="w-full h-full rounded-full object-cover" alt="${contact.name}">`;
        } else {
            headerAvatar.innerHTML = initials;
            headerAvatar.style.background = color;
        }
    }
    
    // Load messages
    await loadChatMessages(contactId);
    
    // Mark messages as read
    markMessagesAsRead(contactId);
    
    // Update contact list highlight
    document.querySelectorAll('.chat-contact-item').forEach(el => {
        el.classList.toggle('bg-green-50', el.dataset.contactId === contactId);
    });
    
    updateUnreadCount();
}

// ========== LOAD CHAT MESSAGES ==========
async function loadChatMessages(contactId, loadMore = false) {
    try {
        const limit = window.chatMessageLimit || 50;
        let url = `/api/chat/messages/${contactId}?limit=${limit}`;
        if (loadMore && window.chatMessages.length > 0) {
            const oldest = window.chatMessages[0];
            url += `&before=${oldest.timestamp}`;
        }
        
        const res = await fetch(url);
        if (res.ok) {
            const messages = await res.json();
            if (loadMore) {
                window.chatMessages = [...messages, ...window.chatMessages];
            } else {
                window.chatMessages = messages;
            }
            renderChatMessages();
        } else {
            console.warn('Failed to load messages:', res.status);
        }
    } catch (e) {
        console.error('Error loading messages:', e);
        // Don't show toast on every poll failure, only on first load
        if (!window.chatMessages.length) {
            showToast('Error loading messages - make sure server is running', 'error');
        }
    }
}

// ========== RENDER CHAT MESSAGES ==========
function renderChatMessages() {
    const container = document.getElementById('chatMessages');
    if (!container) return;
    
    if (!window.chatMessages || window.chatMessages.length === 0) {
        container.innerHTML = `
            <div class="flex justify-center items-center h-full text-gray-400">
                <div class="text-center">
                    <i class="fas fa-comment-dots text-4xl text-gray-300 mb-3 block"></i>
                    <p class="text-sm">No messages yet</p>
                    <p class="text-xs text-gray-300">Start a conversation with ${window.currentChatContact?.name || 'this contact'}</p>
                </div>
            </div>
        `;
        return;
    }
    
    let html = '';
    let lastDate = '';
    
    window.chatMessages.forEach((msg) => {
        const msgDate = new Date(msg.timestamp);
        const dateStr = msgDate.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
        const timeStr = msgDate.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
        const isAdmin = msg.sender === 'admin';
        const isNewDay = dateStr !== lastDate;
        lastDate = dateStr;
        
        let content = '';
        if (msg.message) {
            content += `<p class="text-sm whitespace-pre-wrap break-words">${escapeHtml(msg.message)}</p>`;
        }
        
        if (msg.attachment) {
            const att = msg.attachment;
            if (msg.messageType === 'image' || att.mimetype?.startsWith('image/')) {
                content += `<div class="mt-1"><img src="${att.url || att.path}" class="max-w-xs max-h-48 rounded-lg object-cover" alt="Image"></div>`;
            } else if (msg.messageType === 'audio' || att.mimetype?.startsWith('audio/')) {
                content += `<div class="mt-1"><audio controls class="w-full max-w-xs"><source src="${att.url || att.path}" type="${att.mimetype}"></audio></div>`;
            } else if (msg.messageType === 'video' || att.mimetype?.startsWith('video/')) {
                content += `<div class="mt-1"><video controls class="max-w-xs max-h-48 rounded-lg"><source src="${att.url || att.path}" type="${att.mimetype}"></video></div>`;
            } else {
                content += `<div class="mt-1 flex items-center gap-2 text-sm text-blue-600 hover:underline"><i class="fas fa-file"></i> <a href="${att.url || att.path}" target="_blank">${att.filename}</a></div>`;
            }
        }
        
        html += `
            ${isNewDay ? `<div class="text-center my-3"><span class="text-xs bg-gray-200 text-gray-600 px-3 py-1 rounded-full">${dateStr}</span></div>` : ''}
            <div class="flex ${isAdmin ? 'justify-end' : 'justify-start'} mb-2">
                <div class="max-w-[70%] ${isAdmin ? 'bg-green-500 text-white' : 'bg-white border border-gray-200'} rounded-2xl px-4 py-2 shadow-sm">
                    ${!isAdmin ? `<div class="text-xs font-semibold text-green-600 mb-1">${window.currentChatContact?.name || 'Contact'}</div>` : ''}
                    ${content}
                    <div class="text-[10px] ${isAdmin ? 'text-green-100' : 'text-gray-400'} mt-1 flex items-center gap-1 justify-end">
                        ${timeStr}
                        ${isAdmin ? `<i class="fas fa-check-double ${msg.read ? 'text-blue-300' : 'text-green-300'} text-[8px]"></i>` : ''}
                    </div>
                </div>
            </div>
        `;
    });
    
    container.innerHTML = html;
    setTimeout(() => { container.scrollTop = container.scrollHeight; }, 50);
}

// ========== SEND CHAT MESSAGE ==========
async function sendChatMessage() {
    const input = document.getElementById('chatMessageInput');
    const message = input?.value?.trim();
    
    if (!message) {
        showToast('Please type a message', 'warning');
        return;
    }
    
    if (!window.currentChatContact) {
        showToast('Please select a contact first', 'warning');
        return;
    }
    
    const sendBtn = document.getElementById('chatSendBtn');
    sendBtn.disabled = true;
    sendBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';
    
    try {
        const res = await fetch('/api/chat/messages', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                contactId: window.currentChatContact.id,
                message: message,
                sender: 'admin',
                messageType: 'text'
            })
        });
        
        if (res.ok) {
            input.value = '';
            autoResizeChatInput(input);
            await loadChatMessages(window.currentChatContact.id);
            updateUnreadCount();
        } else {
            const error = await res.json();
            showToast('Error: ' + (error.error || 'Failed to send message'), 'error');
        }
    } catch (e) {
        console.error('Error sending message:', e);
        showToast('Error sending message - make sure server is running', 'error');
    } finally {
        sendBtn.disabled = false;
        sendBtn.innerHTML = '<i class="fas fa-paper-plane text-lg"></i>';
    }
}

// ========== MARK MESSAGES AS READ ==========
async function markMessagesAsRead(contactId) {
    try {
        await fetch(`/api/chat/messages/${contactId}/read`, { method: 'PUT' });
        updateUnreadCount();
    } catch (e) {
        console.warn('Error marking messages as read:', e);
    }
}

// ========== UPDATE UNREAD COUNT ==========
async function updateUnreadCount() {
    try {
        const res = await fetch('/api/chat/unread');
        if (res.ok) {
            const data = await res.json();
            window.chatUnreadCount = data.totalUnread || 0;
            const badge = document.getElementById('chatUnreadBadge');
            if (badge) {
                if (window.chatUnreadCount > 0) {
                    badge.textContent = `${window.chatUnreadCount} unread`;
                    badge.classList.remove('hidden');
                } else {
                    badge.classList.add('hidden');
                }
            }
        }
    } catch (e) {
        console.warn('Error updating unread count:', e);
    }
}

// ========== START CHAT POLLING ==========
function startChatPolling() {
    if (window.chatPollingInterval) {
        clearInterval(window.chatPollingInterval);
    }
    
    window.chatPollingInterval = setInterval(() => {
        if (window.currentChatContact) {
            loadChatMessages(window.currentChatContact.id);
            updateUnreadCount();
        }
    }, 5000);
}

// ========== REFRESH CHAT ==========
function refreshChat() {
    if (window.currentChatContact) {
        loadChatMessages(window.currentChatContact.id);
    }
    updateUnreadCount();
    showToast('Chat refreshed', 'success');
}

// ========== CLEAR CHAT ==========
function clearChat() {
    if (!window.currentChatContact) return;
    if (!confirm(`Clear all messages with ${window.currentChatContact.name}?`)) return;
    showToast('Chat cleared (demo)', 'info');
}

// ========== ATTACHMENT FUNCTIONS ==========
function toggleAttachmentMenu() {
    const menu = document.getElementById('attachmentMenu');
    if (menu) menu.classList.toggle('hidden');
}

function attachFile(type) {
    const input = document.createElement('input');
    input.type = 'file';
    if (type === 'image') input.accept = 'image/*';
    else if (type === 'audio') input.accept = 'audio/*';
    else if (type === 'video') input.accept = 'video/*';
    else input.accept = '.pdf,.doc,.docx,.txt,.xls,.xlsx';
    
    input.onchange = function(e) {
        const file = e.target.files[0];
        if (file) {
            const preview = document.getElementById('attachmentPreview');
            const nameEl = document.getElementById('attachmentPreviewName');
            if (preview && nameEl) {
                preview.classList.remove('hidden');
                nameEl.textContent = `📎 ${file.name} (${(file.size / 1024).toFixed(1)} KB)`;
                preview.dataset.attachment = file.name;
                preview.dataset.file = file;
            }
            showToast(`File "${file.name}" attached`, 'success');
        }
        document.getElementById('attachmentMenu')?.classList.add('hidden');
    };
    input.click();
}

function clearAttachment() {
    const preview = document.getElementById('attachmentPreview');
    if (preview) {
        preview.classList.add('hidden');
        preview.dataset.attachment = '';
        preview.dataset.file = '';
    }
}

// ========== EMOJI PICKER ==========
function toggleEmojiPicker() {
    const input = document.getElementById('chatMessageInput');
    if (!input) return;
    
    const emojis = ['😊', '😂', '❤️', '👍', '🙏', '🎉', '🔥', '💯', '✅', '📚', '🏆', '⭐', '💪', '🤝', '👏'];
    const picker = document.createElement('div');
    picker.className = 'absolute bottom-full left-0 mb-2 bg-white rounded-xl shadow-lg border border-gray-200 p-2 w-64 z-50';
    picker.id = 'emojiPicker';
    picker.innerHTML = emojis.map(e => 
        `<button onclick="insertEmoji('${e}')" class="text-2xl p-1 hover:bg-gray-100 rounded transition">${e}</button>`
    ).join('');
    
    const inputRect = input.getBoundingClientRect();
    picker.style.position = 'fixed';
    picker.style.bottom = (window.innerHeight - inputRect.top + 10) + 'px';
    picker.style.left = (inputRect.left + 40) + 'px';
    
    document.body.appendChild(picker);
    
    setTimeout(() => {
        document.addEventListener('click', function closePicker(e) {
            if (!picker.contains(e.target) && e.target.id !== 'emojiPicker') {
                picker.remove();
                document.removeEventListener('click', closePicker);
            }
        });
    }, 10);
}

function insertEmoji(emoji) {
    const input = document.getElementById('chatMessageInput');
    if (input) {
        const start = input.selectionStart;
        const end = input.selectionEnd;
        const text = input.value;
        input.value = text.substring(0, start) + emoji + text.substring(end);
        input.focus();
        input.selectionStart = input.selectionEnd = start + emoji.length;
        autoResizeChatInput(input);
    }
    document.getElementById('emojiPicker')?.remove();
}

// ========== TYPING INDICATOR ==========
function checkTyping() {
    if (window.typingTimeout) clearTimeout(window.typingTimeout);
    
    if (window.currentChatContact) {
        fetch('/api/chat/typing', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                contactId: window.currentChatContact.id,
                isTyping: true
            })
        }).catch(() => {});
    }
    
    window.typingTimeout = setTimeout(() => {
        if (window.currentChatContact) {
            fetch('/api/chat/typing', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    contactId: window.currentChatContact.id,
                    isTyping: false
                })
            }).catch(() => {});
        }
    }, 2000);
}

// ========== HANDLE CHAT KEYDOWN ==========
function handleChatKeydown(event) {
    if (event.key === 'Enter' && !event.shiftKey) {
        event.preventDefault();
        sendChatMessage();
    }
}

// ========== AUTO RESIZE CHAT INPUT ==========
function autoResizeChatInput(input) {
    input.style.height = 'auto';
    input.style.height = Math.min(input.scrollHeight, 128) + 'px';
}

// ========== HELPER FUNCTIONS ==========
function getContactTypeLabel(type) {
    const labels = {
        'teacher': '👨‍🏫 Teacher',
        'parent': '👨‍👩‍👦 Parent',
        'student': '🎓 Student',
        'director': '👔 Director'
    };
    return labels[type] || type || 'Contact';
}

function getAvatarColor(id) {
    const colors = ['#4F46E5', '#7C3AED', '#EC4899', '#EF4444', '#F59E0B', '#10B981', '#3B82F6', '#8B5CF6'];
    let hash = 0;
    for (let i = 0; i < id.length; i++) {
        hash = id.charCodeAt(i) + ((hash << 5) - hash);
    }
    return colors[Math.abs(hash) % colors.length];
}

function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

// Clean up polling on page unload
window.addEventListener('beforeunload', function() {
    if (window.chatPollingInterval) {
        clearInterval(window.chatPollingInterval);
    }
});

console.log('✅ Chat/Contact UI loaded');